import { cloneData } from '../core/clone-data';
import { FloorId } from '../world/mansion';
import { newLevelFile, sameTile, type LevelFile, type LevelFloor, type TerrainCode, type TilePosition } from '../application/levels/format';

const historyLimit = 40;

export class LevelDraft {
    level = newLevelFile();
    private readonly previous: LevelFile[] = [];
    private readonly next: LevelFile[] = [];

    get canUndo() { return this.previous.length > 0; }
    get canRedo() { return this.next.length > 0; }

    replace(level: LevelFile) {
        this.previous.push(this.level);
        if (this.previous.length > historyLimit) this.previous.shift();
        this.next.length = 0;
        this.level = level;
    }

    edit(change: (level: LevelFile) => void) {
        const updated = cloneData(this.level);
        change(updated);
        this.replace(updated);
    }

    undo() {
        const level = this.previous.pop();
        if (!level) return;
        this.next.push(this.level);
        this.level = level;
    }

    redo() {
        const level = this.next.pop();
        if (!level) return;
        this.previous.push(this.level);
        this.level = level;
    }
}

export function paintTerrain(floor: LevelFloor, [x, y]: TilePosition, code: TerrainCode) {
    const row = floor.terrain.length - y - 1;
    floor.terrain[row] = floor.terrain[row].slice(0, x) + code + floor.terrain[row].slice(x + 1);
}

export function removeStair(level: LevelFile, from: FloorId, to: FloorId) {
    for (const floor of level.floors) {
        if (floor.id === from) floor.stairs = floor.stairs.filter(stair => stair.to !== to);
        if (floor.id === to) floor.stairs = floor.stairs.filter(stair => stair.to !== from);
    }
}

export function eraseObjects(level: LevelFile, floor: LevelFloor, at: TilePosition) {
    floor.items = floor.items.filter(item => !sameTile(item.at, at));
    if (floor.platforms) floor.platforms = floor.platforms.filter(pos => !sameTile(pos, at));
    floor.guards = floor.guards.filter(guard => !sameTile(guard.patrol[0], at));
    for (const stair of floor.stairs) if (sameTile(stair.at, at)) removeStair(level, floor.id, stair.to);
    if (floor.id === FloorId.First) level.exits = level.exits.filter(exit => !sameTile(exit, at));
}

export function resizeFloor(level: LevelFile, floor: LevelFloor, width: number, height: number) {
    const inside = ([x, y]: TilePosition) => x < width && y < height;
    const old = floor.terrain;
    floor.terrain = Array.from({length: height}, (_, row) => {
        const line = old[old.length - height + row] ?? '';
        return line.slice(0, width).padEnd(width, '#');
    });
    floor.items = floor.items.filter(item => inside(item.at));
    if (floor.platforms) floor.platforms = floor.platforms.filter(inside);
    floor.guards = floor.guards.filter(guard => guard.patrol.every(inside));
    for (const stair of floor.stairs) if (!inside(stair.at)) removeStair(level, floor.id, stair.to);
    if (floor.id === FloorId.First) {
        level.exits = level.exits.filter(at => inside(at) && isEdge(floor, at));
        if (!inside(level.start)) {
            const [x, y] = level.start;
            level.start = [Math.min(x, width - 1), Math.min(y, height - 1)];
        }
    }
}

export function isEdge(floor: LevelFloor, [x, y]: TilePosition): boolean {
    return x === 0 || y === 0 || x === floor.terrain[0].length - 1 || y === floor.terrain.length - 1;
}
