import { vec2 } from '../my-matrix';
import type { GameMap,Item,Player } from '../world/game-map';
import { isWindowTerrainType,ItemType,LevelType,TerrainType } from '../world/game-map';
import type { GuardData as Guard } from '../world/guard';
import { removeWorldItems } from '../world/mutations';
import { isLockedDoorItemType,isPlinthTreasure } from '../world/tiles';
import { directionArrowCharacter,StepType } from './commands';
import { makeNoise,NoiseType } from './noise';
import type { SimulationState } from './state';
import { advanceTime,preTurn } from './turn';

export function canCollectLootAt(state: SimulationState, pos: vec2): boolean {
    return state.gameMap.hasLootAt(pos) &&
        !state.gameMap.items.find((item)=>item.type === ItemType.TreasureLock && item.pos.equals(pos));
}

export function collectLoot(state: SimulationState, pos: vec2, posFlyToward: vec2): boolean {
    const itemsCollected = state.gameMap.collectLootAt(pos);
    if (itemsCollected.length === 0) {
        return false;
    }
    let coinCollected = false;
    let healthCollected = false;
    for (const item of itemsCollected) {
        let animType = item.type;
        let offset = 0;
        let numGained = 1;
        if (item.type === ItemType.Coin) {
            ++state.player.loot;
            ++state.lootStolen;
            coinCollected = true;
        } else if (isPlinthTreasure(item.type)) {
            coinCollected = true;
            ++state.treasureStolen;
            for (const treasureInfo of state.gameMap.treasures) {
                if (treasureInfo.posTreasure.equals(item.pos)) {
                    treasureInfo.stolen = true;
                    if (state.gameMapRoughPlans[state.level].levelType === LevelType.Fortress &&
                        state.level === state.gameMapRoughPlans.length - 1) {
                        makeNoise(state, NoiseType.Alarm,
                            pos[0]-state.player.pos[0], pos[1]-state.player.pos[1], 46, true);
                    }
                }
            }
            offset = 0.5;
        } else if (item.type === ItemType.VaultTreasureBox) {
            coinCollected = true;
            animType = ItemType.Coin;
            numGained = 3;
            state.gameMap.items.push({type:ItemType.LootedVaultTreasureBox, pos:vec2.clone(pos)});
            state.feedback?.vaultGold(vec2.clone(item.pos), 0.15);
            makeNoise(state, NoiseType.Alarm,
                pos[0]-state.player.pos[0], pos[1]-state.player.pos[1], 46, true);
        } else if (item.type === ItemType.Health) {
            state.feedback?.enlargeHealthBar();
            if (state.player.health >= state.player.healthMax) {
                ++state.levelStats.extraFoodCollected;
            } else {
                ++state.player.health;
                state.feedback?.flashHeart(state.player.health - 1);
            }
            healthCollected = true;
        }
        state.feedback?.lootFly(animType, vec2.clone(item.pos), vec2.clone(posFlyToward), offset, numGained);
    }

    if (coinCollected) {
        state.feedback?.sound('coin', 1.0);
    }
    if (healthCollected) {
        state.feedback?.sound('food', 0.25);
    }

    return true;
}

export function collectGuardLoot(state: SimulationState, player:Player, guard:Guard, posNew:vec2, animDelay:number=0) {
    let pickedItem:Item|null = null;
    player.interactionTarget = null;
    if (guard.hasPurse) {
        guard.hasPurse = false;
        player.loot += 1;
        state.lootStolen += 1;
        pickedItem = {pos:vec2.clone(guard.pos), type:ItemType.Coin};
    }
    if (guard.hasVaultKey) {
        guard.hasVaultKey = false;
        player.hasVaultKey = true;
        pickedItem = {pos:vec2.clone(guard.pos), type:ItemType.Key};
    }
    if (pickedItem) {
        state.feedback?.guardLootFly(pickedItem, vec2.clone(posNew), animDelay);

        if (pickedItem.type===ItemType.Key) {
            state.feedback?.sound('grabKey', 1.0);
        } else {
            state.feedback?.sound('coin', 1.0);
        }
    }
}

export function pushOrSwapGuard(state: SimulationState, guard: Guard) {
    const posGuardOld = vec2.clone(guard.pos);
    const posPlayer = vec2.clone(state.player.pos);

    // Try to push the guard away from the player. If that doesn't work,
    //  exchange places with the player.

    const posGuardNew = vec2.create();
    vec2.subtract(posGuardNew, posGuardOld, posPlayer);
    vec2.add(posGuardNew, posGuardNew, posGuardOld);

    let pulledGuard = false;

    if (blocksPushedGuard(state, posGuardNew)) {
        if (state.gameMap.isLadderSpace(posPlayer)) return;
        vec2.copy(posGuardNew, posPlayer);
        pulledGuard = true;
    }

    // Update guard position
    vec2.copy(guard.pos, posGuardNew);

    // If guard ends up in water he wakes up immediately
    if (state.gameMap.cells.atVec(guard.pos).type === TerrainType.GroundWater) {
        guard.modeTimeout = 0;
    }

    state.feedback?.guardSlide(guard, posGuardOld, pulledGuard);
}

export function moveGuardToPlayerPos(state: SimulationState, guard: Guard) {
    // Update guard position
    const posGuardOld = vec2.clone(guard.pos);
    vec2.copy(guard.pos, state.player.pos);

    state.feedback?.guardSlide(guard, posGuardOld, true);
}

function blocksPushedGuard(state: SimulationState, posGuardNew: vec2): boolean {
    if (posGuardNew[0] < 0 ||
        posGuardNew[1] < 0 ||
        posGuardNew[0] >= state.gameMap.cells.sizeX ||
        posGuardNew[1] >= state.gameMap.cells.sizeY) {
        return true;
    }
    if (state.gameMap.cells.atVec(posGuardNew).moveCost === Infinity) {
        return true;
    }
    if (state.gameMap.guards.find((guard)=>guard.pos.equals(posGuardNew))) {
        return true;
    }

    for (const item of state.gameMap.items.filter((item) => item.pos.equals(posGuardNew))) {
        switch (item.type) {
        case ItemType.PortcullisEW:
        case ItemType.PortcullisNS:
            return true;

        case ItemType.LockedDoorEW:
        case ItemType.LockedDoorNS:
            if (!state.player.hasVaultKey) {
                return true;
            }
            break;
        }
    }

    return false;
}

export function isLockedDoorAtPos(gameMap: GameMap, pos: vec2): boolean {
    return gameMap.items.some(item => item.pos.equals(pos) && isLockedDoorItemType(item.type));
}

export function bumpAnim(state: SimulationState, dx: number, dy: number) {
    state.feedback?.bump(dx, dy);
}

export function bumpFail(state: SimulationState, dx: number, dy: number) {
    state.feedback?.sound('footstepTile', 0.1);
    bumpAnim(state, dx, dy);
}

export function tryMoveAgainstBlockedSquare(state: SimulationState, dx: number, dy: number, stepType: StepType) {
    if (stepType === StepType.AttemptedLeap) {
        if (state.player.preNoisy && dx === state.player.noiseOffset[0] && dy === state.player.noiseOffset[1]) {
            preTurn(state);
            state.player.interactionTarget = null;
            bumpAnim(state, dx*1.25, dy*1.25);
            state.feedback?.jolt(dx, dy);
            makeNoise(state, NoiseType.BangDoor, dx, dy);
            advanceTime(state);
            if (state.gameMapRoughPlans[state.level].difficulty === 0) {
                state.feedback?.notify('Noise\nattracts\npeople', state.player.pos);
            }
        } else {
            state.player.preNoisy = false;
            bumpFail(state, dx, dy);
        }
        return;
    }

    // See if we are bumping a bookshelf; display the book title, if so.
    const x = state.player.pos[0] + dx;
    const y = state.player.pos[1] + dy;
    const item = state.gameMap.items.find(item =>
        item.pos[0] === x &&
        item.pos[1] === y &&
        (item.type === ItemType.Bookshelf || item.type === ItemType.Note));
    if (item === undefined) {
        state.player.preNoisy = true;
        state.player.noiseOffset[0] = dx;
        state.player.noiseOffset[1] = dy;
        state.player.interactionTarget = null;
        if (state.gameMapRoughPlans[state.level].difficulty === 0 && !state.experiencedPlayer && !isWindowTerrainType(state.gameMap.cells.at(x, y).type)) {
            state.feedback?.notify('Make Noise:\nShift+' + directionArrowCharacter(dx, dy), state.player.pos);
        }
        bumpFail(state, dx, dy);
        return;
    }

    preTurn(state);

    const firstBump = !(state.player.interactionTarget?.kind === 'bookshelf' && state.player.interactionTarget.item === item);
    state.player.interactionTarget = firstBump && state.gameMap.treasures.some(treasure => treasure.switches.some(s => s.equals(item.pos))) ? {kind:'bookshelf',item} : null;

    if (!state.gameMap.cells.at(x, y).lit) {
        state.player.lightActive = true;
    }

    bumpAnim(state, dx, dy);
    advanceTime(state);

    // advanceTime clears state.player.preNoisy. Set it here so player can bang on bookshelves to make noise.

    state.player.preNoisy = true;
    state.player.noiseOffset[0] = dx;
    state.player.noiseOffset[1] = dy;

    if (firstBump) {
        let title = state.gameMap.bookTitle.get(item);
        if (title === undefined) {
            title = 'Untitled';
        }
        if (item.type === ItemType.Bookshelf) {
            title = '"' + title + '"';
        }
        state.feedback?.notify(title, state.player.pos);
        return;
    }

    enum SwitchResult {
        None,
        Completed,
        Reset,
        Advance,
        Complete,
    };

    let switchResult: SwitchResult = SwitchResult.None;

    for (const treasure of state.gameMap.treasures) {
        const secretSwitchIndex = treasure.switches.findIndex(s => s.equals(item.pos));

        if (secretSwitchIndex < 0) {
            continue;
        }

        if (treasure.numSwitchesUsed >= treasure.switches.length) {
            switchResult = Math.max(switchResult, SwitchResult.Completed);
        } else if (secretSwitchIndex === treasure.numSwitchesUsed) {
            ++treasure.numSwitchesUsed;
            if (treasure.numSwitchesUsed >= treasure.switches.length) {
                const gates = state.gameMap.items.filter(itemLock=>(itemLock.type===ItemType.TreasureLock && itemLock.pos.equals(treasure.posTreasure)));
                removeWorldItems(state.gameMap, itemLock => itemLock.type === ItemType.TreasureLock && itemLock.pos.equals(treasure.posTreasure));
                state.gameMap.cells.atVec(treasure.posTreasure).blocksPlayerMove = false;
                for (let gate of gates) {
                    state.feedback?.treasureGate(gate);
                }
                switchResult = Math.max(switchResult, SwitchResult.Complete);
            } else {
                switchResult = Math.max(switchResult, SwitchResult.Advance);
            }
        } else if (secretSwitchIndex === 0) {
            treasure.numSwitchesUsed = 1;
            switchResult = Math.max(switchResult, SwitchResult.Advance);
        } else {
            treasure.numSwitchesUsed = 0;
            switchResult = Math.max(switchResult, SwitchResult.Reset);
        }
    }

    switch (switchResult) {
        case SwitchResult.None:
            break;
        case SwitchResult.Completed:
        case SwitchResult.Reset:
            state.feedback?.sound('switchReset', 0.5);
            state.feedback?.notify('(clunk)', state.player.pos);
            break;
        case SwitchResult.Advance:
            state.feedback?.sound('switchProgress', 0.5);
            state.feedback?.notify('(click)', state.player.pos);
            break;
        case SwitchResult.Complete:
            state.feedback?.sound('switchSuccess', 0.5);
            state.feedback?.notify('(rumble)', state.player.pos);
            state.feedback?.jolt(dx, dy);
            break;
    }
}
