import { vec2 } from '../my-matrix';
import type { SimulationState } from './state';

export enum NoiseType {
    Creak,
    Splash,
    Thud,
    Alarm,
    BangDoor,
    BangChair,
}

export function makeNoise(state: SimulationState, noiseType: NoiseType, dx: number, dy: number, radius:number = 23, makeAngry:boolean = false) {
    const { gameMap: map, player, feedback } = state;
    // Sound presentation uses the struck object. Existing attraction targets the thief.
    const origin = vec2.fromValues(player.pos[0] + dx, player.pos[1] + dy);
    const attraction = vec2.clone(player.pos);
    player.noisy = true;
    player.noiseOffset[0] = dx;
    player.noiseOffset[1] = dy;

    switch (noiseType) {
        case NoiseType.Creak:
            feedback?.sound('footstepCreaky', 0.6);
            feedback?.notify('Creak!', player.pos);
            break;
        case NoiseType.Splash:
            feedback?.sound('splash', 0.5);
            feedback?.notify('Splash!', player.pos);
            break;
        case NoiseType.Thud:
            // Sound effect currently played in executeLeapAttack
            feedback?.notify('Thud!', player.pos);
            break;
        case NoiseType.Alarm:
            feedback?.sound('treasureAlarm', 1.0);
            const pos = origin;
            feedback?.holdNotification('ALARM! ALARM! ALARM!', pos);
            break;
        case NoiseType.BangDoor:
            feedback?.sound('thump', 0.5);
            feedback?.notify('Thud!', player.pos);
            break;
        case NoiseType.BangChair:
            // TODO: sound effect
            break;
    }

    let foundClosestGuard = false;

    for (const guard of map.guardsInEarshot(attraction, radius)) {
        guard.heardThief = true;
        if (!foundClosestGuard) {
            foundClosestGuard = true;
            guard.heardThiefClosest = true;
            guard.heardAlarm = noiseType === NoiseType.Alarm;
        }
        if (makeAngry) {
            guard.angry = true;
        }
    }
}
