import { vec2 } from '../my-matrix';
import { directionArrowCharacter } from '../simulation/commands';
import { canLeapToPos } from '../simulation/movement-rules';
import type { Item } from '../world/game-map';
import { isDoorItemType,ItemType,TerrainType } from '../world/game-map';
import type { GuardData as Guard } from '../world/guard';
import { GuardMode } from '../world/guard-mode';
import { isRelaxedGuardMode } from '../world/guard-policy';
import { isHingedDoorTerrainType } from '../world/tiles';
import type { State } from './state';

function adjacentPositions(pos0: vec2, pos1: vec2): boolean {
    const dx = pos1[0] - pos0[0];
    const dy = pos1[1] - pos0[1];
    return Math.abs(dx) + Math.abs(dy) === 1;
}

export function showMoveTutorialNotifications(state: State, posPrev: vec2) {
    if (state.popups.isNotificationVisible()) {
        return;
    }

    const level = state.game.gameMapRoughPlans[state.game.level].difficulty;

    if (level === 3) {
        runPickpocketTutorial(state);
        return;
    }

    if (state.game.experiencedPlayer) {
        return;
    }

    if (level === 2 && !state.game.hasEnteredMansion && state.game.player.pos.equals(state.game.gameMap.playerStartPos)) {
        const pos = vec2.create();
        vec2.copy(pos, state.game.player.pos);
        pos[1] += 1;
        state.popups.setNotificationHold('Zoom view: [ or ]', pos);
        return;
    }

    if (level === 1 && !state.game.hasEnteredMansion) {
        let sqdistGuardNearest = Infinity;
        let guardNearest: Guard | undefined = undefined;
        for (const guard of state.game.gameMap.guards) {
            const sqdistGuard = vec2.squaredDistance(guard.pos, state.game.player.pos);
            if (sqdistGuard < sqdistGuardNearest) {
                sqdistGuardNearest = sqdistGuard;
                guardNearest = guard;
            }
        }

        if (guardNearest !== undefined && sqdistGuardNearest < 16) {
            state.popups.setNotificationHold('Wait: Z\nor Period/Space', guardNearest.pos);
        }
        return;
    }

    if (level !== 0) {
        return;
    }

    const adjacentLoot = state.game.gameMap.items.find(item => item.type === ItemType.Coin && adjacentPositions(item.pos, state.game.player.pos));
    if (adjacentLoot !== undefined) {
        state.popups.setNotificationHold('Loot: ' + directionArrowCharacter(adjacentLoot.pos[0] - state.game.player.pos[0], adjacentLoot.pos[1] - state.game.player.pos[1]), adjacentLoot.pos);
        return;
    }

    if (state.game.finishedLevel && state.game.gameMap.allowsEscape) {
        if (state.game.player.pos[0] === 0 && posPrev[0] !== 0) {
            state.popups.setNotificationHold('Exit: ' + directionArrowCharacter(-1, 0), state.game.player.pos);
            return;
        }
        if (state.game.player.pos[0] === state.game.gameMap.cells.sizeX - 1 && posPrev[0] !== state.game.gameMap.cells.sizeX - 1) {
            state.popups.setNotificationHold('Exit: ' + directionArrowCharacter(1, 0), state.game.player.pos);
            return;
        }
        if (state.game.player.pos[1] === 0 && posPrev[1] !== 0) {
            state.popups.setNotificationHold('Exit: ' + directionArrowCharacter(0, -1), state.game.player.pos);
            return;
        }
        if (state.game.player.pos[1] === state.game.gameMap.cells.sizeY - 1 && posPrev[1] !== state.game.gameMap.cells.sizeY - 1) {
            state.popups.setNotificationHold('Exit: ' + directionArrowCharacter(0, 1), state.game.player.pos);
            return;
        }
        for (const [dx, dy, terrainType] of [[1, 0, TerrainType.OneWayWindowE], [-1, 0, TerrainType.OneWayWindowW], [0, 1, TerrainType.OneWayWindowN], [0, -1, TerrainType.OneWayWindowS]]) {
            if (state.game.gameMap.cells.at(state.game.player.pos[0] + dx, state.game.player.pos[1] + dy).type === terrainType) {
                state.popups.setNotification('Leap: Shift+' + directionArrowCharacter(dx,dy), state.game.player.pos);
                return;
            }
        }
    }

    if (state.game.gameMap.cells.atVec(state.game.player.pos).type == TerrainType.GroundWater) {
        if (state.game.gameMap.cells.atVec(posPrev).type !== TerrainType.GroundWater) {
            state.popups.setNotification('Hide underwater', state.game.player.pos);
            return;
        }
        if (state.game.player.turnsRemainingUnderwater === 1) {
            state.popups.setNotification('Out of breath;\nsurfacing', state.game.player.pos);
            return;
        }
    }

    if (!state.game.player.pos.equals(posPrev)) {
        const itemsAtPlayer = state.game.gameMap.items.filter(item => item.pos.equals(state.game.player.pos));

        if (itemsAtPlayer.some(item => item.type === ItemType.Bush)) {
            state.popups.setNotification('Hide in bushes', state.game.player.pos);
            return;
        }
        if (itemsAtPlayer.some(item => item.type === ItemType.Table)) {
            state.popups.setNotification('Hide under tables', state.game.player.pos);
            return;
        }
        if (itemsAtPlayer.some(item => item.type === ItemType.BedL || item.type === ItemType.BedR)) {
            state.popups.setNotification('Hide under beds', state.game.player.pos);
            return;
        }
    }

    if (state.game.numLeapMoves === 0 && !state.game.hasEnteredMansion) {
        const adjacentDoor = state.game.gameMap.items.find(item => {
            if (item.type !== ItemType.PortcullisEW && item.type !== ItemType.PortcullisNS) {
                return false;
            }
            return vec2.squaredDistance(state.game.player.pos, item.pos) < 2;
        });
        if (adjacentDoor !== undefined) {
            const dx = adjacentDoor.pos[0] - state.game.player.pos[0];
            const dy = adjacentDoor.pos[1] - state.game.player.pos[1];
            setLeapStatusMessageHold(state, dx, dy);
            return;
        }

        let frontDoor: Item | undefined = undefined;
        for (const item of state.game.gameMap.items) {
            if (item.type !== ItemType.PortcullisEW && item.type !== ItemType.PortcullisNS) {
                continue;
            }
            if (frontDoor === undefined || frontDoor.pos[1] > item.pos[1]) {
                frontDoor = item;
            }
        }
        if (frontDoor !== undefined) {
            state.popups.setNotificationHold('Move: \x18\x19\x1b\x1a', frontDoor.pos);
            return;
        }
    }

    if (!state.game.finishedLevel && state.game.numLeapMoves <= 1) {
        const posMid = vec2.fromValues(Math.floor((state.game.player.pos[0] + posPrev[0]) / 2), Math.floor((state.game.player.pos[1] + posPrev[1]) / 2));
        if (state.game.gameMap.items.some(item => item.pos.equals(posMid) && item.type === ItemType.PortcullisEW)) {
            state.popups.setNotificationHold('Leap over open\nground or low\nfurniture too', state.game.player.pos);
            return;
        }
    }
}

function isAnyoneAwareOfPlayer(state: State): boolean {
    return state.game.gameMap.guards.some(guard => !isRelaxedGuardMode(guard.mode) && guard.mode !== GuardMode.Unconscious);
}

function remainingLootIsOnGuard(state: State): boolean {
    const lootOnGround = state.game.gameMap.items.reduce((count, item)=>count + (item.type === ItemType.Coin ? 1 : 0), 0);
    const lootOnGuards = state.game.gameMap.guards.reduce((count, guard)=>count + (guard.hasPurse ? 1 : 0), 0);
    return lootOnGround === 0 && lootOnGuards > 0;
}

function canLeapToGuard(state: State, guard: Guard): boolean {
    const dx = guard.pos[0] - state.game.player.pos[0];
    const dy = guard.pos[1] - state.game.player.pos[1];
    if (!((Math.abs(dx) === 2 && dy === 0) || (dx === 0 && Math.abs(dy) === 2))) {
        return false;
    }

    if (state.game.gameMap.cells.atVec(state.game.player.pos).type === TerrainType.GroundWater) {
        return false;
    }

    const posMid = vec2.fromValues(state.game.player.pos[0] + dx / 2, state.game.player.pos[1] + dy / 2);
    const cellMid = state.game.gameMap.cells.atVec(posMid);
    if (cellMid.blocksPlayerMove) {
        return false;
    }

    if (isHingedDoorTerrainType(cellMid.type) &&
        state.game.gameMap.items.some((item)=>item.pos.equals(posMid) && isDoorItemType(item.type))) {
        return false;
    }

    // If the midpoint is a one-way window but is the wrong way, downgrade to a step

    if ((cellMid.type == TerrainType.OneWayWindowE && dx <= 0) ||
        (cellMid.type == TerrainType.OneWayWindowW && dx >= 0) ||
        (cellMid.type == TerrainType.OneWayWindowN && dy <= 0) ||
        (cellMid.type == TerrainType.OneWayWindowS && dy >= 0)) {
        return false;
    }

    if (!canLeapToPos(state.game, guard.pos)) {
        return false;
    }

    return true;
}

function runPickpocketTutorial(state: State) {
    if (state.game.lootStolen >= state.game.lootAvailable) {
        return;
    }

    const allSeen = state.game.gameMap.allSeen();
    const remainingLootOnGuard = remainingLootIsOnGuard(state);

    if (state.game.experiencedPlayer) {
        if (!allSeen) {
            return;
        }

        if (!remainingLootOnGuard) {
            return;
        }
    }

    // Wait for everyone to be unaware of player

    if (isAnyoneAwareOfPlayer(state)) {
        return;
    }

    // Find closest guard carrying loot

    const guardsWithLoot = state.game.gameMap.guards.filter(guard => guard.hasPurse);
    if (guardsWithLoot.length === 0) {
        return;
    }

    guardsWithLoot.sort((a, b) => vec2.squaredDistance(state.game.player.pos, a.pos) - vec2.squaredDistance(state.game.player.pos, b.pos));

    const guard = guardsWithLoot[0];

    // If guard is adjacent, display a prompt to step into them

    if (isRelaxedGuardMode(guard.mode) && adjacentPositions(state.game.player.pos, guard.pos)) {
        const dx = guard.pos[0] - state.game.player.pos[0];
        const dy = guard.pos[1] - state.game.player.pos[1];
        const pos = vec2.fromValues(guard.pos[0], Math.max(guard.pos[1], state.game.player.pos[1]));
        const lootPrompt = (state.game.player.interactionTarget?.kind === 'guard' && state.game.player.interactionTarget.guard === guard) ? 'Loot: ' : 'Loot (1/2): ';
        state.popups.setNotificationHold(lootPrompt + directionArrowCharacter(dx, dy) + '\nKnockout: Shift+' + directionArrowCharacter(dx, dy), pos);
        return;
    }

    // If guard is in leaping distance, show a prompt to leap onto them

    if (canLeapToGuard(state, guard)) {
        const dx = guard.pos[0] - state.game.player.pos[0];
        const dy = guard.pos[1] - state.game.player.pos[1];
        const pos = vec2.fromValues(guard.pos[0], Math.max(guard.pos[1], state.game.player.pos[1]));
        state.popups.setNotificationHold('Leap: Shift+' + directionArrowCharacter(dx, dy), pos);
        return;
    }

    // Show a prompt on the guard

    if (allSeen && remainingLootOnGuard) {
        state.popups.setNotificationHold('Loot', guard.pos);
    }
}

function setLeapStatusMessageHold(state: State, dx: number, dy: number) {
    state.popups.setNotificationHold('Leap: Shift+' + directionArrowCharacter(dx, dy), state.game.player.pos);
}
