    g: {label: 'Grass', type: TerrainType.GroundGrass},
    r: {label: 'Roof tiles', type: TerrainType.GroundRoof},
    w: {label: 'Wood', type: TerrainType.GroundWood},
    c: {label: 'Creaky wood', type: TerrainType.GroundWoodCreaky},
    m: {label: 'Marble', type: TerrainType.GroundMarble},
    b: {label: 'Vault floor', type: TerrainType.GroundVault},
    '~': {label: 'Water', type: TerrainType.GroundWater},
    '-': {label: 'Horizontal door', type: TerrainType.DoorEW, fixture: ItemType.DoorEW},
    '|': {label: 'Vertical door', type: TerrainType.DoorNS, fixture: ItemType.DoorNS},
    '=': {label: 'Horizontal gate', type: TerrainType.PortcullisEW, fixture: ItemType.PortcullisEW},
