    food: {label: 'Food', type: ItemType.Health},
    bush: {label: 'Bush', type: ItemType.Bush},
    table: {label: 'Table', type: ItemType.Table},
    chair: {label: 'Stool', type: ItemType.Chair},
    shelf: {label: 'Shelf', type: ItemType.Shelf},
    closet: {label: 'Tall cupboard', type: ItemType.DrawersTall},
    drawers: {label: 'Low drawers', type: ItemType.DrawersShort},
    torch: {label: 'Lit torch', type: ItemType.TorchLit},
