import { vec2 } from '../my-matrix';
import type { GameMap } from '../world/game-map';
import { isGroundTerrainType,ItemType,TerrainType } from '../world/tiles';
export function ambientDistances(map: Pick<GameMap, 'cells' | 'items'>, origin: vec2, range = 10) {
    const result = {grass:Infinity, water:Infinity, stove:Infinity};
    const queue: Array<[number,number,number]> = [[origin[0],origin[1],0]], visited = new Set<number>();
    for (let i=0; i<queue.length; i++) {
        const [x,y,d] = queue[i];
        if (!map.cells.contains(x,y) || d > range) continue;
        const key=y*map.cells.sizeX+x; if (visited.has(key)) continue; visited.add(key);
        const type=map.cells.at(x,y).type;
        if (!isGroundTerrainType(type) && type !== TerrainType.Wall0000) continue;
        if (type === TerrainType.GroundGrass || type === TerrainType.GroundRoof) result.grass=Math.min(result.grass,d);
        if (type === TerrainType.GroundWater) result.water=Math.min(result.water,d);
        if (map.items.some(item=>item.type===ItemType.Stove && item.pos.equalsValues(x,y))) result.stove=Math.min(result.stove,d);
        for (const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]) queue.push([x+dx,y+dy,d+1]);
    }
    return result;
}
