import type { FloorId } from '../world/mansion';
import { vec2 } from '../my-matrix';
import { Player } from '../world/game-map';
import { GuardData as Guard } from '../world/guard';
import type { WorldIdentity } from '../world/identity';
import type { TurnFeedback } from './feedback';

export type EventValue = null | boolean | number | string | readonly EventValue[] | { readonly [key: string]: EventValue };
export type FeedbackEvent = {
    readonly type: 'presentation'; readonly kind: keyof TurnFeedback; readonly args: readonly EventValue[];
};
export type GameEvent = FeedbackEvent |
    { readonly type: 'floor-changed'; readonly from: FloorId; readonly to: FloorId } |
    { readonly type: 'player-damaged'; readonly amount: number; readonly healthRemaining: number } |
    { readonly type: 'guard-knocked-out'; readonly guardId: string; readonly position: readonly number[] };

export function recordFeedback(identity: WorldIdentity, events: GameEvent[] = []) {
    function snapshot(value: unknown): EventValue {
        if (value === undefined || value === null) return null;
        if (typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') return value;
        if (value instanceof vec2) return Object.freeze({ vector: Object.freeze([...value]) });
        if (value instanceof Player || value instanceof Guard) {
            return Object.freeze({ actorId: identity.identify(value), position: Object.freeze([...value.pos]) });
        }
        if (Array.isArray(value)) return Object.freeze(value.map(snapshot));
        if (value instanceof Set) return Object.freeze([...value].map(snapshot));
        if (typeof value === 'object') {
            return Object.freeze(Object.fromEntries(Object.entries(value).map(([key, item]) => [key, snapshot(item)])));
        }
        throw new TypeError('Unsupported event value');
    }
    const feedback = new Proxy({} as TurnFeedback, {
        get: (_target, kind: keyof TurnFeedback) => (...args: unknown[]) => {
            events.push(Object.freeze({ type: 'presentation', kind, args: Object.freeze(args.map(snapshot)) }));
        },
    });
    return { feedback, events };
}
