import type { GameMap } from '../world/game-map';
import { mansionMaps, type MansionView } from '../world/mansion';
import { isVaultBox,ItemType } from '../world/tiles';

type CollectedLoot = {
    lootStolen: number;
    levelStats: { extraFoodCollected: number };
};

type CompletedLevel = CollectedLoot & MansionView & {
    turns: number;
    levelStats: { numSpottings: number };
};

export function parTurns(map: Pick<GameMap, 'numCells' | 'numPreRevealedCells' | 'backtrackingCoefficient' | 'guards'>): number {
    const cellsToTraverse = (map.numCells() - map.numPreRevealedCells) * map.backtrackingCoefficient;
    const numGuards = map.guards.length;
    const turnsForTraversal = cellsToTraverse / 3.5;
    const turnsForGuardAvoidance = 8 * numGuards + (cellsToTraverse > 0 ? 1000 * (numGuards / cellsToTraverse) : 0);
    return 10 * Math.ceil((turnsForTraversal + turnsForGuardAvoidance) / 10);
}

export function hasBonusTreasure(map: Pick<GameMap, 'treasures' | 'items'>): boolean {
    return map.treasures.length > 0 || map.items.some(item => isVaultBox(item.type));
}

export function mansionParTurns(state: MansionView): number {
    const maps = mansionMaps(state);
    return maps.reduce((sum, map) => sum + parTurns(map), 2 * (maps.length - 1));
}

export function mansionHasBonusTreasure(state: MansionView): boolean {
    return mansionMaps(state).some(hasBonusTreasure);
}

function lootBreakdown({ lootStolen, levelStats }: CollectedLoot) {
    return { lootScore: lootStolen * 10, foodScore: levelStats.extraFoodCollected * 5 };
}

export function incompleteLevelScore(level: CollectedLoot): number {
    const { lootScore, foodScore } = lootBreakdown(level);
    return lootScore + foodScore;
}

export function completedLevelBreakdown(level: CompletedLevel) {
    const { levelStats, turns } = level;
    const maps = mansionMaps(level);
    const { lootScore, foodScore } = lootBreakdown(level);
    const locked = maps.flatMap(map => map.treasures).filter(treasure => treasure.stolen && treasure.switches.length > 0).length;
    const unlocked = maps.flatMap(map => map.treasures).filter(treasure => treasure.stolen && treasure.switches.length === 0).length;
    const vaults = maps.flatMap(map => map.items).filter(item => item.type === ItemType.LootedVaultTreasureBox).length;
    const treasureScore = lootScore * locked + lootScore / 2 * unlocked + 30 * vaults;
    const ghosted = levelStats.numSpottings === 0;
    const ghostBonus = ghosted ? lootScore : 0;
    const timeBonus = Math.max(0, mansionParTurns(level) - turns);
    const score = lootScore + treasureScore + foodScore + timeBonus + ghostBonus;
    return { lootScore, foodScore, treasureScore, ghosted, ghostBonus, timeBonus, score };
}
