import type { TileInfo } from './tile-types';
export function overrideTiles(base: readonly TileInfo[], overrides: Readonly<Partial<Record<number,TileInfo>>>): TileInfo[] {
    for (const key of Object.keys(overrides)) if (!Number.isInteger(Number(key)) || Number(key)<0 || Number(key)>=base.length)
        throw new RangeError('Theme override index is outside the base table');
    return base.map((tile,index)=>overrides[index] ?? tile);
}
