export type KeyBindings = Readonly<Record<string, readonly string[]>>;
export class PhysicalKeyboard {
    private held = new Set<string>();
    constructor(private readonly bindings: KeyBindings) {}
    clear() { this.held.clear(); }
    update(code: string, down: boolean, alt: boolean, control: boolean): ReadonlySet<string> {
        if (down) this.held.add(code); else this.held.delete(code);
        const actions = new Set<string>();
        for (let physical of this.held) {
            if (physical === 'AltLeft' || physical === 'AltRight') physical = 'Alt';
            else if (physical === 'ControlLeft' || physical === 'ControlRight') physical = 'Control';
            else if (physical === 'ShiftLeft' || physical === 'ShiftRight') physical = 'Shift';
            else physical = (control ? 'Control+' : '') + (alt ? 'Alt+' : '') + physical;
            for (const action of this.bindings[physical] ?? []) actions.add(action);
        }
        return actions;
    }
}
