function lightAnimator(baseVal:number, lightStates:Array<number>, srcIds:Set<number>, seen:boolean) {
    //Returns the exponent to apply to the light value for tiles hit with animated light
    if(srcIds.size==0) return baseVal;
    if(!seen) return 0;
    let expo=0;
    for(let l of [...srcIds]) {
        expo+=lightStates[l];
    }
    return baseVal**(1+expo/srcIds.size);
}

function updateAnimatedLight(light: WeakMap<Cell, number>, cells:CellGrid, lightStates:Array<number>, seeAll: boolean) {
    for(let x=0; x<cells.sizeX; x++) {
        for(let y=0;y<cells.sizeY; y++) {
            const c = cells.at(x,y);
            if(!connectsWallTile(c.type)) {
                light.set(c, lightAnimator(c.lit, lightStates, c.litSrc, seeAll || c.seen));
            } else {
                //Walls and portals get rendered unlit regardless of light sources
                light.set(c, 0);
            }
        }
    }
}

function litVertices(light: WeakMap<Cell, number>, x:number, y:number, cells:CellGrid):[number,number,number,number] {
    // The scale of 0.1 for unlit tiles creates a hard-ish edge at the boundary of lit and unlit tiles
    // 0 would give a completely hard edge, while 1 will be smooth but hard for the player to tell
    // which tiles at the boundary are lit
    const scale = (cells.at(x, y).lit ? 1 : 0.1) / 4;

    const lld = light.get(cells.at(x-1,y-1)) ?? 0;
    const ld  = light.get(cells.at(x,  y-1)) ?? 0;
    const lrd = light.get(cells.at(x+1,y-1)) ?? 0;
    const ll  = light.get(cells.at(x-1,y  )) ?? 0;
    const l   = light.get(cells.at(x,  y  )) ?? 0;
    const lr  = light.get(cells.at(x+1,y  )) ?? 0;
    const llu = light.get(cells.at(x-1,y+1)) ?? 0;
    const lu  = light.get(cells.at(x,  y+1)) ?? 0;
    const lru = light.get(cells.at(x+1,y+1)) ?? 0;

    return [
        scale * (lld+ld+ll+l), //bottom left vertex
        scale * (lrd+ld+lr+l), //bottom right
        scale * (llu+lu+ll+l), //top left
        scale * (lru+lu+lr+l), //top right
    ];
}

function renderTouchButtons(renderer:Renderer, touchController:TouchController) {
    for(const bkey in touchController.coreTouchTargets) {
        if (!(bkey in touchController.controlStates)) continue;
        const b = touchController.coreTouchTargets[bkey];
        if (!b.mouseable && touchController.mouseActive) continue;
        if (b.tileInfo === null || b.rect[2] === 0 || b.rect[3] === 0) continue;
        const lit = touchController.controlStates[bkey] ? 1 : 0;
        renderer.addGlyphLit(
            b.rect[0],
            b.rect[1],
            b.rect[0] + b.rect[2],
            b.rect[1] + b.rect[3],
            b.tileInfo,
            lit);
    }
    renderer.flush();
}

function renderTerrain(state: State, renderer: Renderer) {

    // Draw terrain
    const {cells, openings} = state.game.gameMap;
    const terrTiles = terrainTileSetForLevelType(state.game.gameMapRoughPlans[state.game.level].levelType, renderer.terrainTileSet);
    const eave = {...fontTileSet.background, color: 0xc03f3446};

    for (let x = 0; x < state.game.gameMap.cells.sizeX; ++x) {
        for (let y = state.game.gameMap.cells.sizeY-1; y >= 0 ; --y) { //Render top to bottom for overlapped tiles
            const cell = state.game.gameMap.cells.at(x, y);
            if (openings.has(cells.index(x, y)) || (!cell.seen && !state.seeAll)) {
                continue;
            }
            let terrainType = cell.type;
            if (terrainType == TerrainType.GroundWoodCreaky) {
                if (!(cell.lit || cell.identified) && !state.seeAll) {
                    terrainType = TerrainType.GroundWood;
                }
            }
            const lv = litVertices(state.visuals.cellLight, x, y, state.game.gameMap.cells);

            // Draw tile
            let tile = state.visuals.cellAnimations.get(cell)?.currentTile() ?? terrTiles[terrainType];
            if ((isHingedDoorTerrainType(terrainType)) && !cell.blocksSight && tile.textureIndex!==undefined) {
                tile = {...tile, textureIndex: tile.textureIndex + 1};
            }
            renderer.addGlyphLit4(x, y, x+1, y+1, tile, lv);
            if (terrainType === TerrainType.GroundRoof && (y === 0 || openings.has(cells.index(x, y - 1)))) {
                renderer.addGlyph(x, y, x + 1, y + 0.125, eave);
            }

            // Draw border for water
            if (terrainType===TerrainType.GroundWater) {
                const ledge = renderer.terrainTileSet.ledgeTiles;
                let ctr = 0;
                for(let adj of [[0,1],[0,-1],[-1,0],[1,0]]) {
                    const cell = state.game.gameMap.cells.at(x+adj[0],y+adj[1]);
                    if(cell.type!==TerrainType.GroundWater) {
                        renderer.addGlyphLit4(x, y, x+1, y+1, ledge[ctr], lv);
                    }
                    ctr++;
                }
            }
        }
    }
}

function renderItems(state: State, renderer: Renderer, topLayer: boolean) {
    // Draw items
    const itemTiles = itemTileSetForLevelType(state.game.gameMapRoughPlans[state.game.level].levelType, renderer.entityTileSet);

    for(const item of state.game.gameMap.items.filter(item=>isOverheadItem(item.type) === topLayer)) {
        const animation = state.visuals.itemAnimations.get(item);
        let x = item.pos[0];
        let y = item.pos[1];
        const cell = state.game.gameMap.cells.at(x, y);
        if (!cell.seen && !state.seeAll) {
            continue;
        }
        const terrainType = cell.type;
        const lv = litVertices(state.visuals.cellLight, x, y, state.game.gameMap.cells);
        if (isGateTerrainType(terrainType)) {
            //Render the portcullis open if a guard in it, otherwise close
            if (!state.game.gameMap.guards.find((guard)=>guard.pos[0]===x && guard.pos[1]===y)) {
                renderer.addGlyphLit4(x, y, x + 1, y + 1, itemTiles[item.type], lv);
            } else {
                let tile = itemTiles[item.type];
                if (tile.textureIndex !== undefined) {
                    tile = {...tile, textureIndex: tile.textureIndex + 1};
                }
                renderer.addGlyphLit4(x, y, x + 1, y + 1, tile, lv);
            }
        } else if (isHingedDoorTerrainType(terrainType)) {
            //The render the door if it is closed
            if (!state.game.gameMap.guards.find((guard)=>guard.pos[0]===x && guard.pos[1]===y) &&
                !(state.game.player.pos[0]===x && state.game.player.pos[1]===y)) {
                renderer.addGlyphLit4(x, y, x + 1, y + 1, itemTiles[item.type], lv);
            }
        } else if (isPlinthTreasure(item.type)) {
            renderer.addGlyph(x, y+0.5, x + 1, y + 1.5, itemTiles[item.type]);
            if (animation) {
                renderer.addGlyph(x, y+0.5, x + 1, y + 1.5, animation.currentTile());
            }
        } else if (item.type===ItemType.VaultTreasureBox) {
            renderer.addGlyph(x, y, x + 1, y + 1, itemTiles[item.type]);
            if (animation) {
                renderer.addGlyph(x, y, x + 1, y + 1, animation.currentTile());
            }
        } else if (item.type===ItemType.Coin) {
            renderer.addGlyph(x, y, x + 1, y + 1, itemTiles[item.type]);
            if (animation) {
                renderer.addGlyph(x, y, x + 1, y + 1, animation.currentTile());
            }
        } else {
            const ti = animation ?
                animation.currentTile() :
                itemTiles[item.type];
            if (animation instanceof SpriteAnimation) {
                const o = animation.offset;
                x += o[0];
                y += o[1];
            }
            renderer.addGlyphLit4(x, y, x + 1, y + 1, ti, lv);
        }
    }
}

function renderRoomAdjacencies(rooms: Array<Rect>, adjacencies: Array<Adjacency>, renderer: Renderer) {
    const tileRoom = entityTileSet.namedTiles.debugSolid;
    const tileWall = {...entityTileSet.namedTiles.debugSolid, color: 0xff4040ff};
    const tileDoor = entityTileSet.namedTiles.debugSolid;

    const r = 1 / 16;

    for (const room of rooms) {
        const x0 = room.posMin[0];
        const y0 = room.posMin[1];
        const x1 = room.posMax[0];
        const y1 = room.posMax[1];
        renderer.addGlyph(x0,     y0,     x1,     y0 + r, tileRoom);
        renderer.addGlyph(x0,     y1 - r, x1,     y1,     tileRoom);
        renderer.addGlyph(x0,     y0 + r, x0 + r, y1 - r, tileRoom);
        renderer.addGlyph(x1 - r, y0 + r, x1,     y1 - r, tileRoom);
    }

    for (const adj of adjacencies) {
        const p0x = 0.5 + adj.origin[0];
        const p0y = 0.5 + adj.origin[1];
        const p1x = p0x + adj.dir[0] * adj.length;
        const p1y = p0y + adj.dir[1] * adj.length;

        const dx = Math.abs(adj.dir[0]) * (1 - r);
        const dy = Math.abs(adj.dir[1]) * (1 - r);

        const x0 = Math.min(p0x, p1x) + dx - (0.5 - r);
        const y0 = Math.min(p0y, p1y) + dy - (0.5 - r);
        const x1 = Math.max(p0x, p1x) - dx + (0.5 - r);
        const y1 = Math.max(p0y, p1y) - dy + (0.5 - r);

        const tile = adj.door ? tileDoor : tileWall;

        renderer.addGlyph(x0,     y0,     x1,     y0 + r, tile);
        renderer.addGlyph(x0,     y1 - r, x1,     y1,     tile);
        renderer.addGlyph(x0,     y0 + r, x0 + r, y1 - r, tile);
        renderer.addGlyph(x1 - r, y0 + r, x1,     y1 - r, tile);
    }
}

function renderWorldBorder(state: State, renderer: Renderer) {
    const sizeX = state.game.gameMap.cells.sizeX;
    const sizeY = state.game.gameMap.cells.sizeY;
    const tileInfo = entityTileSet.unlitTile;
    renderer.addGlyph(-1, 0, 0, sizeY, tileInfo);
    renderer.addGlyph(sizeX, 0, sizeX + 1, sizeY, tileInfo);
    renderer.addGlyph(-1, -1, sizeX + 1, 0, tileInfo);
    renderer.addGlyph(-1, sizeY, sizeX + 1, sizeY + 1, tileInfo);
}

function renderPlayer(state: State, renderer: Renderer) {
    const visual = state.visuals.player(state.game.player);
    const player = state.game.player;
    const a = visual.animation;
    const offset = a &&  a instanceof SpriteAnimation ? a.offset : vec2.create();
    const x = player.pos[0] + offset[0];
    const y = player.pos[1] + offset[1];
    const x0 = player.pos[0];
    const y0 = player.pos[1];
    const cell = state.game.gameMap.cells.at(x0, y0);
    const lit = lightAnimator(cell.lit, state.lightStates, cell.litSrc, state.seeAll || cell.seen);
    const hidden = player.hidden(state.game.gameMap);
    const dead = player.health <= 0;

    let tileInfo:TileInfo;
    if (a) {
        tileInfo = a.currentTile();
    } else {
        const p = renderer.entityTileSet.playerTiles;
        tileInfo =
            dead ? p.dead :
            (hidden || !player.elevated && cell.type === TerrainType.GroundWater) ? p.hidden :
            p.normal;
    }

    const frontRenders:[number, number, number, number, TileInfo, number][] = [];
    const tileInfoTinted = structuredClone(tileInfo);
    if (!dead) {
        if (visual.idle) {
            if(visual.idleCursorAnimation !== null && visual.idleCursorAnimation.length === 1 &&
                visual.idleCursorAnimation[0] instanceof PulsingColorAnimation) {
                const tile = visual.idleCursorAnimation[0].currentTile();
                renderer.addGlyphLit(x0, y0, x0+1, y0+1, tile, 1);
            }
            if(visual.idleCursorAnimation !== null && visual.idleCursorAnimation.length > 1) {
                for (let anim of visual.idleCursorAnimation) {
                    if (anim instanceof RadialAnimation) {
                        const tile = anim.currentTile();
                        const off = anim.offset;
                        if(off[1]>0) {
                            renderer.addGlyphLit(x0+off[0], y0+off[1]/4-0.125, x0+off[0]+1, y0+off[1]/4+1-0.125, tile, 1);
                        } else {
                            frontRenders.push([x0+off[0], y0+off[1]/4-0.125, x0+off[0]+1, y0+off[1]/4+1-0.125, tile, 1])
                        }
                    }
                }
            }
        }
        if (player.damagedLastTurn) {
            tileInfoTinted.color = colorPreset.lightRed;
            tileInfoTinted.unlitColor = colorPreset.darkRed;
        } else if (hidden) {
            tileInfoTinted.color = colorPreset.darkGray;
            tileInfoTinted.unlitColor = colorPreset.darkerGray;
        }
    }

    renderer.addGlyphLit(x, y, x+1, y+1, tileInfoTinted, lit);
    if(hidden && visual.idle) {
        renderer.addGlyphLit(x, y, x+1, y+1, renderer.entityTileSet.playerTiles.litFace, 0.15);
    }
    if(player.lightActive) {
        const torchTile = visual.torchAnimation!==null?
            visual.torchAnimation.currentTile():
            renderer.entityTileSet.itemTiles[ItemType.TorchCarry];
        renderer.addGlyphLit(x, y, x+1, y+1, torchTile, lit);
    }
    for(let dr of frontRenders) {
        renderer.addGlyphLit(...dr);
    }
}

function renderGuards(state: State, renderer: Renderer) {
    for (const guard of state.game.gameMap.guards) {
        const visual = state.visuals.guard(guard);
        let tileIndex = 0 + tileIndexOffsetForDir(guard.dir);

        const cell = state.game.gameMap.cells.atVec(guard.pos);
        let lit = lightAnimator(cell.lit, state.lightStates, cell.litSrc, state.seeAll || cell.seen);
        const visible = state.seeAll || cell.seen || state.visuals.speaker === guard;
        if (!visible && vec2.squaredDistance(state.game.player.pos, guard.pos) > 36) {
            continue;
        }

        if(!visible && guard.mode !== GuardMode.Unconscious) tileIndex+=4;
        else if(guard.mode === GuardMode.Patrol && state.visuals.speaker !== guard && cell.lit==0) lit=0;
        else if(guard.mode === GuardMode.Unconscious) tileIndex+=12;
        else tileIndex+=8;
        const tileInfo = structuredClone(renderer.entityTileSet.npcTiles[tileIndex]);
        if (guard.mode === GuardMode.Unconscious && guard.hidden(state.game.gameMap)) {
            tileInfo.color! = colorPreset.darkGray;
            tileInfo.unlitColor! = colorPreset.darkerGray;
        }

        const gate = state.game.gameMap.items.find((item)=>item.pos.equals(guard.pos) && [ItemType.PortcullisEW, ItemType.PortcullisNS].includes(item.type));
        const offX = (gate!==undefined && gate.pos.equals(guard.pos))? 0.25 : 0;

        let offset = visual.animation?.offset?? vec2.create();
        const x = guard.pos[0] + offset[0] + offX;
        const y = guard.pos[1] + offset[1];

        if(guard.hasTorch || guard.hasPurse || guard.hasVaultKey) {
            let t0 = x+guard.dir[0]*0.375+guard.dir[1]*0.375;
            let t1 = y-0.125;
            const tti = guard.mode!==GuardMode.Unconscious&&visual.torchAnimation?
                    visual.torchAnimation.currentTile():
                    renderer.entityTileSet.itemTiles[ItemType.TorchCarry];
            let p0 = x-guard.dir[0]*0.250+(guard.dir[1]<0?0.375:0);
            let p1 = y-0.125;
            const pti = guard.hasVaultKey?entityTileSet.itemTiles[ItemType.KeyCarry]:renderer.entityTileSet.itemTiles[ItemType.PurseCarry];
            if(guard.dir[1]>0) {
                if(guard.hasTorch) renderer.addGlyphLit(t0, t1, t0 + 1, t1 + 1, tti, lit);
                renderer.addGlyphLit(x, y, x + 1, y + 1, tileInfo, lit);
                if(guard.hasPurse || guard.hasVaultKey) renderer.addGlyphLit(p0, p1, p0 + 1, p1 + 1, pti, lit);
            } else if(guard.dir[1]<0) {
                if(guard.hasPurse || guard.hasVaultKey) renderer.addGlyphLit(p0, p1, p0 + 1, p1 + 1, pti, lit);
                renderer.addGlyphLit(x, y, x + 1, y + 1, tileInfo, lit);
                if(guard.hasTorch) renderer.addGlyphLit(t0, t1, t0 + 1, t1 + 1, tti, lit);
            } else {
                renderer.addGlyphLit(x, y, x + 1, y + 1, tileInfo, lit);
                if(guard.hasTorch) renderer.addGlyphLit(t0, t1, t0 + 1, t1 + 1, tti, lit);
                if(guard.hasPurse || guard.hasVaultKey) renderer.addGlyphLit(p0, p1, p0 + 1, p1 + 1, pti, lit);
            }
        }
        else renderer.addGlyphLit(x, y, x + 1, y + 1, tileInfo, lit);
        // renderer.addGlyphLit(guard.pos[0], guard.pos[1], guard.pos[0] + 1, guard.pos[1] + 1, tileInfo, lit);
    }
}

function renderParticles(state: State, renderer: Renderer) {
    for(let p of state.particles) {
        if(p.animation && (state.seeAll || state.game.gameMap.cells.atVec(p.pos).seen)) {
            const a = p.animation;
            const offset = (a instanceof SpriteAnimation)||(a instanceof IdleRadialAnimation) ? a.offset : vec2.create();
            const x = p.pos[0] + offset[0];
            const y = p.pos[1] + offset[1];
            const tileInfo = a.currentTile();
            if (!(p.animation instanceof SpriteAnimation) || p.animation.time>=0) {
                renderer.addGlyph(x, y, x+1, y+1, tileInfo);
            }
        }
    }
}

function renderIconOverlays(state: State, renderer: Renderer) {
    const visual = state.visuals.player(state.game.player);
    const player = state.game.player;
    const bubble_right = renderer.entityTileSet.namedTiles['speechBubbleR'];
    const bubble_left = renderer.entityTileSet.namedTiles['speechBubbleL'];
    for (const guard of state.game.gameMap.guards) {
        const cell = state.game.gameMap.cells.atVec(guard.pos);
        const visible = state.seeAll || cell.seen || state.visuals.speaker === guard;
        if (!visible && vec2.squaredDistance(state.game.player.pos, guard.pos) > 36) {
            continue;
        }

        let offset = state.visuals.guard(guard).animation?.offset?? vec2.create();
        const x = guard.pos[0] + offset[0];
        const y = guard.pos[1] + offset[1];

        if (state.visuals.speaker === guard && !state.popups.isSpeechBubbleVisible()) {
            const dir = guard.dir[0];
            if(dir>=0) {
                renderer.addGlyph(x+1, y, x+2, y+1, bubble_right);
            } else {
                renderer.addGlyph(x-1, y, x, y+1, bubble_left);
            }
        }

        const guardState = guard.overheadIcon();
        if (guardState!==GuardStates.Relaxed) {
            const gtile = renderer.entityTileSet.guardStateTiles[guardState]
            renderer.addGlyph(x, y+0.625, x+1, y+1.625, gtile);
        }
        if ((player.interactionTarget?.kind === 'guard' && player.interactionTarget.guard === guard)) {
            // Render the shadowing indicator if player is shadowing a guard
            const gtile = entityTileSet.namedTiles['pickTarget'];
            renderer.addGlyph(x, y+0.625, x+1, y+1.625, gtile);
        }
    }

    // Render an icon over the player if the player is being noisy
    if (player.preNoisy || player.noisy) {
        const a = visual.animation;
        const offset = a && a instanceof SpriteAnimation ? a.offset : vec2.create();
        if (Math.abs(offset[0]) < 0.5 && Math.abs(offset[1]) < 0.5) {
            const x = player.pos[0] + player.noiseOffset[0] / 2;
            const y = player.pos[1] + player.noiseOffset[1] / 2;
            if (player.preNoisy) {
                renderer.addGlyph(x, y, x+1, y+1, entityTileSet.namedTiles['pickTarget']);
            } else {
                const s = 0.0625 *  Math.sin(visual.noisyAnim * Math.PI * 2);
                renderer.addGlyph(x - s, y - s, x+1+s, y+1+s, entityTileSet.namedTiles['noise']);
            }
        }
    }
}

function renderGuardSight(state: State, renderer: Renderer) {
    if (!state.seeGuardSight) {
        return;
    }

    const mapSizeX = state.game.gameMap.cells.sizeX;
    const mapSizeY = state.game.gameMap.cells.sizeY;

    const seenByGuard = new BooleanGrid(mapSizeX, mapSizeY, false);

    const pos = vec2.create();
    const dpos = vec2.create();

    for (const guard of state.game.gameMap.guards) {
        const maxSightCutoff = 10;
        const xMin = Math.max(0, Math.floor(guard.pos[0] - maxSightCutoff));
        const xMax = Math.min(mapSizeX, Math.floor(guard.pos[0] + maxSightCutoff) + 1);
        const yMin = Math.max(0, Math.floor(guard.pos[1] - maxSightCutoff));
        const yMax = Math.min(mapSizeY, Math.floor(guard.pos[1] + maxSightCutoff) + 1);
        for (let y = yMin; y < yMax; ++y) {
            for (let x = xMin; x < xMax; ++x) {
                if (seenByGuard.get(x, y)) {
                    continue;
                }
                vec2.set(pos, x, y);
                vec2.subtract(dpos, pos, guard.pos);
                const cell = state.game.gameMap.cells.atVec(pos);
                if (!state.seeAll && !cell.seen) {
                    continue;
                }
                if (cell.blocksPlayerMove) {
                    continue;
                }
                const hidden = !state.game.player.lightActive && !state.game.gameMap.guards.some(g => g.mode === GuardMode.ChaseVisibleTarget) &&
                    (cell.hidesPlayer || cell.type === TerrainType.GroundWater && state.game.player.turnsRemainingUnderwater > 0);
                if (!guardSeesPosition.call(guard, state.game.gameMap, pos, hidden, lineOfSight, 0)) continue;

                seenByGuard.set(x, y, true);
            }
        }
    }

    for (let y = 0; y < state.game.gameMap.cells.sizeY; ++y) {
        for (let x = 0; x < state.game.gameMap.cells.sizeX; ++x) {
            if (seenByGuard.get(x, y)) {
                renderer.addGlyph(x, y, x+1, y+1, entityTileSet.namedTiles['crossHatch']);
            }
        }
    }
}

function renderGuardPatrolPaths(state: State, renderer: Renderer) {
    if (!state.seeGuardPatrols) {
        return;
    }

    for (const guard of state.game.gameMap.guards) {
        for (const pos of guard.patrolPath) {
            renderer.addGlyph(pos[0], pos[1], pos[0]+1, pos[1]+1, entityTileSet.namedTiles['patrolRoute']);
        }
    }
}

function tileIndexOffsetForDir(dir: vec2): number {
    if (dir[1] > 0) {
        return 1;
    } else if (dir[1] < 0) {
        return 3;
    } else if (dir[0] > 0) {
        return 0;
    } else if (dir[0] < 0) {
        return 2;
    } else {
        return 3;
    }
}

function mistColor(depth: number): number {
    return Math.min(174, 27 + 24 * depth) * 0x1000000 + 0x00a48978;
}

function renderExposedStories(state: State, renderer: Renderer) {
    const {mansion, gameMap, floorId, player} = state.game;
    if (!mansion || !gameMap.openings.size) return;
    const theme = state.game.gameMapRoughPlans[state.game.level].levelType;
    const terrain = terrainTileSetForLevelType(theme, renderer.terrainTileSet);
    const items = itemTileSetForLevelType(theme, renderer.entityTileSet);
    const exposed = new Map<MansionFloor, Set<number>>();
    for (const i of gameMap.openings) {
        const pos = vec2.fromValues(i % gameMap.cells.sizeX, Math.floor(i / gameMap.cells.sizeX));
        const floor = exposedFloorAt(mansion, floorId, pos);
        if (!floor) continue;
        const {cells} = floor.map;
        const cell = cells.atVec(pos);
        if (!cell.seen && !state.seeAll) continue;
        const indices = exposed.get(floor) ?? new Set<number>();
        indices.add(cells.indexVec(pos));
        exposed.set(floor, indices);
        const [x,y] = pos;
        renderer.addGlyphLit(x, y, x + 1, y + 1, terrain[cell.type], cell.lit);
    }
    for (const [floor, indices] of exposed) {
        const {cells, items: contents, guards} = floor.map;
        for (const item of contents) {
            if (!indices.has(cells.indexVec(item.pos))) continue;
            const [x,y] = item.pos;
            renderer.addGlyphLit(x, y, x + 1, y + 1, items[item.type], cells.atVec(item.pos).lit);
        }
        for (const guard of guards) {
            if (!indices.has(cells.indexVec(guard.pos))) continue;
            const [x,y] = guard.pos;
            const mode = guard.mode === GuardMode.Unconscious ? 12 : guard.mode === GuardMode.Patrol ? 0 : 8;
            renderer.addGlyphLit(x, y, x + 1, y + 1, renderer.entityTileSet.npcTiles[mode + tileIndexOffsetForDir(guard.dir)], cells.atVec(guard.pos).lit);
        }
        const mist = {...fontTileSet.background, color: mistColor(2 * (floorId - floor.id) + Number(player.elevated))};
        for (const i of indices) {
            const x = i % cells.sizeX, y = Math.floor(i / cells.sizeX);
            renderer.addGlyph(x, y, x + 1, y + 1, mist);
        }
    }
}

function renderElevation(state: State, renderer: Renderer) {
    const {gameMap, player} = state.game;
    const {cells, platforms} = gameMap;
    if (player.elevated) {
        const mist = {...fontTileSet.background, color: mistColor(1)};
        for (const [index, cell] of cells.values.entries()) {
            if ((!cell.seen && !state.seeAll) || gameMap.openings.has(index) || isWallTerrainType(cell.type)) continue;
            const x = index % cells.sizeX, y = Math.floor(index / cells.sizeX);
            renderer.addGlyph(x, y, x + 1, y + 1, mist);
        }
    }
    const edge = {...fontTileSet.background, color: player.elevated ? 0xafdbd5ab : 0x68dbd5ab};
    for (const index of platforms) {
        if (!cells.values[index].seen && !state.seeAll) continue;
        const x = index % cells.sizeX, y = Math.floor(index / cells.sizeX);
        renderer.addGlyph(x + 0.16, y + 0.72, x + 0.84, y + 0.81, edge);
        renderer.addGlyph(x + 0.16, y + 0.19, x + 0.84, y + 0.28, edge);
    }
}

export function renderScene(renderer: Renderer, screenSize: vec2, state: State) {
    renderer.beginFrame(screenSize);
    const matScreenFromWorld = mat4.create();
    setupViewMatrix(state, screenSize, matScreenFromWorld);
    updateAnimatedLight(state.visuals.cellLight, state.game.gameMap.cells, state.lightStates, state.seeAll);

    renderer.start(matScreenFromWorld);
    renderExposedStories(state, renderer);
    renderTerrain(state, renderer);
    renderer.flush();

    const {stairs, exitPositions, cells} = state.game.gameMap;
    if (stairs.length > 0 || exitPositions?.length) {
        renderer.start(matScreenFromWorld);
        function marker(pos: vec2, arrow: number, color: number) {
            if (!state.seeAll && !cells.atVec(pos).seen) return;
            const [x, y] = pos;
            renderer.addGlyph(x + 0.12, y + 0.08, x + 0.88, y + 0.92,
                {atlas: SpriteAtlas.Font, textureIndex: 219, color: 0xd02d2230});
            renderer.addGlyph(x + 0.25, y + 0.05, x + 0.75, y + 0.95, {atlas: SpriteAtlas.Font, textureIndex: arrow, color});
        }
        for (const {pos, destination} of stairs) {
            marker(pos, destination > state.game.floorId ? 0x18 : 0x19, colorPreset.lightCyan);
        }
        for (const pos of exitPositions ?? []) {
            const [x, y] = pos;
            const outward = y === 0 ? 0x19 : y === cells.sizeY - 1 ? 0x18 : x === 0 ? 0x1b : 0x1a;
            marker(pos, outward, colorPreset.lightGreen);
        }
        renderer.flush();
    }

    renderer.start(matScreenFromWorld);
    renderItems(state, renderer, false);

    renderGuardSight(state, renderer);
    renderGuardPatrolPaths(state, renderer);

    renderGuards(state, renderer);
    const elevated = state.game.player.elevated;
    const showPlayer = (state.gameMode !== GameMode.MansionComplete && state.gameMode !== GameMode.Win) ||
        state.visuals.player(state.game.player).animation;
    if (!elevated && showPlayer) renderPlayer(state, renderer);
    renderItems(state, renderer, true);
    renderElevation(state, renderer);
    if (elevated && showPlayer) renderPlayer(state, renderer);

    if (state.seeRoomAdjacencies) {
        renderRoomAdjacencies(state.game.gameMap.rooms, state.game.gameMap.adjacencies, renderer);
    }

    renderParticles(state, renderer);
    if(state.gameMode===GameMode.Mansion) {
        renderIconOverlays(state, renderer);
    }
    renderWorldBorder(state, renderer);
    renderer.flush();

    renderDamageVignette(state.game.player.health, state.game.player.healthMax, state.healthBarState.healing, state.healthBarState.damageDisplayTimer, renderer, screenSize);

    if (state.gameMode===GameMode.Mansion || state.gameMode===GameMode.MansionComplete) {
        renderTextBox(renderer, screenSize, state);
        renderNotification(renderer, screenSize, state);
    }

    if (state.gameMode===GameMode.Mansion || state.gameMode===GameMode.MansionComplete) {
        renderStatusOverlay(renderer, screenSize, state);
    }

    const menuWindow = state.textWindows[state.gameMode];
    if(menuWindow !== undefined) {
        menuWindow.render(renderer);
    }

    renderBottomStatusBar(renderer, screenSize, state);

    if (lastController===state.touchController) {
        const matScreenFromPixel = mat4.create();
        mat4.ortho(
            matScreenFromPixel,
            0,
            screenSize[0],
            0,
            screenSize[1],
            1,
            -1
        );

        renderer.start(matScreenFromPixel);
        renderTouchButtons(renderer, state.touchController);
        renderer.flush();
    }
}
