import { systemClock } from '../application/ports';
import { buildCustomLevel } from './levels/build';
import { readLevel, type LevelFile } from './levels/format';
import { MansionPursuit } from './mansion-pursuit';
import type { GeneratorVersion } from '../core/versions';
import { createGameMap,createGameRoughPlansDailyRun,createMultiFloorMansion } from '../generation';
import type { ProfileState } from '../profile/state';
import { ProfileStore } from '../profile/store';
import { RNG } from '../random';
import { getCurrentDateFormatted } from '../run/date';
import { dailySummary,recordDeath,recordWin,rolloverDailyProfile,scoreCompletedLevel,updateAchievements } from '../run/progress';
import { configureInitialRun,newLevelStats,newRunStats,normalPlans } from '../run/setup';
import type { RunState } from '../run/state';
import type { PlayerCommand } from '../simulation';
import { dispatchCommand } from '../simulation';
import type { GameEvent } from '../simulation/events';
import { recordFeedback } from '../simulation/events';
import { chooseGuardMoves } from '../simulation/guards';
import type { SimulationState } from '../simulation/state';
import { moveToFloor, postTurn, updateMansionProgress } from '../simulation/turn';
import { vec2 } from '../my-matrix';
import { Player } from '../world/game-map';
import { exposedFloorAt, FloorId, landingBesideLadder, mansionMaps } from '../world/mansion';
import type { Mansion } from '../world/mansion';
import { GuardMode } from '../world/guard-mode';
import { WorldIdentity } from '../world/identity';
import { lineOfSightToPosition } from '../world/sight';

export type CommandResult = {
    readonly accepted: boolean;
    readonly turnConsumed: boolean;
    readonly events: readonly GameEvent[];
    readonly outcome: SessionPhase;
};
export type SessionPhase = 'configured' | 'playing' | 'mansion-complete' | 'dead' | 'won';
export type SessionData = RunState & SimulationState & ProfileState & { phase: SessionPhase; multiFloor: boolean; floorId: FloorId; customTitle?: string };
export type GameReadModel = Readonly<Omit<SessionData, 'feedback' | 'turnHooks' | 'profile'>>;
export type SessionCommand = PlayerCommand;
export type SessionEvent = 'floor' | 'reinforcement' | 'map' | 'resume' | 'stop-sounds' | 'complete-level' | 'complete-run' | 'menu' | 'camera-fit' | 'tutorial';
export type SessionOptions = { clock?: Clock; seedSource?: SeedSource; profile: ProfileStore; seed?: string;
    generateMap?: typeof createGameMap; generateMansion?: typeof createMultiFloorMansion; customLevel?: LevelFile;
    generatorVersion?: GeneratorVersion };


function temporaryProfile() {
    const storage = new Map<string, string>();
    return new ProfileStore({
        getItem: key => storage.get(key) ?? null,
        setItem: (key, value) => { storage.set(key, value); },
        removeItem: key => { storage.delete(key); },
    });
}

export function createGameSession(ports: SessionOptions) {
    const custom = ports.customLevel && readLevel(ports.customLevel);
    const scenario = custom && buildCustomLevel(custom);
    const customStart = scenario && {spec: scenario.spec, map: firstFloor(scenario.mansion)};
    const initial = configureInitialRun(0, undefined, customStart?.spec.seed ?? ports.seed ?? ports.seedSource?.(),
        ports.generateMap, customStart, ports.generatorVersion);
    const profile = custom ? temporaryProfile() : ports.profile;
    const data: SessionData = { ...initial, phase: 'configured', multiFloor: (scenario?.mansion.floors.length ?? 1) > 1,
        floorId: FloorId.First, customTitle: custom?.title, mansion: scenario?.mansion, profile,
        persistedStats: profile.readStats(), ...profile.readSettings(), experiencedPlayer: !!custom };
    const getState = () => data;
    let sink: (event: SessionEvent) => void = () => {};
    let pending: SessionEvent[] | undefined;
    const deliver = (event: SessionEvent) => { try { sink(event); } catch { /* Effects cannot cancel transitions. */ } };
    const emit = (event: SessionEvent) => { if (pending) pending.push(event); else deliver(event); };
    const generateMap = ports.generateMap ?? createGameMap;
    const generateMansion = ports.generateMansion ?? createMultiFloorMansion;
    const debugForceLevelType = undefined;
    const debugInitialLevel = 0;
    const debugLevelGen = false;
    const clock = ports.clock ?? systemClock;
    const pursuit = new MansionPursuit();
    let sequence = 0;
    let identities: WorldIdentity;
    const floorIdentities = new Map<FloorId, WorldIdentity>();
    function identifyActiveFloor() {
        const id = data.runId + '/' + data.level;
        identities = floorIdentities.get(data.floorId) ?? new WorldIdentity(data.mansion ? id + '/floor/' + data.floorId : id);
        floorIdentities.set(data.floorId, identities);
        identities.register(data.gameMap, data.player);
    }

    function firstFloor(mansion: Mansion) {
        const ground = mansion.floors.find(floor => floor.id === FloorId.First);
        if (!ground) throw new Error('Mansion is missing its first floor');
        return ground.map;
    }

    function loadMansion(prepared?: Mansion) {
        const spec = data.gameMapRoughPlans[data.level];
        data.mansion = prepared ?? (data.multiFloor ? generateMansion(spec, generateMap) : undefined);
        data.gameMap = data.mansion ? firstFloor(data.mansion) : generateMap(spec);
        data.floorId = FloorId.First;
        floorIdentities.clear();
        pursuit.clear();
        return data.gameMap;
    }

    function newNormalRun(multiFloor = false) {
        if (custom) { restartSeededRun(); return; }
        const state = getState();
        state.rng = new RNG(ports.seedSource?.());
        state.dailyRun = null;
        state.multiFloor = multiFloor;
        restartSeededRun();
    }

    function restartCurrentRun() {
        if (getState().dailyRun !== null) startDaily();
        else newNormalRun(getState().multiFloor);
    }

    function nextMansion() {
        const state = getState();
        if (state.level >= state.gameMapRoughPlans.length - 1) completeRun();
        else setupLevel(state.level + 1);
    }

    function completeRun() {
        const state = getState();
        if (state.resultRecorded) return;
        emit('stop-sounds');
        emit('complete-run');
        recordWin(state, clock);
        state.phase = 'won';
    }

    function leaveResults() {
        if (custom) { restartSeededRun(false); emit('menu'); return; }
        const state = getState();
        state.rng = new RNG(ports.seedSource?.());
        state.dailyRun = null;
        state.multiFloor = false;
        restartSeededRun(false);
        emit('menu');
        state.hasStartedGame = false;
    }

    function openMenu() {

        emit('menu');
    }

    function moveDebugLevel(offset: number, fitCamera: boolean) {
        const state = getState();
        const level = state.level + offset;
        if (level < 0 || level >= state.gameMapRoughPlans.length) return;
        scoreCompletedLevel(state, clock);
        setupLevel(level);
        if (fitCamera) emit('camera-fit');
    }

    function collectDebugLoot() {
        const state = getState();
        const loot = mansionMaps(state).reduce((total,map) => total + map.collectAllLoot(), 0);
        state.player.loot += loot;
        state.lootStolen += loot;
        postTurn(state);
        emit('tutorial');
    }

    function revealDebugMap() {
        const state = getState();
        for (const map of mansionMaps(state)) map.markAllSeen();
        postTurn(state);
        emit('tutorial');
    }

    function grantDebugKey(keepGuardKeys: boolean) {
        const state = getState();
        state.player.hasVaultKey = true;
        if (!keepGuardKeys) {
            for (const map of mansionMaps(state)) for (const guard of map.guards) guard.hasVaultKey = false;
        }
    }

    function startOrResume() {
        const state = getState();
        state.phase = 'playing';
        if (!state.hasStartedGame) {
            state.gameStats.timeStarted = clock.now();
            state.persistedStats.totalPlays++;
            state.profile.writeStat('totalPlays',state.persistedStats.totalPlays);
            state.hasStartedGame = true;
        }
        emit('resume');
    }

    function restartSeededRun(start = true) {
        const state = getState();
        const isDailyRun = state.dailyRun !== null;
        const prepared = custom && buildCustomLevel(custom);
        state.completedLevels.clear();
        if (prepared) {
            state.rng = new RNG(prepared.spec.seed);
            state.gameMapRoughPlans = [prepared.spec];
        } else if (isDailyRun) {
            state.gameMapRoughPlans = createGameRoughPlansDailyRun(state.rng, ports.generatorVersion);
        } else {
            state.gameMapRoughPlans = normalPlans(state.rng, debugForceLevelType, ports.generatorVersion);
        }

        state.level = Math.min(state.gameMapRoughPlans.length - 1, debugInitialLevel);

        if (start) {
        state.persistedStats.totalPlays++;
        state.profile.writeStat('totalPlays',state.persistedStats.totalPlays);
        if (isDailyRun) {
            dailySummary(state).plays++;
            state.persistedStats.currentDailyPlays = dailySummary(state).plays;
            state.profile.writeStat('currentDailyPlays',state.persistedStats.currentDailyPlays);
            state.persistedStats.allDailyPlays++;
            state.profile.writeStat('allDailyPlays',state.persistedStats.allDailyPlays);
        }

        }
        state.hasStartedGame = start;
        state.runId = state.rng.seed + '/' + clock.now() + '/' + (++sequence);
        state.resultRecorded = null;
        state.gameStats = newRunStats(state.dailyRun, start ? clock.now() : 0);
        const gameMap = loadMansion(prepared?.mansion);
        state.player = new Player(gameMap.playerStartPos, isDailyRun);
        revealLaunchTile();
        state.phase = start ? 'playing' : 'configured';
        state.numStepMoves = 0;
        state.numLeapMoves = 0;
        state.numWaitMoves = 0;
        state.hasEnteredMansion = false;
        state.experiencedPlayer = !!custom || isDailyRun || debugLevelGen;
        state.finishedLevel = false;
        state.turns = 0;
        state.totalTurns = 0;
        state.lootStolen = 0;
        state.lootAvailable = state.gameMapRoughPlans[state.level].totalLoot;
        state.treasureStolen = 0;
        Object.assign(state.levelStats, newLevelStats());
        updateAchievements(state, "gameStart");
        identifyActiveFloor();

        emit('map');
        chooseGuardMoves(state);
        postTurn(state);
        emit('tutorial');


        emit('stop-sounds');
        emit('resume');
    }

    function startDaily() {
        if (custom) return;
        const state = getState();
        const date = getCurrentDateFormatted(new Date(clock.now()));
        rolloverDailyProfile(state, clock);
        state.rng = new RNG('Daily '+date);
        state.dailyRun = date;
        state.multiFloor = false;
        restartSeededRun();
    }

    function resetMansion() {
        if (custom) { restartSeededRun(); return; }
        const state = getState();
        const gameMap = loadMansion();
        state.player = new Player(gameMap.playerStartPos, state.dailyRun !== null);
        state.turns = 0;
        state.totalTurns = 0;
        state.lootStolen = 0;
        state.lootAvailable = state.gameMapRoughPlans[state.level].totalLoot;
        state.treasureStolen = 0;
        Object.assign(state.levelStats, newLevelStats());
        updateAchievements(state, "gameStart");

        state.finishedLevel = false;
        identifyActiveFloor();

        emit('map');
        chooseGuardMoves(state);
        postTurn(state);
        emit('tutorial');


        emit('stop-sounds');
        emit('resume');


    }

    function setupLevel(level: number) {
        const state = getState();
        state.level = level;
        if (state.level >= state.gameMapRoughPlans.length) {
            restartSeededRun();
            return;
        }

        loadMansion();
        state.finishedLevel = false;

        state.turns = 0;
        state.lootStolen = 0;
        state.treasureStolen = 0;
        state.lootAvailable = state.gameMapRoughPlans[state.level].totalLoot;

        Object.assign(state.levelStats, newLevelStats());

        const { health, loot } = state.player;
        Object.assign(state.player, new Player(state.gameMap.playerStartPos, state.dailyRun !== null), { health, loot });
        identifyActiveFloor();
        state.phase = 'playing';
        state.hasEnteredMansion = false;

        emit('map');
        chooseGuardMoves(state);
        postTurn(state);
        emit('tutorial');

        emit('resume');

    //    analyzeLevel(state);
    }

    function escape() {
        const state = getState();
        if (state.completedLevels.has(state.level)) return;
        scoreCompletedLevel(state, clock);
        updateAchievements(state, "levelEnd");
        emit('stop-sounds');
        emit('complete-level');
        if(state.levelStats.numSpottings === 0) {
            state.persistedStats.totalGhosts++;
            state.profile.writeStat('totalGhosts',state.persistedStats.totalGhosts);
        }

        state.phase = 'mansion-complete';
    }

    const turnHooks = {
        escape,
        death: () => { recordDeath(data, clock); data.phase = 'dead'; },
        turnEnd: () => updateAchievements(data, 'turnEnd'),
    };
    data.turnHooks = turnHooks;
    function execute(command: SessionCommand): CommandResult {
        if (data.phase !== 'playing') return Object.freeze({ accepted: false, turnConsumed: false, events: [], outcome: data.phase });
        const before = data.turns;
        const damageBefore = data.levelStats.damageTaken;
        const departureFloor = data.floorId;
        const departureMap = data.gameMap;
        const departureIdentity = identities;
        const modes = new Map(departureMap.guards.map(guard => [guard, guard.mode]));
        const output = recordFeedback(identities);
        const previous = data.feedback;
        data.feedback = output.feedback;
        data.turnHooks = {
            ...turnHooks,
            floorChanged(floor) {
                data.floorId = floor.id;
                identifyActiveFloor();
                output.events.push(Object.freeze({type:'floor-changed', from:departureFloor, to:floor.id}));
                data.feedback = recordFeedback(identities, output.events).feedback;
                revealThroughOpenings();
                emit('floor');
            },
        };
        pending = [];
        try {
            const previousPos = vec2.clone(data.player.pos);
            dispatchCommand(data, command);
            if (data.mansion && data.turns !== before && data.phase === 'playing') {
                const activeFloor = data.floorId;
                const response = pursuit.advance(data.mansion, activeFloor, data.player);
                if (response.arrivals) {
                    identifyActiveFloor();
                    chooseGuardMoves(data);
                    emit('reinforcement');
                }
                if (response.spottings) {
                    data.levelStats.numSpottings += response.spottings;
                    updateAchievements(data, 'turnEnd');
                }
                const moved = !data.player.pos.equals(previousPos);
                const stair = activeFloor === departureFloor && moved && !data.player.elevated
                    ? departureMap.stairAt(data.player.pos) : undefined;
                const floor = stair && data.mansion.floors.find(candidate => candidate.id === stair.destination);
                const reciprocal = floor?.map.stairs.find(candidate => candidate.destination === departureFloor);
                const landing = floor && reciprocal && landingBesideLadder(floor.map, reciprocal, pos =>
                    floor.map.guards.some(guard => guard.pos.equals(pos)));
                if (floor && landing) {
                    pursuit.followDeparture(data.mansion, departureFloor, floor.id);
                    moveToFloor(data, floor, landing);
                } else {
                    if (stair) data.feedback.notify('Ladder landing blocked', data.player);
                    if (activeFloor !== departureFloor) pursuit.followDeparture(data.mansion, departureFloor, activeFloor);
                    else if (moved) revealThroughOpenings();
                }
                updateMansionProgress(data);
            }
        }
        finally {
            data.feedback = previous;
            data.turnHooks = turnHooks;
            const completed = pending;
            pending = undefined;
            for (const event of completed) deliver(event);
        }
        const damage = data.levelStats.damageTaken - damageBefore;
        if (damage > 0) output.events.push(Object.freeze({
            type: 'player-damaged', amount: damage, healthRemaining: data.player.health,
        }));
        for (const guard of departureMap.guards) {
            if (guard.mode === GuardMode.Unconscious && modes.get(guard) !== GuardMode.Unconscious) {
                output.events.push(Object.freeze({ type: 'guard-knocked-out', guardId: departureIdentity.identify(guard),
                    position: Object.freeze([...guard.pos]) }));
            }
        }
        const turnConsumed = data.turns !== before;
        const accepted = turnConsumed || data.phase !== 'playing' ||
            output.events.some(event => event.type === 'presentation' && event.kind !== 'beginAction');
        return Object.freeze({ accepted, turnConsumed, events: Object.freeze(output.events), outcome: data.phase });
    }
    function revealThroughOpenings() {
        const {mansion, gameMap, player} = data;
        if (!mansion) return;
        for (const index of gameMap.openings) {
            const pos = vec2.fromValues(index % gameMap.cells.sizeX, Math.floor(index / gameMap.cells.sizeX));
            if (vec2.squaredDistance(player.pos, pos) > 400) continue;
            const below = exposedFloorAt(mansion, data.floorId, pos);
            if (below && !below.map.cells.atVec(pos).seen && lineOfSightToPosition(gameMap, player.pos, pos)) {
                below.map.cells.atVec(pos).seen = true;
            }
        }
    }

    function revealLaunchTile() {
        if (!custom) return;
        data.gameMap.recomputeVisibility(data.player.pos);
        data.gameMap.identifyAdjacentCells(data.player.pos);
        revealThroughOpenings();
    }

    identifyActiveFloor();
    revealLaunchTile();
    chooseGuardMoves(data);
    postTurn(data);
    return {
        read: () => data as GameReadModel,
        execute,
        identities: () => identities,
        observe(listener: (event: SessionEvent) => void) { sink = listener; },
        refreshDaily: () => rolloverDailyProfile(getState(), clock),
        startOrResume, newNormalRun, startMultiFloorRun: () => newNormalRun(true), restartCurrentRun, restartSeededRun, startDaily, resetMansion,
        resetProfile() { profile.clear(); data.persistedStats = profile.readStats(); Object.assign(data, profile.readSettings()); leaveResults(); },
        escape, nextMansion, completeRun, leaveResults, openMenu, moveDebugLevel,
        collectDebugLoot, revealDebugMap, grantDebugKey,
    };
}

export type GameSession = ReturnType<typeof createGameSession>;
