export class DailyHubScreen extends TextWindow {
    pages = [
`The Daily Challenge

Play a new seeded game each day and
compare results with your rivals.

$dailyStatus$
Plays:             $plays$
Wins:              $wins$
Best score:        $bestScore$

$playMode$
$timeLeft$

Last game played:  $lastPlayed$
Last score:        $lastScore$
[S|scorePopup] Score popup (for copy/paste)

[Esc|menuBack] Back to menu`,
    ];
    timeToMidnightUTC():string {
        const d = new Date();
        const dm = new Date(d);
        dm.setUTCHours(24,0,0,0);
        const duration = dm.getTime() - d.getTime();
        const seconds = Math.floor((duration / 1000) % 60);
        const minutes = Math.floor((duration / (1000 * 60)) % 60);
        const hours = Math.floor((duration / (1000 * 60 * 60)) % 24);

        return hours.toString().padStart(2,'0') + ":"
            + minutes.toString().padStart(2,'0') + ":"
            + seconds.toString().padStart(2,'0');
      }
    update(state:State) {
        const lastDailyGameStats = state.game.persistedStats.lastPlayedDailyGame;
        state.session.refreshDaily();
        if(lastDailyGameStats !== null && state.game.persistedStats.currentDailyPlays>0) {
            if(state.game.persistedStats.currentDailyWins===0) {
                this.state.set('dailyStatus', state.game.persistedStats.currentDailyGameId+' game played');
            } else if(state.game.persistedStats.currentDailyWinFirstTry===0) {
                this.state.set('dailyStatus', state.game.persistedStats.currentDailyGameId+' game won');
            } else {
                const tile = spriteTag(getEntityTileSet().itemTiles[ItemType.TorchLit]);
                this.state.set('dailyStatus', state.game.persistedStats.currentDailyGameId+` game won first try ${tile}`);
            }
            this.state.set('timeLeft', "Time to next game: "+this.timeToMidnightUTC());
            this.state.set('playMode', '[P|homePlay] Play it again');
        } else {
            this.state.set('dailyStatus', state.game.persistedStats.currentDailyGameId+` game ready`);
            this.state.set('timeLeft', "Time left to play: "+this.timeToMidnightUTC());
            this.state.set('playMode', '[P|homePlay] Play now');
        }

        const lastDailyDate: string = lastDailyGameStats?.daily ?? 'None';
        const lastDailyScore: number = lastDailyGameStats?.totalScore ?? 0;

        this.state.set('plays', state.game.persistedStats.currentDailyPlays.toString());
        this.state.set('wins', state.game.persistedStats.currentDailyWins.toString());
        this.state.set('lastPlayed', lastDailyDate);
        this.state.set('lastScore', lastDailyScore.toString());
        this.state.set('bestScore', state.game.persistedStats.currentDailyBestScore.toString());
    }
    onControls(state:State, activated:(action:string)=>boolean) {
        if (modalVisible) {
            if (activated('menuAccept') || activated('menuBack')) {
                hideModal();
            }
        } else {
            const action = this.navigateUI(activated);
            if (activated('menuToggle')) {
                state.session.startOrResume();
            } else if (activated('menuBack') || action=='menuBack') {
                state.gameMode = GameMode.HomeScreen;
            } else if (activated('homePlay') || action=='homePlay') {
                state.session.startDaily();

            } else if (activated('scorePopup') || action=='scorePopup') {
                displayScorePopup(state.game.persistedStats.lastPlayedDailyGame, state.game.achievements);
            }
        }
    };
}

