import { spriteAtlasIds, spriteSheets } from '../tilesets';
import type { Howls,SubtitledHowls } from '../audio';
import { ActiveHowlPool,Howler,setupSounds } from '../audio';
import { TouchController } from '../controllers';
import { legacyGeneratorVersion } from '../core/versions';
import { Renderer } from '../render';
import { disposeAccessibleView } from './accessibility';
import { initState } from './application';
import { updateAndRender } from './frame';
import { mountLevelEditor } from './level-editor';
import { hideModal } from './modal';
import { soundShouldBeMuted } from './settings';
import { entityTileSet,fontTileSet,terrainTileSet } from './tiles';

export function startBrowserGame() {
    const lifetime = new AbortController();
    let loading: AbortController | undefined, stop: (()=>void) | undefined;
    const status = (message: string, retry: boolean) => {
        let element = document.getElementById('startupStatus');
        if (!element) { element = document.createElement('div'); element.id='startupStatus'; element.setAttribute('role','alert'); document.body.append(element); }
        element.replaceChildren(document.createTextNode(message));
        element.style.cssText='position:fixed;inset:25%;background:#101;color:white;padding:2rem;z-index:3';
        if (retry) { const button=document.createElement('button');button.textContent='Retry';button.onclick=boot;element.append(button);button.focus(); }
    };
    const failure = (error: unknown) => {
        stop?.(); stop=undefined;
        status(error instanceof Error ? error.message : 'The game could not start.', true);
    };
    async function boot() {
        stop?.(); loading?.abort(); loading=new AbortController();
        const signal=loading.signal;
        status('Loading game…',false);
        try {
            const canvas=document.querySelector('canvas');
            if (!canvas) throw new Error('The game canvas is missing. Reload this page to try again.');
            await Promise.all(spriteAtlasIds.map(atlas => {
                const {imageSrc, image} = spriteSheets[atlas];
                return loadImage(imageSrc, image, signal);
            }));
            if (signal.aborted) return;
            stop=run(canvas,failure);
            document.getElementById('startupStatus')?.remove();
        } catch(error) { if (!signal.aborted) { failure(error); loading?.abort(); } }
    }
    function dispose() {
        lifetime.abort();loading?.abort();stop?.();stop=undefined;
        document.getElementById('startupStatus')?.remove();
    }
    window.addEventListener('pagehide',dispose,{signal:lifetime.signal});
    if (document.readyState==='complete') void boot();
    else window.addEventListener('load',()=>void boot(),{once:true,signal:lifetime.signal});
    return {dispose};
}

function run(canvas: HTMLCanvasElement, failure: (error:unknown)=>void) {
    const lifetime=new AbortController(), signal=lifetime.signal;
    const renderer=new Renderer(canvas,terrainTileSet,entityTileSet,fontTileSet,spriteSheets);
    const sounds:Howls={},subtitledSounds:SubtitledHowls={};
    const activeSoundPool=new ActiveHowlPool(),ambientSoundPool=new ActiveHowlPool();
    const touchController=new TouchController(canvas);
    let state: ReturnType<typeof initState>;
    try {
        const requestedVersion = new URLSearchParams(window.location.search).get('generator');
        const version = requestedVersion === String(legacyGeneratorVersion) ? legacyGeneratorVersion : undefined;
        state = initState(sounds, subtitledSounds, activeSoundPool, ambientSoundPool, touchController, version);
        mountLevelEditor(state, canvas, signal);
    }
    catch(error) { renderer.dispose();touchController.dispose();throw error; }
    let width=canvas.clientWidth,height=canvas.clientHeight,raf=0,audioReady=false,disposed=false;
    function ensureSound() {
        if (audioReady) return;
        audioReady=true;
        try {
            setupSounds(sounds,subtitledSounds,activeSoundPool,ambientSoundPool);
            Howler.volume(state.soundVolume);Howler.mute(soundShouldBeMuted(state));
            for (const sound of Object.values(subtitledSounds)) sound.mute=state.guardMute;
        } catch { canvas.dataset.audio='unavailable'; }
    }
    document.body.addEventListener('keydown',ensureSound,{signal});
    canvas.addEventListener('mousedown',ensureSound,{signal});
    canvas.addEventListener('touchstart',ensureSound,{signal});
    window.addEventListener('gamepadconnected',ensureSound,{signal});
    window.addEventListener('blur',()=>Howler.mute(soundShouldBeMuted(state)),{signal});
    window.addEventListener('focus',()=>Howler.mute(soundShouldBeMuted(state)),{signal});
    const observer=new ResizeObserver(()=>{
        width=canvas.clientWidth;height=canvas.clientHeight;state.camera.snapped=false;
        try { screen.orientation?.unlock?.(); } catch { /* Optional platform capability. */ }
    });
    observer.observe(canvas);
    function dispose() {
        if (disposed) return;disposed=true;lifetime.abort();cancelAnimationFrame(raf);observer.disconnect();
        state.timers.clear();state.keyboardController.dispose();state.gamepadManager.dispose();touchController.dispose();
        activeSoundPool.dispose();ambientSoundPool.dispose();Howler.unload();renderer.dispose();
        hideModal();disposeAccessibleView();canvas.dataset.status='stopped';
    }
    canvas.addEventListener('webglcontextlost',event=>{
        event.preventDefault();dispose();failure(new Error('Graphics were interrupted. Retry to reload the game.'));
    },{signal});
    function frame(now:number) {
        if (disposed) return;
        try { if (!state.levelEditor?.isOpen()) updateAndRender(now,renderer,state,canvas,width,height); }
        catch(error) { dispose();failure(error);return; }
        raf=requestAnimationFrame(frame);
    }
    canvas.dataset.status='running';raf=requestAnimationFrame(frame);
    return dispose;
}

function loadImage(src:string,image:HTMLImageElement,signal:AbortSignal):Promise<void> {
    return new Promise((resolve,reject)=>{
        const timer=setTimeout(()=>finish(new Error('Game images took too long to load. Check your connection and retry.')),15000);
        const aborted=()=>finish(new Error('Loading cancelled.'));
        function finish(error?:Error) {
            clearTimeout(timer);image.onload=null;image.onerror=null;signal.removeEventListener('abort',aborted);
            if(error)reject(error);else resolve();
        }
        image.onload=()=>finish();image.onerror=()=>finish(new Error('Game images could not load. Check your connection and retry.'));
        signal.addEventListener('abort',aborted,{once:true});image.src=src;
    });
}
