import type { GameSession as ApplicationSession,SessionEvent } from '../application/session';
import { createGameSession } from '../application/session';
import { Howler } from '../audio';
import { vec2 } from '../my-matrix';
import { ambienceAtPlayer,playAmbience } from './ambience';
import { prepareMapVisuals } from './animation';
import { createCamera } from './camera';
import { presentEvents } from './events';
import { resetHealthBar } from './health-bar';
import { mansionCompleteTopStatusHint } from './messages';
import type { State } from './state';
import { AmbienceType,GameMode } from './state';
import { showMoveTutorialNotifications } from './tutorials';

export function resetMapPresentation(state: State, arriving = false) {
    const cursor = state.visuals.player(state.game.player).idleCursorType;
    state.timers.clear();
    state.particles = [];
    state.popups.reset();
    state.lightStates = Array(state.game.gameMap.lightCount).fill(0);
    prepareMapVisuals(state.game.gameMap, state);
    resetHealthBar(state);
    state.camera = createCamera(state.game.player.pos, state.zoomLevel);
    state.camera.zoomed = arriving;
    state.oldPlayerPos = vec2.clone(state.game.player.pos);
    state.ambience = arriving || state.game.customTitle ? ambienceAtPlayer(state) : AmbienceType.Outdoor;
    state.activeSoundPool.empty();
    state.ambientSoundPool.empty();
    if (arriving) {
        state.visuals.player(state.game.player).idleCursorType = cursor;
        playAmbience(state);
    }
    if (state.game.multiFloor || state.game.customTitle) state.hintMessage = '';
}

export function attachSession(session: ApplicationSession, state: State) {
    session.observe((event: SessionEvent) => {
        switch (event) {
            case 'tutorial': showMoveTutorialNotifications(state, state.game.player.pos); break;
            case 'map':
            case 'floor': {
                resetMapPresentation(state, event === 'floor');
                break;
            }
            case 'reinforcement':
                while (state.lightStates.length < state.game.gameMap.lightCount) state.lightStates.push(0);
                break;
            case 'stop-sounds':
                state.timers.clear();
                state.activeSoundPool.cancelPending?.();
                state.ambientSoundPool.cancelPending?.();
                Howler.stop(); break;
            case 'resume': playAmbience(state); break;
            case 'complete-run': state.sounds.victorySong?.play(0.5); break;
            case 'complete-level':
                state.hintMessage = state.game.customTitle ? '' : mansionCompleteTopStatusHint[state.game.level] ?? '';
                state.sounds.levelCompleteJingle?.play(0.35);
                break;
            case 'camera-fit': state.camera.zoomed = false; break;
            case 'menu': state.timers.clear(); state.gameMode = state.game.player.health > 0 ? GameMode.HomeScreen : GameMode.Dead; break;
        }
    });
    const sync = () => {
        const phase = session.read().phase;
        const screens = { configured: GameMode.HomeScreen, playing: GameMode.Mansion,
            'mansion-complete': GameMode.MansionComplete, dead: GameMode.Mansion, won: GameMode.Win };
        state.gameMode = screens[phase];
    };
    const methods = { ...session };
    for (const key of ['startOrResume','newNormalRun','startMultiFloorRun','restartCurrentRun','restartSeededRun','startDaily',
        'resetMansion','nextMansion','completeRun','moveDebugLevel','execute'] as const) {
        const operation = session[key] as (...args: any[]) => unknown;
        Object.assign(methods, { [key]: (...args: any[]) => { const result = operation(...args);
            if (key === 'execute' && state.feedback) {
                const {events} = result as ReturnType<ApplicationSession['execute']>;
                const arrivedAt = events.findIndex(event => event.type === 'floor-changed');
                // Keep feedback that applies to the player across floors.
                const visible = arrivedAt < 0 ? events : events.filter((event, index) =>
                    index > arrivedAt || event.type === 'presentation' &&
                    (event.kind === 'beginAction' || event.kind === 'sound' || event.kind === 'flashHeart' || event.kind === 'enlargeHealthBar'));
                presentEvents(visible, state.feedback, session.identities());
            }
            sync();
            return result; } });
    }
    return methods;
}
export { createGameSession };
export type GameSession = ApplicationSession;
