import type { ActiveHowlPool,Howls,SubtitledHowls } from '../audio';
import type { TouchController } from '../controllers';
import { GamepadManager,KeyboardController } from '../controllers';
import type { GeneratorVersion } from '../core/versions';
import { vec2 } from '../my-matrix';
import { Popups } from '../popups';
import { ProfileStore } from '../profile/store';
import { AchievementsScreen,CreditsScreen,DailyHubScreen,DeadScreen,DevScreen,HelpControls,HelpKey,HomeScreen,MansionCompleteScreen,OptionsScreen,StatsScreen,WinScreen } from '../ui';
import { prepareMapVisuals } from './animation';
import { createCamera,initZoomLevel } from './camera';
import { debugLevelGen,debugSeeAll } from './debug-config';
import { createTurnFeedback } from './feedback';
import { attachSession,createGameSession } from './session';
import type { State } from './state';
import { AmbienceType,GameMode } from './state';
import { browserStorage } from './storage';
import { TimerScope } from './timers';
import { showMoveTutorialNotifications } from './tutorials';
import { WorldVisuals } from './visuals';

export function initState(sounds:Howls, subtitledSounds: SubtitledHowls, activeSoundPool:ActiveHowlPool,
    ambientSoundPool:ActiveHowlPool, touchController:TouchController, generatorVersion?: GeneratorVersion): State {
    const profile = new ProfileStore(browserStorage());

    const settings = profile.readSettings();
    const application = createGameSession({ profile, generatorVersion });
    const run = application.read();
    const {gameMap, player} = run;

    const state: State = {
        game: run,
        profile,
        ...settings,
        session: application,
        timers: new TimerScope(),
        lightStates: Array(gameMap.lightCount).fill(0),
        particles:[],
        visuals: new WorldVisuals(),
        tLast: undefined,
        dt: 0,
        frameElapsed: 0,
        idleTimer: 5,
        fpsInfo: {enabled: false, msgFPS: 'FPS: --', frames:0, cumulativeTime:0, worstFrame:0, drops:0},
        devMode: debugLevelGen,
        leapToggleActive: false,
        healthBarState: {
            damageDisplayTimer: 0,
            healing: false,
            size: 1,
            enlargeTimeRemaining: 0,
            heartFlashRemaining: Array(player.healthMax).fill(0),
        },
        gameMode: debugLevelGen ? GameMode.Mansion : GameMode.HomeScreen,
        textWindows: {
            [GameMode.HomeScreen]: new HomeScreen(),
            [GameMode.OptionsScreen]: new OptionsScreen(),
            [GameMode.StatsScreen]: new StatsScreen(),
            [GameMode.AchievementsScreen]: new AchievementsScreen(),
            [GameMode.DailyHub]: new DailyHubScreen(),
            [GameMode.HelpControls]: new HelpControls(),
            [GameMode.HelpKey]: new HelpKey(),
            [GameMode.MansionComplete]: new MansionCompleteScreen(),
            [GameMode.Dead]: new DeadScreen(),
            [GameMode.Win]: new WinScreen(),
            [GameMode.CreditsScreen]: new CreditsScreen(),
            [GameMode.DevScreen]: new DevScreen(),
        },
        ambience: AmbienceType.Outdoor,
        ambientSoundPool: ambientSoundPool,
        oldPlayerPos: vec2.clone(gameMap.playerStartPos),
        hintMessage: '',
        numZoomMoves: 0,
        zoomLevel: initZoomLevel,
        seeAll: debugSeeAll,
        seeGuardSight: false,
        seeGuardPatrols: false,
        seeRoomAdjacencies: false,
        camera: createCamera(gameMap.playerStartPos, initZoomLevel),
        sounds: sounds,
        subtitledSounds: subtitledSounds,
        activeSoundPool: activeSoundPool,
        keyRepeatActive: undefined,
        touchController: touchController,
        gamepadManager: new GamepadManager(),
        keyboardController: new KeyboardController(),
        popups: new Popups,
    };

    state.session = attachSession(application, state);
    state.feedback = createTurnFeedback(state);
    prepareMapVisuals(gameMap, state);
    showMoveTutorialNotifications(state, state.game.player.pos);

    return state;
}
