import { generatorVersion,legacyGeneratorVersion,rulesVersion } from '../core/versions';
import { RNG } from '../random';
import type { LevelSpec } from '../run/state';
import type { GameMap } from '../world/game-map';
import { BooleanGrid,ItemType,LevelType } from '../world/game-map';
import { makeWarrens } from './experimental/warrens';
import { addAdditionalFortressDoors,assignRoomTypes,assignVaultRoom,computeAdjacencies,computeRoomDepths,connectRooms,createRooms,estimateBacktracking,insideIsHorizontallySymmetric,insideIsVerticallySymmetric,makeDoubleRooms,makeFortressRoomGrid,makeManorRoomGrid,makeMansionRoomGrid,mirrorOffsetsBottomToTop,mirrorOffsetsLeftToRight,offsetBuilding,offsetWalls,outerBorder,outerBorderBottom,roomSizeX,roomSizeY,storeAdjacenciesInRooms } from './geometry';
import type { PatrolRoute } from './patrols';
import { addStationaryPatrols,appendOutsidePatrolRoutes,placePatrolRoutesDense,placePatrolRouteSingle } from './patrols';
import { giveBooksTitles,markExteriorAsSeen,placeGuards,placeHealth,placeLoot,placeTreasure } from './population';
import { GenerationContext } from './stages';
import { validateFinalMap,validateRoomGraph } from './validation';
import { cacheCellInfo,createBlankGameMap,elevatedStartPosition,fixupWalls,openFloorExterior,outerBuildingPerimeter,placeExteriorBushes,placeFrontPillars,playerStartPosition,renderRooms,renderWalls } from './world-building';

export function createGameMap(plan: LevelSpec, {openExterior = false} = {}): GameMap {
    if (!plan || ![LevelType.Manor,LevelType.ManorRed,LevelType.Mansion,LevelType.Fortress,LevelType.Warrens].includes(plan.levelType) || !Number.isInteger(plan.difficulty) || plan.difficulty < 0 || plan.difficulty > 9 ||
        !Number.isInteger(plan.numRoomsX) || plan.numRoomsX < 1 || plan.numRoomsX > 20 ||
        !Number.isInteger(plan.numRoomsY) || plan.numRoomsY < 1 || plan.numRoomsY > 20 ||
        !Number.isSafeInteger(plan.totalLoot) || plan.totalLoot < 0 || typeof plan.seed !== 'string' || !plan.seed ||
        (plan.generatorVersion !== generatorVersion && plan.generatorVersion !== legacyGeneratorVersion) ||
        plan.rulesVersion !== rulesVersion)
        throw new RangeError('Invalid or unsupported versioned level specification');
    const context = new GenerationContext(plan);
    try { const map = generate(plan, context, openExterior); context.enter('validation'); validateFinalMap(map, plan); return map; } catch (error) { throw context.failure(error); }
}

function generate(plan: LevelSpec, context: GenerationContext, openExterior: boolean): GameMap {
    const rng = new RNG(plan.seed);

    const level = plan.difficulty;
    const levelType = plan.levelType;
    const mirrorLayout = plan.generatorVersion === legacyGeneratorVersion;

    if (levelType === LevelType.Warrens) {
        context.enter('layout');
        return makeWarrens(level, plan.numRoomsX, plan.numRoomsY, plan.totalLoot, rng, context, openExterior);
    }

    context.enter('layout');
    // Keep room connections indoors when there is no yard on this story.

    const inside = new BooleanGrid(plan.numRoomsX, plan.numRoomsY, true);

    switch (levelType) {
    case LevelType.Manor:
    case LevelType.ManorRed:
        if (!openExterior) makeManorRoomGrid(inside, rng, mirrorLayout);
        break;

    case LevelType.Mansion:
        makeMansionRoomGrid(inside, rng);
        break;

    case LevelType.Fortress:
        if (!openExterior) makeFortressRoomGrid(inside, rng);
        break;
    }

    /*
    console.log('Finished grid:');
    for (let y = inside.sizeY - 1; y >= 0; --y) {
        let s: string = y.toString() + ': ';
        for (let x = 0; x < inside.sizeX; ++x) {
            s += inside.get(x, y) ? 'X' : '.';
        }
        console.log(s);
    }
    */

    // Randomly offset walls.

    const forceTJunctionProbability = 0.75;
    const randomJunctionOrientationProbability = 0.5;
    const straightWallMinX = rng.random() < 0.25;
    const straightWallMaxX = mirrorLayout ? straightWallMinX : rng.random() < 0.25;
    const straightWallMinY = mirrorLayout ? straightWallMinX : rng.random() < 0.25;
    const straightWallMaxY = mirrorLayout ? straightWallMinX : rng.random() < 0.25;

    const roomVarianceX = 3;
    const roomVarianceY = 3;

    const [offsetX, offsetY] = offsetWalls(
        plan.numRoomsX,
        plan.numRoomsY,
        roomSizeX,
        roomSizeY,
        roomVarianceX,
        roomVarianceY,
        forceTJunctionProbability,
        randomJunctionOrientationProbability,
        straightWallMinX,
        straightWallMinY,
        straightWallMaxX,
        straightWallMaxY,
        rng);

    // Preserve mirrored walls when replaying earlier generator specs.

    const mirrorRoomsX = mirrorLayout && (plan.numRoomsX & 1) === 1 && insideIsHorizontallySymmetric(inside);
    if (mirrorRoomsX) {
        mirrorOffsetsLeftToRight(offsetX, offsetY);
    }

    const mirrorRoomsY = mirrorLayout && (plan.numRoomsY & 1) === 1 &&
        insideIsVerticallySymmetric(inside) && (!mirrorRoomsX || rng.random() < 0.5);
    if (mirrorRoomsY) {
        mirrorOffsetsBottomToTop(offsetX, offsetY);
    }

    // Translate the building so it abuts the X and Y axes with outerBorder/outerBorderBottom padding

    offsetBuilding(offsetX, offsetY, outerBorder, outerBorderBottom);

    // Make a set of rooms.

    const [rooms, roomIndex] = createRooms(inside, offsetX, offsetY, levelType);

    context.enter('topology');
    // Compute a list of room adjacencies.

    const mirrorAdjacencies = mirrorLayout && rng.randomInRange(24) >= level;
    const mirrorAdjacenciesX = mirrorRoomsX && mirrorAdjacencies;
    const mirrorAdjacenciesY = mirrorRoomsY && mirrorAdjacencies;

    const adjacencies = computeAdjacencies(mirrorAdjacenciesX, mirrorAdjacenciesY, offsetX, offsetY, rooms, roomIndex);
    storeAdjacenciesInRooms(adjacencies);

    // Join rooms to make bigger rooms.

//    joinRoomsWarren(rooms, adjacencies, rng);

    // Connect rooms together.

    rng.shuffleArray(adjacencies);
    connectRooms(rooms, adjacencies, level, levelType, rng, mirrorLayout);

    // Join a pair of rooms together.

    makeDoubleRooms(rooms, adjacencies, rng);

    // In fortresses, connectRooms added only the bare minimum of doors necessary to connect the level.
    //  Add additional doors now, but lock them.

    if (levelType === LevelType.Fortress) {
        computeRoomDepths(rooms);
        assignVaultRoom(rooms, level, levelType, rng);
        addAdditionalFortressDoors(adjacencies, rng);
    }

    context.enter('analysis');
    // Compute room distances from entrance.

    computeRoomDepths(rooms);

    // Compute a measure of how much each room is on paths between other rooms.


    validateRoomGraph({rooms, adjacencies});
    context.enter('roles');
    // Assign types to the rooms.

    assignRoomTypes(rooms, level, levelType, rng);

    context.enter('construction');
    // Create the actual map

    const map = createBlankGameMap(levelType, rooms);
    map.backtrackingCoefficient = estimateBacktracking(rooms);
    const entry = openExterior ? openFloorExterior(map, rooms, adjacencies, levelType) : undefined;

    // Render doors and windows.

    renderWalls(levelType, adjacencies, map);

    //verifyRoomsHaveDoors(rooms, map, rng.seed);

    // Render floors.

    renderRooms(level, levelType, rooms, map, rng);

    let outsidePatrolRoute: PatrolRoute | undefined;
    if (!entry) {
        map.playerStartPos = playerStartPosition(level, levelType, adjacencies, map);
        outsidePatrolRoute = {
            path: outerBuildingPerimeter(adjacencies, map),
            minRoomDepth: rooms[0].depth,
            maxRoomDepth: rooms[0].depth,
        };
        placeExteriorBushes(map, outsidePatrolRoute.path, rng);
        placeFrontPillars(map, mirrorLayout ? undefined : rng, outsidePatrolRoute.path);
    }

    // Convert walls to proper straight, corner, T-junction, cross tiles

    fixupWalls(map.cells);

    // Cache info about how the cells in the map affect sound, lighting, and movement

    cacheCellInfo(map);
    if (entry) map.playerStartPos = elevatedStartPosition(map, entry);

    context.enter('patrols');
    // Place patrol routes

    let patrolRoutes: Array<PatrolRoute>;
    if (level < 1) {
        patrolRoutes = [];
    } else if (level < 2) {
        patrolRoutes = placePatrolRouteSingle(map, rooms, rng);
    } else {
        patrolRoutes = placePatrolRoutesDense(levelType, level, map, rooms, adjacencies, rng);
//        patrolRoutes = placePatrolRoutes(level, map, rooms, adjacencies, rng);
//        patrolRoutes = placePatrolRouteSingle(map, rooms, rng);
//        patrolRoutes = placePatrolRouteSingleDense(levelType, map, rooms, rng);
//        patrolRoutes = placePatrolRoutesLong(map, rooms, rng);
//        patrolRoutes = placePatrolRouteLargeLoop(map, rooms, rng);

        // Past level 5, include patrols around the outside of the mansion.
        // Keep these ones at the end so they won't get keys or purses.

        if (level > 5 && outsidePatrolRoute) {
            appendOutsidePatrolRoutes(outsidePatrolRoute, patrolRoutes);
        }
    }

    const needKey = map.items.find((item) => item.type === ItemType.LockedDoorNS || item.type === ItemType.LockedDoorEW) !== undefined;
    addStationaryPatrols(level, map, rooms, needKey, patrolRoutes, rng);

    context.enter('population');
    // Place loot

    const guardsAvailableForLoot = patrolRoutes.length - (needKey ? 1 : 0);
    const guardLoot = Math.min(Math.floor(level/3), Math.min(guardsAvailableForLoot, plan.totalLoot));

    placeLoot(plan.totalLoot - guardLoot, rooms, map, patrolRoutes, levelType, rng);
    giveBooksTitles(map.bookTitle, rooms, map.items.filter(item=>item.type === ItemType.Bookshelf), rng);
    placeTreasure(map, rooms, rng);

    placeHealth(level, map, rooms, rng);

    // Put guards on the patrol routes

    placeGuards(level, map, patrolRoutes, guardLoot, needKey, rng);

    context.enter('finalization');
    // Final setup

    if (!entry) markExteriorAsSeen(map);
    map.computeLighting(null);
    map.recomputeVisibility(map.playerStartPos);

    map.rooms = rooms.map(room => ({ posMin: room.posMin, posMax: room.posMax }));
    map.adjacencies = adjacencies;

    return map;
}
