import type { GuardData } from './guard';
import { GuardMode } from './guard-mode';

export function isRelaxedGuardMode(guardMode: GuardMode): boolean {
    return guardMode === GuardMode.Patrol ||
           guardMode === GuardMode.MoveToTorch ||
           guardMode === GuardMode.LightTorch;
}

export function isAlertGuard(guard: Pick<GuardData, 'mode'>): boolean {
    return guard.mode !== GuardMode.Unconscious && guard.mode !== GuardMode.ChaseVisibleTarget && !isRelaxedGuardMode(guard.mode);
}
