import { vec2 } from '../my-matrix';
import { mansionParTurns } from '../run/scoring';
import { mansionMaps,type MansionFloor } from '../world/mansion';
import type { Item } from '../world/game-map';
import { ItemType,maxPlayerTurnsUnderwater,TerrainType } from '../world/game-map';
import { chooseGuardMoves,guardActAll } from './guards';
import type { SimulationState } from './state';

export function preTurn(state: SimulationState) {
    state.player.noisy = false;
    state.player.damagedLastTurn = false;
    state.player.itemUsed = null;
    state.player.lightActive = false;
    state.feedback?.advanceNotification();
}

export function moveToFloor(state: SimulationState, floor: MansionFloor, landing: vec2, elevated = false) {
    state.gameMap.computeLighting(null);
    state.gameMap = floor.map;
    const {player} = state;
    vec2.copy(player.pos, landing);
    vec2.set(player.noiseOffset, 0, 0);
    player.noisy = false;
    player.preNoisy = false;
    player.lightActive = false;
    player.itemUsed = null;
    player.interactionTarget = null;
    player.turnsRemainingUnderwater = maxPlayerTurnsUnderwater;
    player.elevated = elevated;
    floor.map.computeLighting(player);
    floor.map.recomputeVisibility(landing);
    floor.map.identifyAdjacentCells(landing);
    chooseGuardMoves(state);
    state.turnHooks?.floorChanged?.(floor);
}

export function advanceTime(state: SimulationState) {
    state.player.preNoisy = false;
    ++state.turns;
    ++state.totalTurns;
    if (!state.player.elevated && state.gameMap.cells.atVec(state.player.pos).type == TerrainType.GroundWater) {
        if (state.player.turnsRemainingUnderwater > 0) {
            --state.player.turnsRemainingUnderwater;

            if (state.player.turnsRemainingUnderwater <= 0) {
                state.feedback?.sound('waterExit', 0.25);
            }
        }
    } else {
        state.player.turnsRemainingUnderwater = maxPlayerTurnsUnderwater;
    }

    state.gameMap.computeLighting(state.player);

    if (state.player.health > 0) guardActAll(state);

    state.gameMap.recomputeVisibility(state.player.pos);

    chooseGuardMoves(state);
    postTurn(state);

    if (state.player.damagedLastTurn) {
        state.feedback?.sound('hitPlayer', 0.5);

        if (state.player.health <= 0) {
            state.feedback?.delaySound('gameOverJingle', 0.5, 1000);
            state.turnHooks?.death();
        }
    }

    state.turnHooks?.turnEnd();
}

export function updateMansionProgress(state: SimulationState) {
    if (state.finishedLevel || state.lootStolen < state.lootAvailable ||
        !mansionMaps(state).every(map => map.allSeen())) return;

    state.finishedLevel = true;
    state.feedback?.sound('levelRequirementJingle', 0.5);
    const hint = state.gameMap.allowsEscape ? '\x88\x89Escape!' : 'Return to\nfirst floor';
    state.feedback?.notify(hint, state.player, 3, 5.0);
}

export function postTurn(state: SimulationState) {
    updateMansionProgress(state);

    const numTurnsPar = mansionParTurns(state);
    if (state.level > 0 && (state.turns === Math.floor(0.75*numTurnsPar) || state.turns === numTurnsPar-10 && numTurnsPar>100)) {
        state.feedback?.notify('\x8c\x8dTick tock!', state.player, 3, 5.0);
        state.feedback?.sound('clockTick', 1.0);
    }
    if (state.turns === numTurnsPar + 1) {
        let itemsRemoved = false;
        for (const map of mansionMaps(state)) {
            const vaultItems: Item[] = [];
            map.items = map.items.filter(item => {
                if (item.type !== ItemType.VaultTreasureBox) return true;
                vaultItems.push(item);
                return false;
            });
            for (const item of vaultItems) {
                itemsRemoved = true;
                map.items.push({type:ItemType.EmptyVaultTreasureBox, pos:item.pos});
                if (map === state.gameMap) state.feedback?.vaultGold(vec2.clone(item.pos), 0.2);
            }
        }
        if (itemsRemoved) {
            state.feedback?.notify('\x8c\x8dLate!\nVaults were cleared.', state.player, 3, 5.0);
            state.feedback?.sound('coinRattle', 1.0);
            state.feedback?.sound('clockChime', 0.5);
        } else if (state.level > 0) {
            state.feedback?.notify('\x8c\x8dLate!', state.player, 3, 5.0);
            state.feedback?.sound('clockChime', 1.0);
        }
    }
}

const deadDailyNotification: string = 'Retry: Ctrl+R\nMenu: Esc/Slash';
const deadNotification: string = 'New Game: Ctrl+R\nMenu: Esc/Slash';
export function showDeadNotification(state: SimulationState) {
    state.feedback?.notify(state.dailyRun ? deadDailyNotification : deadNotification, state.player.pos);
}

export function tryPlayerWait(state: SimulationState) {
    const player = state.player;

    // Can't move if you're dead.
    if (player.health <= 0) {
        showDeadNotification(state);
        return;
    }

    state.feedback?.beginAction();

    preTurn(state);

    state.gameMap.identifyAdjacentCells(player.pos);

    player.interactionTarget = null;
    player.preNoisy = false;

    ++state.numWaitMoves;

    advanceTime(state);

    state.feedback?.tutorial(state.player.pos);
}
