import { displayModal } from '../browser/modal';
import { achievementBadges } from '../presentation/achievements';
import { Achievements } from '../run/achievements';
import type { GameStats } from '../run/state';
export function displayScorePopup(stats: GameStats | null, achievements: Achievements) {
    let msg = scoreMessage(stats, achievements);
    displayModal(msg);
}

export function scoreMessage(stats: GameStats | null, achievements: Achievements): string {
    if (stats === null) {
        return 'No game played yet!';
    }

    const numGhostedLevels = stats.numGhostedLevels;
    const numSpottings = stats.numSpottings;
    const numInjuries = stats.numInjuries;
    const numKnockouts = stats.numKnockouts;
    const totalScore = stats.totalScore;
    const turns = stats.turns;
    const numCompletedLevels = stats.numCompletedLevels;
    const numLevels = stats.numLevels;
    const win = numCompletedLevels >= numLevels;
    const daily = stats.daily;

    const runText = daily !== null ?
        '\uD83D\uDCC5 Daily run for ' + daily :
        '\uD83C\uDFB2 Random game';
    const endText =
        stats.numLevels === 0 ? '' :
        win ? 'Completed mission in ' + turns + ' turns.' :
        '\uD83D\uDC80 Died on level ' + (numCompletedLevels + 1) + ' after ' + turns + ' turns.';
    let achievementsLine = '';
    if (win && daily === null) {
        let a:keyof Achievements;
        for(a in achievements) {
            if (!achievements[a].failed) {
                achievementsLine += achievementBadges[a];
            }
        }
        if (achievementsLine.length>0) {
            achievementsLine = 'Achievements: '+achievementsLine+'\n';
        }
    }

    const scoreMessage = `\uD83C\uDFDB\uFE0F LLLOOOT! \uD83C\uDFDB\uFE0F\n${runText}\n${endText}\n`+
        `Completed:   ${numCompletedLevels} of ${numLevels}\n` +
        `Ghosted:     ${numGhostedLevels}\n`+
        `Spottings:   ${numSpottings}\n`+
        `Knockouts:   ${numKnockouts}\n`+
        `Injuries:    ${numInjuries}\n`+
        `Total score: ${totalScore}\n`+
        `${achievementsLine}`;

    return scoreMessage;
}

export function scoreToClipboard(stats:GameStats | null, achievements:Achievements) {
    const message = scoreMessage(stats, achievements);
    if (!navigator.clipboard) { displayModal(message); return; }
    navigator.clipboard.writeText(message).catch(() => displayModal(message));
}
