export class Rect extends Array<number> {
    constructor(x:number=0, y:number=0, w:number=0, h:number=0) {
        super(x,y,w,h);
    }
    collide(x:number, y:number, w:number=0, h:number=0) {
        if (x + w < this[0])
            return false;
        if (y + h < this[1])
            return false;
        if (x >= this[0] + this[2])
            return false;
        if (y >= this[1] + this[3])
            return false;
        return true;
    }
}
