export class BooleanGrid {
    readonly sizeX: number;
    readonly sizeY: number;
    values: Uint8Array;

    constructor(sizeX: number, sizeY: number, initialValue: boolean) {
        if (!Number.isSafeInteger(sizeX) || !Number.isSafeInteger(sizeY) || sizeX < 0 || sizeY < 0) throw new RangeError('Invalid grid size');
        this.sizeX = sizeX;
        this.sizeY = sizeY;
        this.values = new Uint8Array(sizeX * sizeY);
        this.fill(initialValue);
    }

    fill(value: boolean) {
        this.values.fill(value ? 1 : 0);
    }

    contains(x: number, y: number): boolean { return Number.isInteger(x) && Number.isInteger(y) && x >= 0 && y >= 0 && x < this.sizeX && y < this.sizeY; }
    get(x: number, y: number): boolean {
        if (!this.contains(x,y)) return false;
        return this.values[this.sizeX * y + x] !== 0;
    }

    set(x: number, y: number, value: boolean) {
        if (!this.contains(x,y)) throw new RangeError('Grid write outside bounds');
        this.values[this.sizeX * y + x] = value ? 1 : 0;
    }
}

export class Int32Grid {
    readonly sizeX: number;
    readonly sizeY: number;
    values: Int32Array;

    constructor(sizeX: number, sizeY: number, initialValue: number) {
        if (!Number.isSafeInteger(sizeX) || !Number.isSafeInteger(sizeY) || sizeX < 0 || sizeY < 0) throw new RangeError('Invalid grid size');
        this.sizeX = sizeX;
        this.sizeY = sizeY;
        this.values = new Int32Array(sizeX * sizeY);
        this.fill(initialValue);
    }

    fill(value: number) {
        this.values.fill(value);
    }

    contains(x: number, y: number): boolean { return Number.isInteger(x) && Number.isInteger(y) && x >= 0 && y >= 0 && x < this.sizeX && y < this.sizeY; }
    get(x: number, y: number): number {
        if (!this.contains(x,y)) return Infinity;
        return this.values[this.sizeX * y + x];
    }

    set(x: number, y: number, value: number) {
        if (!this.contains(x,y)) throw new RangeError('Grid write outside bounds');
        this.values[this.sizeX * y + x] = value;
    }
}

