import { basicFontTileset, entityTileSet31Color, terrainTileSet31Color } from './presentation/tile-definitions';
import { SpriteAtlas, spriteSheetCapacity } from './presentation/tile-types';
import type { SpriteSheet, SpriteSheets } from './presentation/tile-types';

export * from './presentation/tile-types';

export function getTerrainTileSet() {
    return terrainTileSet31Color;
}

export function getEntityTileSet() {
    return entityTileSet31Color;
}

export function getFontTileSet() {
    return basicFontTileset;
}

function loadableSheet(imageSrc: string, layers: number): SpriteSheet {
    return { imageSrc, image: new Image(), layers };
}

// Sprite sheets are 256 × 256. Indexes run left to right, then top to bottom.
// Keep layers at the highest occupied or referenced index plus one so blank space costs no GPU memory.
export const spriteSheets: SpriteSheets = {
    [SpriteAtlas.Font]: loadableSheet(require('url:./font.png'), spriteSheetCapacity),
    [SpriteAtlas.Surfaces]: loadableSheet(require('url:./sprites/surfaces.png'), 37),
    [SpriteAtlas.Architecture]: loadableSheet(require('url:./sprites/architecture.png'), 120),
    [SpriteAtlas.Items]: loadableSheet(require('url:./sprites/items.png'), 34),
    [SpriteAtlas.Characters]: loadableSheet(require('url:./sprites/characters.png'), 12),
    [SpriteAtlas.Effects]: loadableSheet(require('url:./sprites/effects.png'), 44),
    [SpriteAtlas.Interface]: loadableSheet(require('url:./sprites/interface.png'), 35),
};
