import type { vec2 } from '../my-matrix';
import { TerrainType } from './tiles';

export type Cell = {
    type: TerrainType;
    moveCost: number;
    blocksPlayerMove: boolean;
    blocksPlayerSight: boolean;
    blocksSight: boolean;
    blocksSound: boolean;
    hidesPlayer: boolean;
    isWindow: boolean;
    lit: number;
    litSrc: Set<number>; //Array<number>; //TODO: this should be a set pointing to the item/guard
    seen: boolean;
    identified: boolean;
}

export class CellGrid {
    readonly sizeX: number;
    readonly sizeY: number;
    values: Array<Cell>;

    constructor(sizeX: number, sizeY: number) {
        if (!Number.isInteger(sizeX) || !Number.isInteger(sizeY) || sizeX < 0 || sizeY < 0) throw new RangeError('Cell grid dimensions must be nonnegative integers');
        this.sizeX = sizeX;
        this.sizeY = sizeY;
        const size = sizeX * sizeY;
        this.values = new Array<Cell>(size);
        for (let i = 0; i < size; ++i) {
            this.values[i] = this.emptyCell();
        };
    }

    contains(x: number, y: number): boolean { return Number.isInteger(x) && Number.isInteger(y) && x >= 0 && y >= 0 && x < this.sizeX && y < this.sizeY; }

    checked(x: number, y: number): Cell {
        if (!this.contains(x,y)) throw new RangeError('Cell outside map');
        return this.at(x,y);
    }

    at(x: number, y: number): Cell {
        if (!this.contains(x,y)) {
            return this.emptyCell();
        }
        const i = this.sizeX * y + x;
        return this.values[i];
    }

    atVec(pos:vec2): Cell {
        return this.at(pos[0], pos[1]);
    }

    index(x: number, y:number): number {
        return this.sizeX * y + x;
    }

    indexVec(pos:vec2): number {
        return this.index(pos[0], pos[1]);
    }


    emptyCell(): Cell {
        return {
            type: TerrainType.GroundGrass,
            moveCost: Infinity,
            blocksPlayerMove: false,
            blocksPlayerSight: false,
            blocksSight: false,
            blocksSound: false,
            hidesPlayer: false,
            isWindow: false,
            lit: 0,
            litSrc: new Set<number>(),
            seen: false,
            identified: false,
        }
    }
}
