// Profile/run DTOs contain plain records, arrays and scalar values.
export function cloneData<T>(value: T): T {
    if (Array.isArray(value)) return value.map(cloneData) as T;
    if (value && typeof value === 'object') {
        const result = {...value};
        for (const key of Object.keys(result) as Array<keyof T>) result[key] = cloneData(result[key]);
        return result;
    }
    return value;
}
