import { TerrainType } from './tiles';
export function windowAllowsDirection(type: TerrainType, dx: number, dy: number, from?: TerrainType): boolean {
    // A roof meets the outer sill at window height, making it reachable from either side.
    const eitherWay = from === TerrainType.GroundRoof;
    switch (type) {
        case TerrainType.OneWayWindowE: return dx > 0 || (eitherWay && dx < 0);
        case TerrainType.OneWayWindowW: return dx < 0 || (eitherWay && dx > 0);
        case TerrainType.OneWayWindowN: return dy > 0 || (eitherWay && dy < 0);
        case TerrainType.OneWayWindowS: return dy < 0 || (eitherWay && dy > 0);
        default: return true;
    }
}
