export type Direction = 'left' | 'right' | 'down' | 'up';

export type PlayerCommand =
    | { type: 'step' | 'leap'; direction: Direction }
    | { type: 'wait' };

export const directionOffsets: Record<Direction, readonly [number, number]> = {
    left: [-1, 0],
    right: [1, 0],
    down: [0, -1],
    up: [0, 1],
};

export enum StepType {
    Normal,
    AttemptedLeap,
    AttemptedLeapBounceBack,
}

export function directionArrowCharacter(dx: number, dy: number): string {
    if (dx > 0) {
        return '\x1a';
    } else if (dx < 0) {
        return '\x1b';
    } else if (dy > 0) {
        return '\x18';
    } else if (dy < 0) {
        return '\x19';
    }
    return '\x07';
}
