import type { TileInfo } from '../tilesets';
import { activateController,Controller } from './controller';
import { Rect } from './rect';
export type TouchTargets = {
    [id:string]:
    {
        id:number,
        rect:Rect,
        tileInfo:TileInfo|null,
        touchXY:[number, number],
        mouseable:boolean,
    }
};

export class TouchController extends Controller {
    canvas: HTMLCanvasElement;
    lastMotion: {id:number, active: boolean, x0:number, y0:number, x:number, y:number};
    coreTouchTargets: TouchTargets;
    touchTargets: TouchTargets;
    mouseActive: boolean = false;
    targetOnTouchDown: string|null = null;
    constructor(canvas: HTMLCanvasElement) {
        super();
        this.canvas = canvas;
        // Register touch event handlers
        this.listen(canvas, 'touchstart', (ev: TouchEvent)=>this.process_touchstart(ev), true);
        this.listen(canvas, 'touchmove', (ev: TouchEvent)=>this.process_touchmove(ev), true);
        this.listen(canvas, 'touchcancel', (ev: TouchEvent)=>{ this.clearPressedAll(); ev.preventDefault(); }, true);
        this.listen(canvas, 'touchend', (ev: TouchEvent)=>this.process_touchend(ev), true);
        this.listen(canvas, 'mousedown', (ev: MouseEvent)=>this.process_mousedown(ev), true);
        this.listen(window, 'mouseup', (ev: MouseEvent)=>this.process_mouseup(ev), true);
        this.listen(canvas, 'mousemove', (ev: MouseEvent)=>this.process_mousemove(ev), true);
        this.listen(window, 'resize', () => this.clearPressedAll());
        this.lastMotion = {id:-1,active:false,x0:0,y0:0,x:0,y:0};

        this.coreTouchTargets = {
            'up':           {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'down':         {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'left':         {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'right':        {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'wait':         {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'jump':         {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'menuAccept':   {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:false},
            'pan':          {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
            'zoomIn':       {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
            'zoomOut':      {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
            'forceRestart': {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
            'menuToggle':   {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
            'fullscreen':   {id:-1, rect:new Rect(), touchXY:[0,0], tileInfo:null, mouseable:true},
        };
        this.touchTargets = this.coreTouchTargets;
    }
    clearPressedAll() {
        super.clearPressedAll();
        for (const target of Object.values(this.touchTargets ?? {})) target.id = -1;
        if (this.lastMotion) this.clearMotion();
    }
    clearMotion() {
        this.lastMotion.active = false;
        this.lastMotion.id = -1;
        this.lastMotion.x0 = 0;
        this.lastMotion.y0 = 0;
        this.lastMotion.x = 0;
        this.lastMotion.y = 0;
        this.targetOnTouchDown = null;
    }
    updateCoreTouchTarget(id:string, rect:Rect, tileInfo:TileInfo) {
        const b0 = this.coreTouchTargets[id];
        b0.rect = rect;
        b0.tileInfo = tileInfo;
        const rectClient = this.canvas.getBoundingClientRect();
        const x = b0.touchXY[0] - rectClient.left;
        const y = rectClient.bottom - (b0.touchXY[1] + 1);
        if (!b0.rect.collide(x, y)) {
            if(this.controlStates[id] && b0.id!=-1) {
                this.setPressed(id, false, false);
                b0.id = -1;
            }
        }
    }
    activateTouchTargets(extraTouchTargets: TouchTargets|undefined) {
        let touchTargets: TouchTargets;
        if(extraTouchTargets === undefined) {
            touchTargets = this.coreTouchTargets;
        } else {
            touchTargets = {...this.coreTouchTargets, ...extraTouchTargets};
        }

        // Clear pressed status on any touch targets going away

        for (const [bname, _b] of Object.entries(this.touchTargets)) {
            if (!(bname in touchTargets)) {
                this.controlStates[bname] = false;
            }
        }

        this.touchTargets = touchTargets;
    }
    //touchstart handler
    process_mousedown(ev: MouseEvent) {
        activateController(this);
        const rectClient = this.canvas.getBoundingClientRect();
        const x = ev.clientX - rectClient.left;
        const y = rectClient.bottom - (ev.clientY + 1);
        this.mouseActive = true;
        this.lastMotion.id=-2;
        this.lastMotion.active = false;
        this.lastMotion.x0 = x;
        this.lastMotion.y0 = y;
        this.lastMotion.x = x;
        this.lastMotion.y = y;
        this.targetOnTouchDown = null;
        for (const [bname, b] of Object.entries(this.touchTargets)) {
            if(!b.mouseable) continue;
            const touching = b.rect.collide(x, y);
            if(touching) {
                b.touchXY = [ev.clientX, ev.clientY];
                b.id = -2;
                this.setPressed(bname, true);
                this.targetOnTouchDown = bname;
            }
        }
        ev.preventDefault();
    }
    // touchmove handler
    process_mousemove(ev:MouseEvent) {
        activateController(this);
        this.mouseActive = true;
        const rectClient = this.canvas.getBoundingClientRect();
        const x = ev.clientX - rectClient.left;
        const y = rectClient.bottom - (ev.clientY + 1);
        if(this.lastMotion.id == -2) {
            this.lastMotion.active = true;
            this.lastMotion.x = x;
            this.lastMotion.y = y;
        }
        for (const [bname, b] of Object.entries(this.touchTargets)) {
            if(!b.mouseable) continue;
            if(b.id === -2) { //already pressing this button down
                const touching = b.rect.collide(x, y);
                if(touching) {
                    b.touchXY = [ev.clientX, ev.clientY]; //update touch info but don't trigger another activation
                } else {
                    this.setPressed(bname, false, false);
                    b.id = -1;
                }
            }
        }
        ev.preventDefault();
    }
    // mouseup handler
    process_mouseup(ev:MouseEvent) {
        for (const [bname, b] of Object.entries(this.touchTargets)) {
            if(!b.mouseable) continue;
            if(this.controlStates[bname]) {
                b.id = -1;
                this.setPressed(bname, false, true);
                this.controlTimes[bname] = 0;
            }
        }
        this.clearMotion();
        ev.preventDefault();
    }
    //touchstart handler
    process_touchstart(ev: TouchEvent) {
        activateController(this);
        this.mouseActive = false;
        this.targetOnTouchDown = null;
        const rectClient = this.canvas.getBoundingClientRect();
        for(let t of ev.changedTouches) {
            const x = t.clientX - rectClient.left;
            const y = rectClient.bottom - (t.clientY + 1);
            this.lastMotion.id = t.identifier;
            this.lastMotion.active = false;
            this.lastMotion.x0 = x;
            this.lastMotion.y0 = y;
            this.lastMotion.x = x;
            this.lastMotion.y = y;
            for (const [bname, b] of Object.entries(this.touchTargets)) {
                const touching = b.rect.collide(x, y);
                if(touching) {
                    b.touchXY = [t.clientX, t.clientY];
                    b.id = t.identifier;
                    this.targetOnTouchDown = bname;
                    this.setPressed(bname, true);
                }
            }
        }
        ev.preventDefault();
    }
    // touchmove handler
    process_touchmove(ev:TouchEvent) {
        this.mouseActive = false;
        const rectClient = this.canvas.getBoundingClientRect();
        for(let t of ev.changedTouches) {
            const x = t.clientX - rectClient.left;
            const y = rectClient.bottom - (t.clientY + 1);
            if(this.lastMotion.id == t.identifier) {
                this.lastMotion.active = true;
                this.lastMotion.x = x;
                this.lastMotion.y = y;
            }
            for (const [bname, b] of Object.entries(this.touchTargets)) {
                if(b.id == t.identifier) {
                    const touching = b.rect.collide(x, y);
                    if(touching) {
                        b.touchXY = [t.clientX, t.clientY];
                    } else {
                        b.id = -1;
                        this.setPressed(bname, false, false);
                    }
                }
            }
        }
        ev.preventDefault();
    }
    // touchend handler
    process_touchend(ev:TouchEvent) {
        this.mouseActive = false;
        for(let t of ev.changedTouches) {
            for (const [bname, b] of Object.entries(this.touchTargets)) {
                if(b.id==t.identifier) {
                    b.id = -1;
                    this.setPressed(bname, false, true);
                    this.controlTimes[bname] = 0;
                }
            }
            if(this.lastMotion.id == t.identifier) {
                this.clearMotion();
            }
        }
        ev.preventDefault();
    }
}
