import { vec2 } from '../my-matrix';
import { isDoorItemType,isWindowTerrainType } from '../world/game-map';
import type { GameMap } from '../world/game-map';
import { exposedFloorAt,type MansionFloor } from '../world/mansion';
import { blocksOrdinaryStep,canLeapOntoItemType,isClimbableItem,isGateTerrainType,isHingedDoorTerrainType,isLockedDoorItemType,isWallTerrainType,TerrainType } from '../world/tiles';
import { windowAllowsDirection } from '../world/traversal';
import type { SimulationState } from './state';

type MovementState = Pick<SimulationState, 'gameMap' | 'player' | 'finishedLevel'>;
export function canStepToPos(state: MovementState, pos: vec2, ignoreGuards = false): boolean {

    // Cannot step off map if level is unfinished

    if (pos[0] < 0 || pos[0] >= state.gameMap.cells.sizeX ||
        pos[1] < 0 || pos[1] >= state.gameMap.cells.sizeY) {
        if (!state.finishedLevel || !state.gameMap.canEscapeFrom(state.player.pos)) {
            return false;
        }
    }

    // Cannot step onto walls or windows

    const cellNew = state.gameMap.cells.atVec(pos);
    if (cellNew.blocksPlayerMove) {
        return false;
    }

    if (isWindowTerrainType(cellNew.type)) {
        return false;
    }

    // Cannot step onto torches, portcullises, treasure boxes or treasure

    if (state.gameMap.items.some(item => item.pos.equals(pos) && blocksOrdinaryStep(item.type))) {
        return false;
    }

    // Cannot step onto guards

    if (!ignoreGuards && state.gameMap.guards.find((guard)=>guard.pos.equals(pos))) {
        return false;
    }

    return true;
}

export function canLeapToPos(state: MovementState, pos: vec2, ignoreGuards = false): boolean {
    // Cannot leap off map if level is unfinished

    if (pos[0] < 0 || pos[0] >= state.gameMap.cells.sizeX ||
        pos[1] < 0 || pos[1] >= state.gameMap.cells.sizeY) {
        if (!state.finishedLevel || !state.gameMap.canEscapeFrom(state.player.pos)) {
            return false;
        }
    }

    // Cannot leap onto a wall, window, portcullis, or door

    const cellNew = state.gameMap.cells.atVec(pos);
    if (cellNew.blocksPlayerMove) {
        return false;
    }

    if (isWindowTerrainType(cellNew.type)) {
        return false;
    }

    if (isGateTerrainType(cellNew.type)) {
        return false;
    }

    if (isHingedDoorTerrainType(cellNew.type) &&
        state.gameMap.items.some((item)=>item.pos.equals(pos) && isDoorItemType(item.type))) {
        return false;
    }

    // Cannot leap onto a blocking item

    if (state.gameMap.items.some((item)=>item.pos.equals(pos) && !canLeapOntoItemType(item.type))) {
        return false;
    }

    // Cannot leap onto a stationary guard

    if (!ignoreGuards && state.gameMap.guards.some((guard)=>guard.pos.equals(pos) && !guard.allowsMoveOntoFrom(state.player.pos))) {
        return false;
    }

    return true;
}

type DropLanding = {floor: MansionFloor; pos: vec2; elevated: boolean; stories: number};

export function resolveLeapDrop(state: MovementState & Pick<SimulationState, 'mansion'>,
    dx: number, dy: number): {landing?: DropLanding} | undefined {
    const {mansion, gameMap: map, player} = state;
    if (!mansion) return undefined;
    const {pos: from, elevated} = player;
    const fromType = map.cells.atVec(from).type;
    if (!elevated && fromType === TerrainType.GroundWater) return undefined;

    const mid = vec2.fromValues(from[0] + dx, from[1] + dy);
    const middle = map.cells.atVec(mid);
    const end = vec2.fromValues(mid[0] + dx, mid[1] + dy);
    const unsupported = (pos: vec2) => map.isOpening(pos) && (!elevated || !map.hasHighSurface(pos));
    const throughWindow = isWindowTerrainType(middle.type) && !middle.blocksPlayerMove &&
        windowAllowsDirection(middle.type, dx, dy, fromType);
    const fromRoof = fromType === TerrainType.GroundRoof;
    const offEdge = fromRoof && unsupported(mid);
    const overRoof = fromRoof && middle.type === TerrainType.GroundRoof && canStepToPos(state, mid);
    const outside = offEdge ? mid : end;
    if (!(offEdge || overRoof || throughWindow) || !unsupported(outside)) return undefined;

    const source = mansion.floors.find(floor => floor.map === map);
    if (!source) return undefined;
    const floor = exposedFloorAt(mansion, source.id, outside, true);
    if (!floor) return {};

    // Momentum can carry the thief off a blocked landing by one tile.
    for (const [x, y] of [[0, 0], [dx, dy], [-dy, dx], [dy, -dx]]) {
        const pos = vec2.fromValues(outside[0] + x, outside[1] + y);
        const target = floor.map;
        if (!map.isOpening(pos) || exposedFloorAt(mansion, source.id, pos, true) !== floor) continue;
        const high = target.hasHighSurface(pos);
        if (!high && (target.isLadderSpace(pos) || !canFallOnto(target, pos))) continue;
        const stories = source.id - floor.id + (Number(elevated) - Number(high)) / 2;
        return {landing: {floor, pos, elevated: high, stories}};
    }
    return {};
}

function canFallOnto(map: GameMap, pos: vec2): boolean {
    const cell = map.cells.atVec(pos);
    return !cell.blocksPlayerMove && !isWindowTerrainType(cell.type) && !isGateTerrainType(cell.type) &&
        !map.items.some(item => item.pos.equals(pos) && (isDoorItemType(item.type) || !canLeapOntoItemType(item.type))) &&
        !map.guards.some(guard => guard.pos.equals(pos));
}

export type ElevatedMove = { to: vec2; elevated: boolean; leap: boolean };

export function resolveElevatedMove(state: MovementState, from: vec2, elevated: boolean, dx: number, dy: number,
    leap: boolean, ignoreGuards = false): ElevatedMove | undefined {
    const {gameMap, player} = state;
    const next = vec2.fromValues(from[0] + dx, from[1] + dy);
    if (!elevated) {
        if (leap && gameMap.hasHighSurface(next) && gameMap.cells.atVec(from).type !== TerrainType.GroundWater &&
            gameMap.items.some(item => item.pos.equals(next) && isClimbableItem(item.type))) {
            return {to: next, elevated: true, leap: true};
        }
        return undefined;
    }

    function landing(to: vec2, jumped: boolean): ElevatedMove | undefined {
        if (!gameMap.cells.contains(to[0], to[1])) return undefined;
        if (gameMap.hasHighSurface(to)) return {to, elevated: true, leap: jumped};
        if (!(jumped ? canLeapToPos(state, to, ignoreGuards) : canStepToPos(state, to, ignoreGuards)) ||
            (!ignoreGuards && gameMap.guards.some(guard => guard.pos.equals(to))) ||
            (!player.hasVaultKey && gameMap.items.some(item => item.pos.equals(to) && isLockedDoorItemType(item.type)))) return undefined;
        return {to, elevated: false, leap: jumped};
    }

    const middle = gameMap.cells.atVec(next).type;
    if (leap && !isWallTerrainType(middle) && !isHingedDoorTerrainType(middle) &&
        windowAllowsDirection(middle, dx, dy, gameMap.cells.atVec(from).type)) {
        const end = vec2.fromValues(next[0] + dx, next[1] + dy);
        const move = landing(end, true);
        if (move) return move;
    }
    return landing(next, false);
}
