import { vec2 } from '../my-matrix';
import type { EventValue,GameEvent } from '../simulation/events';
import type { TurnFeedback } from '../simulation/feedback';
import type { WorldIdentity } from '../world/identity';

export function presentEvents(events: readonly GameEvent[], feedback: TurnFeedback, identities: WorldIdentity) {
    function decode(value: EventValue): unknown {
        if (Array.isArray(value)) return value.map(decode);
        if (value && typeof value === 'object') {
            const data = value as { readonly [key: string]: EventValue };
            if (Array.isArray(data.vector)) return vec2.fromValues(Number(data.vector[0]), Number(data.vector[1]));
            if (typeof data.actorId === 'string') return identities.resolve(data.actorId);
            return Object.fromEntries(Object.entries(data).map(([key, item]) => [key, decode(item)]));
        }
        return value === null ? undefined : value;
    }
    for (const event of events) {
        if (event.type !== 'presentation') continue;
        try {
            const consume = feedback[event.kind] as (...args: unknown[]) => void;
            consume(...event.args.map(decode));
        } catch {
            // Each effect has independent failure isolation. Gameplay has already completed.
        }
    }
}
