import { createGameSession } from '../application/session';
import {
    floorIds, itemPalette, levelThemes, maxFloorSize, maxGuardsPerFloor, maxLevelFileSize, maxPatrolLength,
    minFloorSize, newLevelFile, newLevelFloor, readLevel, readLevelFile, sameTile, terrainAt, terrainPalette,
    type ItemCode, type LevelFile, type LevelTheme, type TerrainCode, type TilePosition,
} from '../application/levels/format';
import { Howler } from '../audio';
import { FloorId, floorName } from '../world/mansion';
import { eraseObjects, isEdge, LevelDraft, paintTerrain, removeStair, resizeFloor } from './level-draft';
import { drawLevelPreview, pointerTile } from './level-preview';
import { attachSession, resetMapPresentation } from './session';
import { GameMode, type State } from './state';

const tools = {
    terrain: 'Paint terrain',
    item: 'Place item',
    start: 'Player start',
    exit: 'Exit',
    stairs: 'Ladder',
    platform: 'Ceiling platform',
    guard: 'Place guard',
    patrol: 'Edit patrol',
    erase: 'Erase object',
};
type Choice = keyof typeof tools;
type StairLink = {from: FloorId; to: FloorId; at: TilePosition};

export function mountLevelEditor(state: State, canvas: HTMLCanvasElement, signal: AbortSignal) {
    const element = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
    const dialog = element<HTMLDialogElement>('levelEditor');
    const grid = element<HTMLCanvasElement>('editorGrid');
    const file = element<HTMLInputElement>('editorFile');
    const title = element<HTMLInputElement>('editorTitle');
    const theme = element<HTMLSelectElement>('editorTheme');
    const floors = element<HTMLSelectElement>('editorFloor');
    const width = element<HTMLInputElement>('editorWidth');
    const height = element<HTMLInputElement>('editorHeight');
    const zoom = element<HTMLSelectElement>('editorZoom');
    const tool = element<HTMLSelectElement>('editorTool');
    const terrain = element<HTMLSelectElement>('editorTerrain');
    const item = element<HTMLSelectElement>('editorItem');
    const destination = element<HTMLSelectElement>('editorDestination');
    const guards = element<HTMLSelectElement>('editorGuard');
    const torch = element<HTMLInputElement>('editorTorch');
    const purse = element<HTMLInputElement>('editorPurse');
    const playtestBar = element('playtestBar');
    const notice = element('editorStatus');
    const removeFloorButton = element<HTMLButtonElement>('editorRemoveFloor');
    const removeGuardButton = element<HTMLButtonElement>('editorRemoveGuard');
    const undoButton = element<HTMLButtonElement>('editorUndo');
    const redoButton = element<HTMLButtonElement>('editorRedo');
    const draft = new LevelDraft();
    const mainSession = state.session;
    let floorId = FloorId.First;
    let cursor: TilePosition = [0, 0];
    let guardIndex = 0;
    let linking: StairLink | undefined;
    let stroke: {id: number; previous: TilePosition} | undefined;
    let loadToPlay = false;
    let fileRequest = 0;

    const floor = () => draft.level.floors.find(floor => floor.id === floorId)!;
    const choice = () => tool.value as Choice;
    const isOpen = () => dialog.open;

    function options(select: HTMLSelectElement, values: readonly (readonly [string | number, string])[], active?: string | number) {
        select.replaceChildren(...values.map(([value, label]) => {
            const option = document.createElement('option');
            option.value = String(value);
            option.text = label;
            return option;
        }));
        if (active !== undefined && values.some(([key]) => String(key) === String(active))) select.value = String(active);
    }

    options(theme, Object.entries(levelThemes).map(([key, value]) => [key, value.label]));
    options(tool, Object.entries(tools));
    options(terrain, Object.entries(terrainPalette).map(([code, value]) => [code, value.label]), 'w');
    options(item, Object.entries(itemPalette).map(([code, value]) => [code, value.label]));
    for (const input of [width, height]) {
        input.min = String(minFloorSize);
        input.max = String(maxFloorSize);
    }

    function status(message = '', error = false) {
        notice.textContent = message;
        notice.dataset.error = String(error);
    }

    function report(error: unknown) {
        status(error instanceof Error ? error.message : 'The level could not be opened.', true);
    }

    function clearGameInput() {
        state.keyboardController.clearPressedAll();
        state.touchController.clearPressedAll();
        for (const controller of Object.values(state.gamepadManager.gamepads)) controller.clearPressedAll();
        state.keyRepeatActive = undefined;
    }

    function draw() {
        if (!isOpen()) return;
        drawLevelPreview(grid, draft.level, floor(), cursor, guardIndex);
        grid.dataset.fit = String(zoom.value === 'fit');
        grid.style.width = zoom.value === '150' ? grid.width * 1.5 + 'px' : '';
        const {label} = terrainPalette[terrainAt(floor(), cursor)];
        element('editorCoordinates').textContent = `${cursor.join(', ')} · ${label}`;
    }

    function refresh() {
        if (!draft.level.floors.some(floor => floor.id === floorId)) floorId = FloorId.First;
        const active = floor();
        title.value = draft.level.title;
        theme.value = draft.level.theme;
        width.value = String(active.terrain[0].length);
        height.value = String(active.terrain.length);
        cursor = [Math.min(cursor[0], Number(width.value) - 1), Math.min(cursor[1], Number(height.value) - 1)];
        options(floors, floorIds.map(id => [id, draft.level.floors.some(floor => floor.id === id)
            ? floorName(id) : '+ Add ' + floorName(id).toLowerCase()]), floorId);
        floors.disabled = !!linking;
        removeFloorButton.disabled = floorId === FloorId.First || !!linking;
        options(destination, draft.level.floors.filter(floor => floor.id !== floorId).map(floor => [floor.id, floorName(floor.id)]),
            destination.value);
        destination.disabled = !!linking || destination.options.length === 0;
        guardIndex = Math.max(0, Math.min(guardIndex, active.guards.length - 1));
        options(guards, active.guards.map((_, index) => [index, 'Guard ' + (index + 1)]), guardIndex);
        const guard = active.guards[guardIndex];
        for (const input of [guards, torch, purse, removeGuardButton]) input.disabled = !guard;
        torch.checked = guard?.torch ?? false;
        purse.checked = guard?.purse ?? false;
        element('editorGuardRow').hidden = !['guard', 'patrol'].includes(choice());
        element('editorTerrainRow').hidden = choice() !== 'terrain';
        element('editorItemRow').hidden = choice() !== 'item';
        element('editorStairsRow').hidden = choice() !== 'stairs' || !!linking;
        undoButton.disabled = !draft.canUndo;
        redoButton.disabled = !draft.canRedo;
        const guide: Partial<Record<Choice, string>> = {
            terrain: 'Click or drag across the grid to paint.',
            start: 'Choose where the player starts on the first floor.',
            exit: 'Place an exit on the edge of the first floor.',
            stairs: linking ? `Place the return ladder on ${floorName(linking.to).toLowerCase()}. Switch tools to cancel.` :
                destination.disabled ? 'Add another floor to connect a ladder.' : 'Choose a destination, then place one ladder tile on each floor. Leave a clear tile beside each one.',
            platform: 'Place an elevated surface. Connect it to tall furniture so the player can climb up.',
            guard: 'Place a guard on an open tile. A guard with no waypoints stands still.',
            patrol: 'Add neighboring waypoints. Click an existing waypoint to shorten the route. The guard retraces the route.',
            erase: 'Erase an item, platform, guard, exit, or both ends of a ladder.',
        };
        element('editorGuide').textContent = guide[choice()] ?? 'Choose an item and click a tile to place it.';
        draw();
    }

    function change(edit: (level: LevelFile) => void) {
        draft.edit(edit);
        status();
        refresh();
    }

    function editTile(at: TilePosition) {
        const active = floor();
        const currentFloor = (level: LevelFile) => level.floors.find(floor => floor.id === floorId)!;
        switch (choice()) {
            case 'terrain':
                change(level => paintTerrain(currentFloor(level), at, terrain.value as TerrainCode));
                break;
            case 'item':
                change(level => {
                    const target = currentFloor(level);
                    target.items = target.items.filter(item => !sameTile(item.at, at));
                    target.items.push({type: item.value as ItemCode, at});
                });
                break;
            case 'erase':
                change(level => eraseObjects(level, currentFloor(level), at));
                break;
            case 'start':
                if (floorId !== FloorId.First) { status('Place the player start on the first floor.', true); return; }
                change(level => { level.start = at; });
                break;
            case 'exit':
                if (floorId !== FloorId.First || !isEdge(active, at)) { status('Choose an edge tile on the first floor.', true); return; }
                change(level => {
                    if (terrainAt(active, at) === '#') paintTerrain(currentFloor(level), at, '.');
                    if (!level.exits.some(exit => sameTile(exit, at))) level.exits.push(at);
                });
                break;
            case 'platform':
                change(level => {
                    const target = currentFloor(level);
                    const tiles = target.platforms ??= [];
                    if (!tiles.some(tile => sameTile(tile, at))) tiles.push(at);
                });
                break;
            case 'stairs':
                if (active.stairs.some(stair => sameTile(stair.at, at) && stair.to !== (linking?.from ?? Number(destination.value)))) {
                    status('Choose a separate tile for this ladder.', true);
                    return;
                }
                if (linking) {
                    const link = linking;
                    linking = undefined;
                    change(level => {
                        removeStair(level, link.from, link.to);
                        level.floors.find(floor => floor.id === link.from)!.stairs.push({at: link.at, to: link.to});
                        currentFloor(level).stairs.push({at, to: link.from});
                    });
                    status('Ladders connected.');
                } else if (!destination.disabled) {
                    linking = {from: floorId, to: Number(destination.value), at};
                    floorId = linking.to;
                    refresh();
                }
                break;
            case 'guard':
                if (active.guards.length >= maxGuardsPerFloor) { status('This floor already has the maximum number of guards.', true); return; }
                if (active.guards.some(guard => sameTile(guard.patrol[0], at))) { status('Choose a different guard start.', true); return; }
                tool.value = 'patrol';
                guardIndex = active.guards.length;
                change(level => currentFloor(level).guards.push({patrol: [at], torch: false, purse: false}));
                break;
            case 'patrol': {
                const guard = active.guards[guardIndex];
                if (!guard) { status('Place a guard before editing a patrol.', true); return; }
                const previous = guard.patrol.findIndex(point => sameTile(point, at));
                const last = guard.patrol[guard.patrol.length - 1];
                if (previous < 0 && (Math.max(Math.abs(last[0] - at[0]), Math.abs(last[1] - at[1])) > 1 ||
                    guard.patrol.length >= maxPatrolLength)) {
                    status('Choose a neighboring tile or click a waypoint to shorten the patrol.', true);
                    return;
                }
                change(level => {
                    const patrol = currentFloor(level).guards[guardIndex].patrol;
                    if (previous < 0) patrol.push(at);
                    else patrol.length = previous + 1;
                });
                break;
            }
        }
    }

    function closeEditor() {
        fileRequest++;
        linking = undefined;
        stroke = undefined;
        dialog.close();
        clearGameInput();
        state.tLast = undefined;
        canvas.focus();
    }

    function openEditor(load = false) {
        clearGameInput();
        if (!isOpen()) {
            state.timers.clear();
            state.activeSoundPool.cancelPending?.();
            state.ambientSoundPool.cancelPending?.();
            Howler.stop();
            dialog.showModal();
        }
        refresh();
        if (load) openFile(true);
    }

    function openFile(play: boolean) {
        fileRequest++;
        loadToPlay = play;
        file.value = '';
        file.click();
    }

    function play() {
        try {
            const next = createGameSession({profile: state.profile, customLevel: draft.level});
            closeEditor();
            state.game = next.read();
            state.session = attachSession(next, state);
            resetMapPresentation(state);
            element('playtestName').textContent = draft.level.title;
            playtestBar.hidden = false;
            state.session.startOrResume();
        } catch (error) {
            report(error);
        }
    }

    function returnToEditor() {
        const finished = state.game.phase === 'mansion-complete';
        const turns = state.game.turns;
        state.session = mainSession;
        state.game = mainSession.read();
        state.gameMode = GameMode.HomeScreen;
        resetMapPresentation(state);
        state.hintMessage = '';
        playtestBar.hidden = true;
        openEditor();
        status(finished ? `Playtest completed in ${turns} turns.` : 'Returned to your draft.');
    }

    function history(undo: boolean) {
        linking = undefined;
        if (undo) draft.undo();
        else draft.redo();
        status();
        refresh();
    }

    function click(id: string, action: () => void) {
        element(id).addEventListener('click', action, {signal});
    }

    click('editorClose', closeEditor);
    click('editorNew', () => {
        floorId = FloorId.First;
        linking = undefined;
        draft.replace(newLevelFile());
        status('New level ready.');
        refresh();
    });
    click('editorSave', () => {
        try {
            const level = readLevel(draft.level);
            const url = URL.createObjectURL(new Blob([JSON.stringify(level, null, 2) + '\n'], {type: 'application/json'}));
            const link = document.createElement('a');
            link.href = url;
            link.download = (level.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'custom-level') + '.json';
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
            status('Level file saved.');
        } catch (error) { report(error); }
    });
    click('editorOpen', () => openFile(false));
    click('editorPlay', play);
    click('editorUndo', () => history(true));
    click('editorRedo', () => history(false));
    click('editorResize', () => {
        const w = width.valueAsNumber, h = height.valueAsNumber;
        if (![w, h].every(size => Number.isInteger(size) && size >= minFloorSize && size <= maxFloorSize)) {
            status(`Choose whole dimensions from ${minFloorSize} to ${maxFloorSize} tiles.`, true);
            return;
        }
        linking = undefined;
        change(level => { for (const story of level.floors) resizeFloor(level, story, w, h); });
    });
    click('editorRemoveFloor', () => {
        const removed = floorId;
        if (removed === FloorId.First) return;
        floorId = FloorId.First;
        change(level => {
            level.floors = level.floors.filter(floor => floor.id !== removed);
            for (const floor of level.floors) floor.stairs = floor.stairs.filter(stair => stair.to !== removed);
        });
    });
    click('editorRemoveGuard', () => change(level => level.floors.find(floor => floor.id === floorId)!.guards.splice(guardIndex, 1)));
    click('playtestBack', returnToEditor);
    click('playtestRetry', () => {
        clearGameInput();
        state.session.restartCurrentRun();
        canvas.focus();
    });

    title.addEventListener('change', () => change(level => { level.title = title.value; }), {signal});
    theme.addEventListener('change', () => change(level => { level.theme = theme.value as LevelTheme; }), {signal});
    floors.addEventListener('change', () => {
        floorId = Number(floors.value);
        cursor = [0, 0];
        if (!draft.level.floors.some(floor => floor.id === floorId)) {
            change(level => {
                const grid = level.floors[0].terrain;
                level.floors.push(newLevelFloor(floorId, grid[0].length, grid.length));
                level.floors.sort((a, b) => a.id - b.id);
            });
            status('Use the Ladder tool to connect the new floor.');
        } else refresh();
    }, {signal});
    zoom.addEventListener('change', draw, {signal});
    tool.addEventListener('change', () => { linking = undefined; status(); refresh(); }, {signal});
    guards.addEventListener('change', () => { guardIndex = Number(guards.value); refresh(); }, {signal});
    for (const [input, property] of [[torch, 'torch'], [purse, 'purse']] as const) {
        input.addEventListener('change', () => change(level => {
            level.floors.find(floor => floor.id === floorId)!.guards[guardIndex][property] = input.checked;
        }), {signal});
    }
    file.addEventListener('change', async () => {
        const loaded = file.files?.[0];
        if (!loaded) return;
        const request = ++fileRequest;
        const previous = draft.level;
        const autoPlay = loadToPlay;
        try {
            if (loaded.size > maxLevelFileSize) throw new Error('This level file is too large.');
            const level = readLevelFile(await loaded.text());
            if (request !== fileRequest || previous !== draft.level || !isOpen() || signal.aborted) return;
            floorId = FloorId.First;
            linking = undefined;
            cursor = [0, 0];
            draft.replace(level);
            refresh();
            status('Level file opened.');
            if (autoPlay) play();
        } catch (error) {
            if (request === fileRequest && isOpen() && !signal.aborted) report(error);
        }
    }, {signal});

    function inside([x, y]: TilePosition) {
        return x >= 0 && y >= 0 && x < floor().terrain[0].length && y < floor().terrain.length;
    }

    grid.addEventListener('pointerdown', event => {
        if (!event.isPrimary || event.button !== 0) return;
        const at = pointerTile(grid, event);
        if (!inside(at)) return;
        grid.focus({preventScroll: true});
        cursor = at;
        if (choice() === 'terrain') {
            draft.edit(() => {});
            paintTerrain(floor(), at, terrain.value as TerrainCode);
            stroke = {id: event.pointerId, previous: at};
            grid.setPointerCapture(event.pointerId);
            status();
            refresh();
        } else editTile(at);
    }, {signal});
    grid.addEventListener('pointermove', event => {
        if (stroke?.id !== event.pointerId) return;
        const end = pointerTile(grid, event);
        if (!inside(end) || sameTile(end, stroke.previous)) return;
        const [x, y] = stroke.previous;
        const dx = end[0] - x, dy = end[1] - y;
        const steps = Math.max(Math.abs(dx), Math.abs(dy));
        const active = floor();
        for (let step = 1; step <= steps; step++) {
            paintTerrain(active, [x + Math.round(dx * step / steps), y + Math.round(dy * step / steps)], terrain.value as TerrainCode);
        }
        cursor = stroke.previous = end;
        draw();
    }, {signal});
    grid.addEventListener('lostpointercapture', () => { stroke = undefined; }, {signal});
    grid.addEventListener('keydown', event => {
        let [x, y] = cursor;
        switch (event.key) {
            case 'ArrowLeft': x--; break;
            case 'ArrowRight': x++; break;
            case 'ArrowUp': y++; break;
            case 'ArrowDown': y--; break;
            case ' ':
            case 'Enter':
                event.preventDefault();
                editTile(cursor);
                return;
            default: return;
        }
        event.preventDefault();
        if (inside([x, y])) { cursor = [x, y]; draw(); }
    }, {signal});
    dialog.addEventListener('keydown', event => {
        event.stopPropagation();
        if (!(event.target instanceof HTMLInputElement) && (event.ctrlKey || event.metaKey) &&
            ['z', 'y'].includes(event.key.toLowerCase())) {
            event.preventDefault();
            history(event.key.toLowerCase() === 'z' && !event.shiftKey);
        }
    }, {signal});
    playtestBar.addEventListener('keydown', event => {
        if (event.key === 'Escape') { event.preventDefault(); returnToEditor(); }
    }, {signal});
    dialog.addEventListener('cancel', event => { event.preventDefault(); closeEditor(); }, {signal});
    signal.addEventListener('abort', () => {
        if (isOpen()) dialog.close();
        playtestBar.hidden = true;
        state.levelEditor = undefined;
    }, {once: true});
    state.levelEditor = {open: openEditor, isOpen, returnFromPlaytest: returnToEditor};
}
