import type { Animator,LightSourceAnimation,SpriteAnimation } from '../animation';
import type { Cell,Item,Player } from '../world/game-map';
import type { GuardData as Guard } from '../world/guard';

type PlayerVisuals = {
    animation: SpriteAnimation | null;
    torchAnimation: LightSourceAnimation | null;
    noisyAnim: number;
    idle: boolean;
    idleCursorAnimation: Animator[] | null;
    idleCursorType: 'orbs' | 'off';
};

type GuardVisuals = {
    animation: SpriteAnimation | null;
    torchAnimation: LightSourceAnimation | null;
};

export class WorldVisuals {
    cellAnimations = new WeakMap<Cell, Animator>();
    cellLight = new WeakMap<Cell, number>();
    itemAnimations = new WeakMap<Item, Animator>();
    private players = new WeakMap<Player, PlayerVisuals>();
    private guards = new WeakMap<Guard, GuardVisuals>();
    speaker?: Guard;

    resetMap() {
        this.players = new WeakMap();
        this.cellAnimations = new WeakMap();
        this.cellLight = new WeakMap();
        this.itemAnimations = new WeakMap();
        this.guards = new WeakMap();
        this.speaker = undefined;
    }

    player(actor: Player): PlayerVisuals {
        let visuals = this.players.get(actor);
        if (!visuals) {
            visuals = {
                animation: null,
                torchAnimation: null,
                noisyAnim: 0,
                idle: false,
                idleCursorAnimation: null,
                idleCursorType: 'orbs',
            };
            this.players.set(actor, visuals);
        }
        return visuals;
    }

    guard(actor: Guard): GuardVisuals {
        let visuals = this.guards.get(actor);
        if (!visuals) {
            visuals = { animation: null, torchAnimation: null };
            this.guards.set(actor, visuals);
        }
        return visuals;
    }
}
