import { vec2 } from '../my-matrix';
import { RNG } from '../random';
import type { LevelSpec } from '../run/state';
import { CellGrid,LevelType,type GameMap } from '../world/game-map';
import { FloorId, type Mansion } from '../world/mansion';
import { RoomType, type Room } from '../world/room-graph';
import type { ItemType } from '../world/tiles';
import { cacheCellInfo } from '../world/mutations';
import { blocksOrdinaryStep, canLeapOntoItemType, connectsWallTile, isClimbableItem, isDoorItemType, isGateTerrainType,
    isGroundTerrainType, isHingedDoorTerrainType, isLockedDoorItemType, isWallTerrainType, isWindowTerrainType, TerrainType } from '../world/tiles';
import { windowAllowsDirection } from '../world/traversal';
import { createGameMap } from './create-map';
import { isCourtyardRoomType } from './room-roles';
import { markExteriorAsSeen } from './population';
import { GenerationError } from './stages';
import { validateFinalMap } from './validation';
import { enclosedFloorTiles } from './world-building';

const directions = [[1, 0], [0, 1], [-1, 0], [0, -1]] as const;

type Story = {
    id: FloorId;
    map: GameMap;
    spec: LevelSpec;
    clearSites: Set<number>;
    blocked: Set<number>;
    dryRoutes: Set<number>;
    unlockedRoutes: Set<number>;
};

type GeneratedStory = {id: FloorId; map: GameMap; spec: LevelSpec};
type Layout = {rooms: string; walls: Set<string>};
const minWallDifference = 0.30;

export function createMultiFloorMansion(spec: LevelSpec, generateStory = createGameMap): Mansion {
    const ids = [FloorId.First, FloorId.Second];
    if (spec.difficulty >= 1) ids.push(FloorId.Basement);
    if (spec.difficulty >= 2) ids.push(FloorId.Third);
    if (spec.difficulty >= 3) ids.push(FloorId.Rooftop);

    const extraStories = ids.length - 1;
    const extraLoot = Math.min(Math.max(0, spec.totalLoot - 1), Math.max(extraStories, Math.round(spec.totalLoot * 0.45)));
    const groundSpec = {...spec, totalLoot: spec.totalLoot - extraLoot};

    for (let attempt = 0; attempt < 6; attempt++) {
        const ground = generateStory(groundSpec);
        const generated: GeneratedStory[] = [{id: FloorId.First, map: ground, spec: groundSpec}];
        const layouts = [describeLayout(ground)];
        for (const [index, id] of ids.slice(1).entries()) {
            const loot = Math.floor(extraLoot / extraStories) + Number(index < extraLoot % extraStories);
            const storySpec = {...spec, totalLoot: loot, seed: spec.seed + '/story/v4/' + id + '/' + attempt};
            const below = generated.find(story => story.id === id - 1)?.map;
            const story = generateDistinctStory(id, storySpec, layouts, generateStory, below);
            if (!story) break;
            generated.push(story);
        }
        if (generated.length !== ids.length) continue;

        const width = Math.max(...generated.map(({map}) => map.cells.sizeX));
        const height = Math.max(...generated.map(({map}) => map.cells.sizeY));
        for (const {id, map, spec} of generated) {
            padExterior(map, width, height, spec.levelType, id > FloorId.First);
        }
        const arranged = generated.map(({id, map, spec}) => planStory(id, map, spec));
        const connected = arranged.slice(1).every(story => {
            const parentId = story.id === FloorId.Basement ? FloorId.First : story.id - 1;
            const parent = arranged.find(candidate => candidate.id === parentId)!;
            return connectStories(parent, story, new RNG(story.spec.seed + '/ladder'));
        });
        if (!connected) continue;

        for (const story of arranged) finishStory(story);
        return {floors: arranged.sort((a, b) => a.id - b.id).map(({id, map}) => ({id, map}))};
    }
    throw new Error('Unable to generate distinct stories with aligned ladders in ' + spec.seed);
}

function generateDistinctStory(id: FloorId, spec: LevelSpec, layouts: Layout[], generateStory: typeof createGameMap,
    below?: GameMap): GeneratedStory | undefined {
    let fallback: GeneratedStory | undefined;
    for (let variant = 0; variant < 12; variant++) {
        const seededSpec = {...spec, seed: spec.seed + '/' + variant};
        let map: GameMap;
        try {
            map = generateStory(seededSpec, {openExterior: id > FloorId.First});
        } catch (error) {
            if (!(error instanceof GenerationError)) throw error;
            continue;
        }
        const layout = describeLayout(map);
        if (layouts.every(previous => isDistinctLayout(previous, layout))) {
            const story = {id, map, spec: seededSpec};
            if (below && !addStoryRoofs(below, map, spec.levelType)) {
                fallback ??= story;
                continue;
            }
            layouts.push(layout);
            return story;
        }
    }
    // Some footprints leave no room for a walkable roof beside the upstairs rooms.
    if (fallback) layouts.push(describeLayout(fallback.map));
    return fallback;
}

function describeLayout({rooms, cells}: GameMap): Layout {
    const walls = new Set<string>();
    for (const [index, cell] of cells.values.entries()) {
        if (connectsWallTile(cell.type)) walls.add((index % cells.sizeX) + ',' + Math.floor(index / cells.sizeX));
    }
    return {
        rooms: rooms.map(room => [...room.posMin, ...room.posMax].join(',')).sort().join(';'),
        walls,
    };
}

function isDistinctLayout(a: Layout, b: Layout): boolean {
    if (a.rooms === b.rooms) return false;
    let shared = 0;
    for (const pos of a.walls) if (b.walls.has(pos)) shared++;
    return a.walls.size + b.walls.size - 2 * shared >= minWallDifference * Math.max(a.walls.size, b.walls.size);
}

function padExterior(map: GameMap, width: number, height: number, levelType: LevelType, openExterior: boolean) {
    const original = map.cells;
    if (original.sizeX === width && original.sizeY === height) return;
    const cells = new CellGrid(width, height);
    if (levelType === LevelType.Warrens) {
        for (const cell of cells.values) cell.type = TerrainType.GroundNormal;
    }
    // Generation anchors the building at the southwest border. Extend the exterior from that origin.
    const openings = new Set<number>();
    for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        const index = cells.index(x, y);
        if (original.contains(x, y)) {
            cells.values[index] = original.at(x, y);
            if (map.openings.has(original.index(x, y))) openings.add(index);
        } else if (openExterior) {
            openings.add(index);
        }
    }
    map.cells = cells;
    map.openings.clear();
    for (const index of openings) map.openings.add(index);
    cacheCellInfo(map);
    if (!openExterior && levelType !== LevelType.Warrens) {
        map.numPreRevealedCells = 0;
        markExteriorAsSeen(map);
    }
    map.recomputeVisibility(map.playerStartPos);
}

function addStoryRoofs(below: GameMap, above: GameMap, levelType: LevelType): boolean {
    const lower = below.cells;
    padExterior(above, Math.max(lower.sizeX, above.cells.sizeX),
        Math.max(lower.sizeY, above.cells.sizeY), levelType, true);
    const enclosed = new Set<Room>();
    for (const {roomLeft, roomRight} of below.adjacencies) {
        for (const room of [roomLeft, roomRight]) {
            if (room.roomType !== RoomType.Exterior && !isCourtyardRoomType(room.roomType)) enclosed.add(room);
        }
    }
    const covered = enclosedFloorTiles(lower, enclosed, below.adjacencies);
    for (const [index, cell] of lower.values.entries()) {
        if (connectsWallTile(cell.type)) covered.add(index);
    }

    const {cells} = above;
    const roofs = new Set<number>();
    for (const tile of covered) {
        // An exposed terrace already has its roof at the lower story's height.
        if (below.openings.has(tile) || lower.values[tile].type === TerrainType.GroundRoof) continue;
        const index = cells.index(tile % lower.sizeX, Math.floor(tile / lower.sizeX));
        if (!above.openings.delete(index)) continue;
        cells.values[index].type = TerrainType.GroundRoof;
        roofs.add(index);
    }
    if (roofs.size === 0) return false;
    cacheCellInfo(above);

    const reachable = new Set(roundTripCells(above, new Set()).map(pos => cells.indexVec(pos)));
    const windows = roofWindowSites(above, reachable);
    let walkableRoof = false;
    for (const start of roofs) {
        const section = [start];
        roofs.delete(start);
        for (const index of section) {
            const x = index % cells.sizeX, y = Math.floor(index / cells.sizeX);
            for (const [dx, dy] of directions) {
                if (!cells.contains(x + dx, y + dy)) continue;
                const next = cells.index(x + dx, y + dy);
                if (roofs.delete(next)) section.push(next);
            }
        }

        const connected = section.some(index => reachable.has(index));
        const window = connected ? undefined : section.map(index => windows.get(index)).find(site => site !== undefined);
        if (window) cells.values[window.index].type = window.type;
        if (section.length > 1 && (connected || window)) walkableRoof = true;
    }
    cacheCellInfo(above);
    return walkableRoof;
}

function roofWindowSites({cells, adjacencies}: GameMap, reachable: ReadonlySet<number>) {
    const sites = new Map<number, {index: number; type: TerrainType}>();
    for (const {roomLeft, roomRight, origin, dir, length} of adjacencies) {
        const outsideLeft = roomLeft.roomType === RoomType.Exterior;
        const outsideRight = roomRight.roomType === RoomType.Exterior;
        if (outsideLeft === outsideRight || roomLeft.roomType === RoomType.Vault || roomRight.roomType === RoomType.Vault) continue;
        const dx = outsideLeft ? -dir[1] : dir[1];
        const dy = outsideLeft ? dir[0] : -dir[0];
        const type = dx > 0 ? TerrainType.OneWayWindowE : dx < 0 ? TerrainType.OneWayWindowW :
            dy > 0 ? TerrainType.OneWayWindowN : TerrainType.OneWayWindowS;
        for (let i = 1; i < length; i++) {
            const x = origin[0] + i * dir[0], y = origin[1] + i * dir[1];
            if (!cells.contains(x + dx, y + dy) || !cells.contains(x - dx, y - dy)) continue;
            if (!isWallTerrainType(cells.at(x, y).type) || cells.at(x + dx, y + dy).type !== TerrainType.GroundRoof) continue;
            const inner = cells.at(x - dx, y - dy);
            if (!isGroundTerrainType(inner.type) || inner.type === TerrainType.GroundRoof ||
                inner.moveCost !== 0 || !reachable.has(cells.index(x - dx, y - dy))) continue;
            sites.set(cells.index(x + dx, y + dy), {index: cells.index(x, y), type});
        }
    }
    return sites;
}

function planStory(id: FloorId, map: GameMap, spec: LevelSpec): Story {
    const {cells} = map;
    const occupied = new Set(map.items.map(item => cells.indexVec(item.pos)));
    for (const guard of map.guards) for (const [index, at] of guard.patrolPath.entries()) {
        const next = guard.patrolPath[(index + 1) % guard.patrolPath.length];
        occupied.add(cells.indexVec(at));
        if (at[0] !== next[0] && at[1] !== next[1]) {
            occupied.add(cells.index(at[0], next[1]));
            occupied.add(cells.index(next[0], at[1]));
        }
    }
    occupied.add(cells.indexVec(map.playerStartPos));
    const blocked = new Set<number>();
    const dry = roundTripCells(map, blocked);
    const clearSites = new Set(dry.filter(([x, y]) =>
        x > 0 && y > 0 && x < cells.sizeX - 1 && y < cells.sizeY - 1 &&
        isGroundTerrainType(cells.at(x, y).type) && cells.at(x, y).type !== TerrainType.GroundRoof &&
        cells.at(x, y).moveCost === 0 &&
        !occupied.has(cells.index(x, y))).map(pos => cells.indexVec(pos)));
    return {
        id, map, spec, clearSites, blocked,
        dryRoutes: new Set(dry.map(pos => cells.indexVec(pos))),
        unlockedRoutes: new Set(roundTripCells(map, blocked, true).map(pos => cells.indexVec(pos))),
    };
}

function preservesRoutes(story: Story): boolean {
    const {map, blocked} = story;
    function remaining(routes: Set<number>): number {
        let count = routes.size;
        for (const index of blocked) if (routes.has(index)) count--;
        return count;
    }
    // The chosen ladder tiles are automatically left, so the regular routes have to go around them.
    return roundTripCells(map, blocked).length === remaining(story.dryRoutes) &&
        roundTripCells(map, blocked, true).length === remaining(story.unlockedRoutes);
}

function connectStories(a: Story, b: Story, rng: RNG): boolean {
    const {sizeX: width} = a.map.cells;
    const sites = [...a.clearSites].filter(index => b.clearSites.has(index));
    rng.shuffleArray(sites);
    const isOutside = (story: Story, index: number) => {
        const type = story.map.cells.values[index].type;
        return type === TerrainType.GroundGrass || type === TerrainType.GroundNormal;
    };
    sites.sort((x, y) => Number(isOutside(a, x)) + Number(isOutside(b, x)) -
        Number(isOutside(a, y)) - Number(isOutside(b, y)));
    for (const index of sites) {
        const x = index % width, y = Math.floor(index / width);
        const clear = (story: Story) => story.map.stairs.every(stair =>
            Math.abs(stair.pos[0] - x) + Math.abs(stair.pos[1] - y) > 2);
        if (!clear(a) || !clear(b)) continue;
        const beside = (story: Story) => directions
            .map(([dx, dy]) => vec2.fromValues(x + dx, y + dy))
            .find(pos => story.clearSites.has(story.map.cells.indexVec(pos)) && !story.blocked.has(story.map.cells.indexVec(pos)));
        const arrivesA = beside(a), arrivesB = beside(b);
        if (!arrivesA || !arrivesB) continue;
        a.blocked.add(index);
        b.blocked.add(index);
        if (preservesRoutes(a) && preservesRoutes(b)) {
            const pos = vec2.fromValues(x, y);
            a.map.stairs.push({pos, destination: b.id, arrival: arrivesA});
            b.map.stairs.push({pos: vec2.clone(pos), destination: a.id, arrival: arrivesB});
            return true;
        }
        a.blocked.delete(index);
        b.blocked.delete(index);
    }
    return false;
}

function finishStory({id, map, spec}: Story) {
    map.hasElevation = true;
    for (const {pos} of map.items.filter(item => isClimbableItem(item.type)).slice(0, 2)) {
        for (const [dx, dy] of directions) {
            const next = vec2.fromValues(pos[0] + dx, pos[1] + dy);
            if (map.cells.contains(next[0], next[1]) && !map.isOpening(next) && !map.isLadderSpace(next) &&
                isGroundTerrainType(map.cells.atVec(next).type) && map.cells.atVec(next).moveCost === 0) {
                map.platforms.add(map.cells.indexVec(next));
            }
        }
    }

    cacheCellInfo(map);
    if (id !== FloorId.First) {
        map.allowsEscape = false;
        if (id > FloorId.First) {
            map.markAllUnseen();
            map.numPreRevealedCells = 0;
            for (const cell of map.cells.values) {
                if (cell.type !== TerrainType.GroundRoof) continue;
                cell.seen = true;
                map.numPreRevealedCells++;
            }
        }
        map.playerStartPos = map.stairs[0].arrival!;
        map.recomputeVisibility(map.playerStartPos);
    }
    validateFinalMap(map, spec);
}

function roundTripCells(map: GameMap, blocked: ReadonlySet<number>, hasKey = false): vec2[] {
    const {cells} = map;
    const positions = [map.playerStartPos];
    const start = cells.indexVec(map.playerStartPos);
    const discovered = new Set<number>([start]);
    const fromCells = new Map<number, number[]>();
    const items = new Map<number, ItemType[]>();
    for (const item of map.items) {
        const index = cells.indexVec(item.pos);
        const types = items.get(index) ?? [];
        types.push(item.type);
        items.set(index, types);
    }
    function add(from: number, x: number, y: number, leap: boolean) {
        if (!cells.contains(x, y)) return;
        const index = cells.index(x, y);
        if (blocked.has(index)) return;
        const cell = cells.at(x, y);
        const types = items.get(index) ?? [];
        if (cell.blocksPlayerMove || isWindowTerrainType(cell.type) ||
            (!hasKey && (cell.type === TerrainType.GroundWater || types.some(isLockedDoorItemType)))) return;
        if (leap
            ? isGateTerrainType(cell.type) || types.some(type => !canLeapOntoItemType(type) || isDoorItemType(type))
            : types.some(blocksOrdinaryStep)) return;
        const previous = fromCells.get(index) ?? [];
        previous.push(from);
        fromCells.set(index, previous);
        if (discovered.has(index)) return;
        discovered.add(index);
        positions.push(vec2.fromValues(x, y));
    }
    for (const [x, y] of positions) {
        const from = cells.index(x, y);
        for (const [dx, dy] of directions) {
            const mid = cells.at(x + dx, y + dy);
            add(from, x + dx, y + dy, false);
            if (cells.contains(x + dx, y + dy) && cells.at(x,y).type !== TerrainType.GroundWater && !mid.blocksPlayerMove &&
                !map.openings.has(cells.index(x + dx, y + dy)) &&
                windowAllowsDirection(mid.type, dx, dy, cells.at(x,y).type) &&
                !(isHingedDoorTerrainType(mid.type) && items.get(cells.index(x + dx, y + dy))?.some(isDoorItemType))) {
                add(from, x + 2 * dx, y + 2 * dy, true);
            }
        }
    }
    // One-way windows can lead to landings you cannot return from.
    const returns = [start];
    const canReturn = new Set(returns);
    for (const cell of returns) {
        for (const previous of fromCells.get(cell) ?? []) {
            if (canReturn.has(previous)) continue;
            canReturn.add(previous);
            returns.push(previous);
        }
    }
    return positions.filter(pos => canReturn.has(cells.indexVec(pos)));
}
