import type { GameMap,Item } from './game-map';
import { guardMoveCostForItemType } from './game-map';
import { blocksGuardSight,blocksPlayerMovement,blocksPlayerSight,hidesPlayer,isWallTerrainType,isWindowTerrainType,TerrainType } from './tiles';

export function cacheCellInfo(map: GameMap) {
    let sx = map.cells.sizeX;
    let sy = map.cells.sizeY;

    for (let x = 0; x < sx; ++x) {
        for (let y = 0; y < sy; ++y) {
            const cell = map.cells.at(x, y);
            const cellType = cell.type;
            const opening = map.openings.has(map.cells.index(x, y));
            const isWall = isWallTerrainType(cellType);
            const isWindow = isWindowTerrainType(cellType);
            const isWater = cellType == TerrainType.GroundWater;
            cell.moveCost = (isWall || isWindow || opening) ? Infinity : (isWater ? 64 : 0);
            cell.blocksPlayerMove = isWall || opening;
            cell.blocksPlayerSight = isWall && cellType !== TerrainType.Wall0000;
            cell.blocksSight = isWall;
            cell.blocksSound = isWall;
            cell.hidesPlayer = false;
            cell.isWindow = isWindow;
        }
    }

    // Landings stay clear for arrivals and guard patrols route around them.
    for (const stair of map.stairs) {
        map.cells.atVec(stair.pos).moveCost = Infinity;
        if (stair.arrival) map.cells.atVec(stair.arrival).moveCost = Infinity;
    }

    for (const item of map.items) {
        let cell = map.cells.atVec(item.pos);
        let itemType = item.type;
        cell.moveCost = Math.max(cell.moveCost, guardMoveCostForItemType(itemType));
        if (blocksPlayerSight(itemType)) {
            cell.blocksPlayerSight = true;
        }
        if (blocksGuardSight(itemType)) {
            cell.blocksSight = true;
        }
        if (hidesPlayer(itemType)) {
            cell.hidesPlayer = true;
        }
        if (blocksPlayerMovement(itemType)) {
            cell.blocksPlayerMove = true;
        }
    }
}

export function removeWorldItems(map: GameMap, predicate: (item: Item) => boolean): Item[] {
    const removed = map.items.filter(predicate);
    if (removed.length) {
        map.items = map.items.filter(item => !removed.includes(item));
        cacheCellInfo(map);
    }
    return removed;
}

export function changeItemType(map: GameMap, item: Item, type: Item['type']) {
    item.type = type;
    cacheCellInfo(map);
}
