import { mansionRevealed } from '../world/mansion';
import { vec2 } from '../my-matrix';
import type { Player } from '../world/game-map';
import { isDoorItemType,isWindowTerrainType,ItemType,TerrainType } from '../world/game-map';
import type { GuardData as Guard } from '../world/guard';
import { isAlertGuard } from '../world/guard-policy';
import { isHingedDoorTerrainType } from '../world/tiles';
import { windowAllowsDirection } from '../world/traversal';
import { directionArrowCharacter,StepType } from './commands';
import { GuardMode } from './guards';
import {
bumpFail,canCollectLootAt,collectGuardLoot,collectLoot,isLockedDoorAtPos,
moveGuardToPlayerPos,pushOrSwapGuard,tryMoveAgainstBlockedSquare
} from './interactions';
import { canLeapToPos,canStepToPos,resolveElevatedMove,resolveLeapDrop } from './movement-rules';
import { makeNoise,NoiseType } from './noise';
import type { SimulationState } from './state';
import { advanceTime,moveToFloor,preTurn,showDeadNotification } from './turn';
export { canLeapToPos,canStepToPos } from './movement-rules';

export function tryPlayerStep(state: SimulationState, dx: number, dy: number, stepType: StepType) {

    // Can't move if you're dead

    const player = state.player;
    if (player.health <= 0) {
        showDeadNotification(state);
        return;
    }

    if (player.elevated) {
        moveAtHeight(state, dx, dy, false);
        return;
    }

    if (stepType !== StepType.AttemptedLeap) {
        player.preNoisy = false;
    }

    state.feedback?.beginAction();

    // Get the player's current position and new position

    const posOld = vec2.clone(player.pos);
    const posNew = vec2.fromValues(player.pos[0] + dx, player.pos[1] + dy);

    // Trying to move off the map?

    if (posNew[0] < 0 || posNew[0] >= state.gameMap.cells.sizeX ||
        posNew[1] < 0 || posNew[1] >= state.gameMap.cells.sizeY) {

        if (!state.gameMap.allowsEscape) {
            state.feedback?.notify('Leave from the\nfirst floor', player.pos);
            bumpFail(state, dx, dy);
        } else if (!state.gameMap.canEscapeFrom(posOld)) {
            state.feedback?.notify('Use a marked exit', player.pos);
            bumpFail(state, dx, dy);
        } else if (!state.finishedLevel) {
            if (mansionRevealed(state) < 1) {
                state.feedback?.notify('Map and loot\nbefore leaving', state.player.pos);
            } else {
                state.feedback?.notify('Collect all loot\nbefore leaving', state.player.pos);
            }
            bumpFail(state, dx, dy);
        } else {
            preTurn(state);
            state.turnHooks?.escape();

            state.feedback?.exitStep(posOld, posNew, dx, dy);
        }
        return;
    }

    // Trying to move into solid terrain?

    const cellNew = state.gameMap.cells.atVec(posNew);
    if (cellNew.blocksPlayerMove) {
        if (canCollectLootAt(state, posNew)) {
            preTurn(state);
            collectLoot(state, posNew, player.pos);
            player.interactionTarget = null;
            state.feedback?.bump(dx, dy);
            advanceTime(state);
        } else {
            if (stepType === StepType.Normal && state.gameMap.items.some(item => item.type === ItemType.TreasureLock && item.pos.equals(posNew))) {
                state.feedback?.notify('Locked!', state.player.pos);
            }
            tryMoveAgainstBlockedSquare(state, dx, dy, stepType);
        }
        return;
    }

    // Trying to go through the wrong way through a one-way window?

    if (!windowAllowsDirection(cellNew.type, dx, dy, state.gameMap.cells.atVec(posOld).type)) {

        state.feedback?.notify('Window is\nimpassable\nfrom here', state.player.pos);

        if (state.gameMapRoughPlans[state.level].difficulty === 0) {
            state.feedback?.delaySound('tooHigh', 0.3, 250);
        }

        tryMoveAgainstBlockedSquare(state, dx, dy, stepType);
        return;
    }

    // Trying to move into a one-way window instead of leaping through?

    if (isWindowTerrainType(cellNew.type)) {
        setLeapStatusMessage(state, dx, dy);

        if (state.gameMapRoughPlans[state.level].difficulty === 0) {
            state.feedback?.delaySound('jump', 0.3, 250);
        }

        bumpFail(state, dx, dy);
        return;
    }

    // Trying to move into an item that blocks movement?

    for (const item of state.gameMap.items.filter((item) => item.pos.equals(posNew))) {
        switch (item.type) {
        case ItemType.DrawersShort:
        case ItemType.VaultTreasureBox:
        case ItemType.EmptyVaultTreasureBox:
        case ItemType.LootedVaultTreasureBox:
        case ItemType.TreasurePlinth:
            if (canCollectLootAt(state, posNew)) {
                preTurn(state);
                collectLoot(state, posNew, player.pos);
                player.interactionTarget = null;
                state.feedback?.bump(dx, dy);
                advanceTime(state);
            } else {
                if (canLeapToPos(state, vec2.fromValues(posOld[0] + 2*dx, posOld[1] + 2*dy))) {
                    setLeapStatusMessage(state, dx, dy);
                } else {
                    tryMoveAgainstBlockedSquare(state, dx, dy, stepType);
                }
            }
            return;

        case ItemType.TorchUnlit:
            preTurn(state);
            state.feedback?.sound('ignite', 0.08);
            item.type = ItemType.TorchLit;
            player.interactionTarget = null;
            player.itemUsed = item;
            state.feedback?.bump(dx, dy);
            advanceTime(state);
            return;

        case ItemType.TorchLit:
            preTurn(state);
            state.feedback?.sound('douse', 0.05);
            item.type = ItemType.TorchUnlit;
            player.interactionTarget = null;
            player.itemUsed = item;
            state.feedback?.bump(dx, dy);
            advanceTime(state);
            return;

        case ItemType.PortcullisEW:
        case ItemType.PortcullisNS:
            if (stepType !== StepType.AttemptedLeap) {
                setLeapStatusMessage(state, dx, dy);
            }
            state.feedback?.sound('gate', 0.3);
            if (state.gameMapRoughPlans[state.level].difficulty === 0) {
                state.feedback?.delaySound('jump', 0.3, 1000);
            }
            state.feedback?.bump(dx, dy);
            return;

        case ItemType.LockedDoorEW:
        case ItemType.LockedDoorNS:
            if (!player.hasVaultKey) {
                if (stepType === StepType.Normal) {
                    state.feedback?.notify('Locked!', state.player.pos);
                }
                tryMoveAgainstBlockedSquare(state, dx, dy, stepType);
                return;
            }
            break;
        }
    }

    // Trying to move onto a guard?

    const guard = state.gameMap.guards.find((guard) => guard.pos.equals(posNew));
    if (guard === undefined) {
        preTurn(state);
        player.interactionTarget = null;
    } else if (guard.mode === GuardMode.Unconscious) {
        preTurn(state);
        player.interactionTarget = null;
        pushOrSwapGuard(state, guard);
    } else if (guard.mode === GuardMode.ChaseVisibleTarget) {
        bumpFail(state, dx, dy);
        return;
    } else {
        preTurn(state);
        let needGuardLootCollect = false;
        if (guard.hasPurse || guard.hasVaultKey) {
            // If we have already targeted this guard, pick their pocket; otherwise target them
            if ((player.interactionTarget?.kind === 'guard' && player.interactionTarget.guard === guard)) {
                needGuardLootCollect = true;
            } else {
                player.interactionTarget = {kind:'guard',guard};
            }
        }

        // If the guard is stationary, pass time in place
        if (!guard.allowsMoveOntoFrom(player.pos)) {
            if(needGuardLootCollect) collectGuardLoot(state, player, guard, posOld);
            advanceTime(state);
            state.feedback?.tutorial(posOld);
            return;
        }
        if(needGuardLootCollect) collectGuardLoot(state, player, guard, posNew);
    }

    // Execute the move
    const fromCrouch = player.hidden(state.gameMap) || state.gameMap.cells.atVec(player.pos).type === TerrainType.GroundWater;

    vec2.copy(player.pos, posNew);
    ++state.numStepMoves;

    // Identify creaky floors nearby

    state.gameMap.identifyAdjacentCells(player.pos);

    const crouch = player.hidden(state.gameMap) || cellNew.type === TerrainType.GroundWater;
    state.feedback?.step(posOld, posNew, dx, dy, fromCrouch, crouch,
        guard?.mode === GuardMode.Unconscious, stepType === StepType.AttemptedLeapBounceBack);

    // Collect loot

    collectLoot(state, player.pos, posNew);

    // Generate movement AI noises

    if (cellNew.type === TerrainType.GroundWoodCreaky) {
        makeNoise(state, NoiseType.Creak, 0, -1);
    }

    // Let guards take a turn

    advanceTime(state);

    // Hints

    state.feedback?.tutorial(posOld);

    // Play sound for terrain type changes

    state.feedback?.movementSound(state.gameMap.cells.atVec(posOld), cellNew);
}

function moveAtHeight(state: SimulationState, dx: number, dy: number, leap: boolean) {
    const move = resolveElevatedMove(state, state.player.pos, true, dx, dy, leap);
    if (move) {
        moveVertically(state, move.to, dx, dy, move.elevated, move.leap);
    } else {
        state.feedback?.beginAction();
        bumpFail(state, dx, dy);
    }
}

function moveVertically(state: SimulationState, to: vec2, dx: number, dy: number, high: boolean, leap: boolean) {
    const {player, gameMap} = state;
    const from = vec2.clone(player.pos);
    state.feedback?.beginAction();
    preTurn(state);
    player.interactionTarget = null;
    player.elevated = high;
    vec2.copy(player.pos, to);
    gameMap.identifyAdjacentCells(to);
    if (leap) {
        ++state.numLeapMoves;
        const via = vec2.fromValues((from[0] + to[0]) / 2, (from[1] + to[1]) / 2);
        state.feedback?.leap(from, to, via, dx, dy, player.hidden(gameMap), false);
    } else {
        ++state.numStepMoves;
        state.feedback?.step(from, to, dx, dy, false, player.hidden(gameMap), false, false);
    }
    if (!high) {
        collectLoot(state, to, to);
        const type = gameMap.cells.atVec(to).type;
        if (type === TerrainType.GroundWoodCreaky) makeNoise(state, NoiseType.Creak, 0, -1);
        else if (type === TerrainType.GroundWater) makeNoise(state, NoiseType.Splash, 0, 0);
    }
    advanceTime(state);
    if (!high) state.feedback?.movementSound(gameMap.cells.atVec(from), gameMap.cells.atVec(to));
}

export function tryPlayerLeap(state: SimulationState, dx: number, dy: number) {

    // Can't move if you're dead

    const player = state.player;
    if (player.health <= 0) {
        showDeadNotification(state);
        return;
    }

    if (tryLeapDrop(state, dx, dy)) return;

    if (player.elevated) {
        moveAtHeight(state, dx, dy, true);
        return;
    }
    const climb = resolveElevatedMove(state, player.pos, false, dx, dy, true);
    if (climb) {
        moveVertically(state, climb.to, dx, dy, true, true);
        return;
    }

    state.feedback?.beginAction();

    // Get the player's current position and new position, and the middle position between them

    const posOld = vec2.clone(player.pos);
    const posMid = vec2.fromValues(player.pos[0] + dx, player.pos[1] + dy);
    const posNew = vec2.fromValues(player.pos[0] + 2*dx, player.pos[1] + 2*dy);

    const cellOld = state.gameMap.cells.atVec(posOld)
    const cellMid = state.gameMap.cells.atVec(posMid);
    const cellNew = state.gameMap.cells.atVec(posNew);

    // If an unaware guard is adjacent in the leap direction, knock them unconscious

    const guardMid = state.gameMap.guards.find((guard) =>
        guard.pos.equals(posMid) &&
        guard.mode !== GuardMode.Unconscious);

    if (guardMid) {
        if (cellMid.type===TerrainType.PortcullisEW ||
            cellMid.type===TerrainType.PortcullisNS ||
            (!player.hasVaultKey && isLockedDoorAtPos(state.gameMap, posMid))) {
            //Can't attack or leap over a guard on a portcullis
            tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
            return;
        } else if (guardMid.mode === GuardMode.ChaseVisibleTarget) {
            // Swap places with the guard
            if (!state.gameMap.isLadderSpace(player.pos)) moveGuardToPlayerPos(state, guardMid);
            tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        } else {
            preTurn(state);

            guardMid.mode = GuardMode.Unconscious;
            guardMid.modeTimeout = Math.max(1, 40 - 2*state.level) + state.rng.randomInRange(20);
            if (guardMid.hasPurse || guardMid.hasVaultKey) {
                collectGuardLoot(state, player, guardMid, posOld);
            }
            player.interactionTarget = null;
            ++state.levelStats.numKnockouts;
            state.feedback?.sound('hitGuard', 0.25);

            advanceTime(state);

            state.feedback?.bump(dx, dy);

            state.feedback?.jolt(dx, dy);
        }
        return;
    }

    // If player is in water, downgrade to a step

    if (cellOld.type === TerrainType.GroundWater) {
        tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        return;
    }

    // If the endpoint is off the map, downgrade to a step

    if (posNew[0] < 0 ||
        posNew[1] < 0 ||
        posNew[0] >= state.gameMap.cells.sizeX ||
        posNew[1] >= state.gameMap.cells.sizeY) {
        tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        return;
    }

    // If the midpoint is a wall, downgrade to a step

    if (cellMid.blocksPlayerMove) {
        tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        return;
    }

    // If the midpoint is a door, downgrade to a step

    if (isHingedDoorTerrainType(cellMid.type) &&
        state.gameMap.items.find((item)=>item.pos.equals(posMid) && isDoorItemType(item.type))) {
        tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        return;
    }

    // If the midpoint is a one-way window but is the wrong way, downgrade to a step

    if (!windowAllowsDirection(cellMid.type, dx, dy, cellOld.type)) {
        tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        return;
    }

    // If the leap destination is blocked, try a step if it can succeeed; else fail

    const canStepToMid = canStepToPos(state, posMid);

    const guard = state.gameMap.guards.find((guard) => guard.pos.equals(posNew));
    if (!canLeapToPos(state, posNew)) {
        if (canStepToMid) {
            if (guard !== undefined &&
                isAlertGuard(guard) &&
                cellNew.type !== TerrainType.PortcullisEW &&
                cellNew.type !== TerrainType.PortcullisNS &&
                (player.hasVaultKey || !isLockedDoorAtPos(state.gameMap, posNew))) {
                // Leaping attack: An alert guard at posNew will be KO'd and looted with player landing at posMid
                executeLeapAttack(state, player, guard, dx, dy, posOld, posMid, posNew);
            } else {
                tryPlayerStep(state, dx, dy, StepType.AttemptedLeapBounceBack);
            }
        } else {
            tryPlayerStep(state, dx, dy, StepType.AttemptedLeap);
        }
        return;
    }

    // Handle a guard at the endpoint
    if (guard === undefined || !(guard.hasPurse || guard.hasVaultKey)) {
        player.interactionTarget = null;
    } else {
        player.interactionTarget = {kind:'guard',guard};
    }

    // Execute the leap

    preTurn(state);

    // Collect any loot from posMid

    collectLoot(state, posMid, posNew);

    // Extinguish torch at posMid

    const torchMid = state.gameMap.items.find((item)=>item.pos.equals(posMid) && item.type === ItemType.TorchLit);
    if (torchMid !== undefined) {
        state.feedback?.sound('douse', 0.05);
        torchMid.type = ItemType.TorchUnlit;
        player.itemUsed = torchMid;
    } else if (canStepToMid && cellMid.type !== TerrainType.GroundWoodCreaky) {
        ++state.levelStats.steppableLeaps;
    }

    // Update player position

    vec2.copy(player.pos, posNew);
    ++state.numLeapMoves;

    // Identify creaky floor under player
    cellNew.identified = true;

    state.feedback?.leap(posOld, posNew, posMid, dx, dy, player.hidden(state.gameMap), false);

    const jumpedGate = cellMid.type === TerrainType.PortcullisNS || cellMid.type === TerrainType.PortcullisEW;
    if (jumpedGate) {
        state.hasEnteredMansion = true;
    } else if (state.gameMapRoughPlans[state.level].difficulty === 0 && !state.hasEnteredMansion) {
        state.experiencedPlayer = true;
    }

    // Collect any loot from posNew

    collectLoot(state, posNew, posNew);

    // Generate movement AI noises

    /*
    if (state.gameMap.items.find((item)=>item.pos.equals(posNew) && item.type === ItemType.Chair)) {
        makeNoise(state, NoiseType.BangChair, 0, 0);
    } else
    */
    if (cellNew.type === TerrainType.GroundWoodCreaky) {
        makeNoise(state, NoiseType.Creak, 0, -1);
    } else if (cellNew.type === TerrainType.GroundWater) {
        makeNoise(state, NoiseType.Splash, 0, 0);
    }

    // Let guards take a turn

    advanceTime(state);

    // Hints

    state.feedback?.tutorial(posOld);

    // Play sound for terrain type changes

    state.feedback?.movementSound(state.gameMap.cells.atVec(posOld), cellNew);

    if (jumpedGate) {
        state.feedback?.sound('gate', 0.3);
    }
}

function tryLeapDrop(state: SimulationState, dx: number, dy: number): boolean {
    const {player} = state;
    const drop = resolveLeapDrop(state, dx, dy);
    if (!drop) return false;

    state.feedback?.beginAction();
    if (!drop.landing) {
        state.feedback?.notify('No clear landing below', player);
        bumpFail(state, dx, dy);
        return true;
    }

    preTurn(state);
    const {floor, pos, stories, elevated} = drop.landing;
    moveToFloor(state, floor, pos, elevated);
    ++state.numLeapMoves;
    const water = !elevated && floor.map.cells.atVec(pos).type === TerrainType.GroundWater;
    const damage = Math.min(player.health, Math.max(0, Math.floor(stories) - Number(water)));
    state.feedback?.fall(dx, dy, stories);
    if (!water) state.feedback?.sound('thump', 0.5);
    makeNoise(state, water ? NoiseType.Splash : NoiseType.Thud, 0, 0);
    if (damage > 0) {
        player.applyDamage(damage);
        state.levelStats.damageTaken += damage;
        for (let heart = player.health; heart < player.health + damage; heart++) state.feedback?.flashHeart(heart);
        state.feedback?.enlargeHealthBar();
        state.feedback?.jolt(0, -1);
    }
    if (player.health > 0 && !elevated) collectLoot(state, pos, pos);
    advanceTime(state);
    return true;
}

function executeLeapAttack(state: SimulationState, player:Player, target:Guard, dx:number, dy:number, posOld:vec2, posMid:vec2, posNew:vec2) {
    // Execute the leaping attack that will finish at posMid

    preTurn(state);

    // Collect any loot from posMid

    collectLoot(state, posMid, posNew);

    // Update player position

    vec2.copy(player.pos, posMid);
    ++state.numLeapMoves;

    target.mode = GuardMode.Unconscious;
    target.modeTimeout = Math.max(1, 40 - 2*state.level) + state.rng.randomInRange(20);
    if (target.hasPurse || target.hasVaultKey) {
        collectGuardLoot(state, player, target, posMid, 0.15);
    }
    player.interactionTarget = null;
    ++state.levelStats.numKnockouts;
    state.feedback?.sound('hitGuard', 0.25);

    // Identify creaky floor under player

    const cellMid = state.gameMap.cells.atVec(posMid);
    cellMid.identified = true;

    state.feedback?.leap(posOld, posMid, posNew, dx, dy, player.hidden(state.gameMap), true);

    // Generate movement AI noises

    if (cellMid.type === TerrainType.GroundWoodCreaky) {
        makeNoise(state, NoiseType.Creak, 0, -1);
    } else if (cellMid.type === TerrainType.GroundWater) {
        makeNoise(state, NoiseType.Splash, 0, 0);
    }

    state.feedback?.jolt(dx, dy);
    makeNoise(state, NoiseType.Thud, dx, dy);

    // Let guards take a turn

    advanceTime(state);

    // Play sound for terrain type changes

    state.feedback?.movementSound(state.gameMap.cells.atVec(posOld), cellMid);
}

export function setLeapStatusMessage(state: SimulationState, dx: number, dy: number) {
    state.feedback?.notify('Leap: Shift+' + directionArrowCharacter(dx, dy), state.player.pos);
}
